// MT-1E7B: database/init-db.js (fresh dev/test seed, via crearBaseline001EnConexion) nunca crea
// atlas_schema_migrations -- eso es responsabilidad exclusiva de adopt-legacy-baseline.js/
// provision-tenant-db.js (ver business-schema-baseline.js). Antes de MT-1E7B eso no importaba: el
// runtime legacy no exigia schema CURRENT para arrancar. El nuevo boot gate SI lo exige en ambos
// modos, asi que toda business DB de fixture producida por database/init-db.js debe declararse
// CURRENT explicitamente aca (en el test harness, sin tocar database/init-db.js ni el builder) para
// poder arrancar backend/server.js. Mismo contrato exacto (tabla + fila) que provision-tenant-db.js
// usa para un tenant nuevo real.
// Sincrono a proposito (spawnSync, mismo patron que database/init-db.js ya usa arriba): las
// ~120 call-sites existentes de bootstrapFreshTestDb()/bootstrapFreshRegisteredTenantDb() son
// sincronas y no-await en toda la suite -- convertir esta funcion en async forzaria tocar cada una
// de esas call-sites, un refactor masivo fuera de proposito para un fix de test harness.
// MT-1F5C1: aplica el catalogo REAL completo (baseline 001 + toda migration real posterior), no
// solo BUSINESS_MIGRATIONS[0] -- desde que existe una migration 002+ real, una fixture con solo el
// baseline en su historial clasificaria BEHIND (nunca CURRENT), y el boot gate rechazaria arrancar
// backend/server.js contra ella. El proceso hijo re-require-ea database/business-migrations.js (la
// MISMA autoridad real, nunca una copia) para poder invocar up(db) de cada migration real.
//
// MT-1F5C1-R1B: idempotente respecto de historial YA existente -- no asume mas una DB "en blanco".
// Si atlas_schema_migrations ya existe (caso: copia de SOURCE_DB, que trae el historial real y
// legitimo de database/guernica.db, congelado en 001 por la Real Guernica Rule), NO recrea la tabla
// (evita "table already exists") y sólo aplica -- via up(db), nunca hardcodeado -- las migrations
// del catalogo cuya sequence sea posterior a lo ya presente. Antes de continuar valida que el
// prefijo ya aplicado coincida exactamente con el catalogo real (mismo sequence+migrationId en el
// mismo orden); si no coincide, falla cerrado en vez de forzar un estado inconsistente. Para una DB
// en blanco (ninguna fila previa) el comportamiento es exactamente el de antes: crea la tabla y
// aplica el catalogo completo desde sequence=1.
function stamparHistorialBaselineActual(dbPath) {
  const businessMigrationsPath = path.join(ROOT, "database", "business-migrations.js");
  const script = `
    const sqlite3 = require("sqlite3").verbose();
    const { BUSINESS_MIGRATIONS } = require(${JSON.stringify(businessMigrationsPath)});
    function runQuery(db, sql, params = []) {
      return new Promise((resolve, reject) => {
        db.run(sql, params, function (error) { if (error) { reject(error); return; } resolve(this); });
      });
    }
    function allQuery(db, sql, params = []) {
      return new Promise((resolve, reject) => {
        db.all(sql, params, (error, rows) => { if (error) reject(error); else resolve(rows); });
      });
    }
    (async () => {
      const db = new sqlite3.Database(${JSON.stringify(dbPath)});
      try {
        const tablaExistente = await allQuery(db, "SELECT name FROM sqlite_master WHERE type='table' AND name='atlas_schema_migrations'");
        if (tablaExistente.length === 0) {
          await runQuery(db, \`CREATE TABLE atlas_schema_migrations (
            sequence INTEGER NOT NULL UNIQUE CHECK(sequence >= 1),
            migration_id TEXT PRIMARY KEY NOT NULL,
            applied_at TEXT NOT NULL
          )\`);
        }
        const yaAplicadas = await allQuery(db, "SELECT sequence, migration_id FROM atlas_schema_migrations ORDER BY sequence ASC");
        for (let i = 0; i < yaAplicadas.length; i++) {
          const esperada = BUSINESS_MIGRATIONS[i];
          const coincide = esperada
            && Number(yaAplicadas[i].sequence) === esperada.sequence
            && yaAplicadas[i].migration_id === esperada.migrationId;
          if (!coincide) {
            throw new Error(\`stamparHistorialBaselineActual: historial existente en \${${JSON.stringify(dbPath)}} no coincide con el catalogo real en la posicion \${i} (encontrado sequence=\${yaAplicadas[i].sequence} migration_id=\${yaAplicadas[i].migration_id})\`);
          }
        }
        for (const migracion of BUSINESS_MIGRATIONS) {
          if (migracion.sequence <= yaAplicadas.length) continue;
          if (migracion.sequence > 1) await migracion.up(db);
          await runQuery(
            db,
            "INSERT INTO atlas_schema_migrations (sequence, migration_id, applied_at) VALUES (?, ?, datetime('now'))",
            [migracion.sequence, migracion.migrationId]
          );
        }
        await new Promise((resolve, reject) => db.close((error) => { if (error) reject(error); else resolve(); }));
      } catch (error) {
        console.error(error.message);
        process.exitCode = 1;
      }
    })();
  `;
  const resultado = spawnSync(process.execPath, ["-e", script], { cwd: ROOT, encoding: "utf8" });
  if (resultado.error) {
    throw new Error(`stamparHistorialBaselineActual: no se pudo ejecutar: ${resultado.error.message}`);
  }
  if (resultado.status !== 0) {
    throw new Error(`stamparHistorialBaselineActual: fallo con status=${resultado.status}\n${resultado.stderr || resultado.stdout}`);
  }
}

// MT-1F5C1-R1B: unico punto de entrada para "copiar SOURCE_DB (database/guernica.db real, usado
// solo como fuente de lectura -- jamas se abre en escritura ni se le crea backup) y llevar la copia
// disposable a CURRENT". Reutiliza stamparHistorialBaselineActual() (ya idempotente respecto de
// historial existente) -- ninguna segunda autoridad de migracion dentro del harness, ningun 002
// hardcodeado: sigue automaticamente el catalogo real, crezca lo que crezca. Reemplaza el patron
// previo "fs.copyFileSync(SOURCE_DB, dbPath)" a secas, que dejaba el historial congelado en lo que
// sea que tenga hoy database/guernica.db en disco (001, por la Real Guernica Rule) y por eso
// clasificaba BEHIND en cuanto el catalogo crecio a 002 (ver MT-1F5C1-R1/R1A).
// MT-1F5C1-R1D: guard de autoproteccion -- mismo patron ya usado en bootstrapFreshRegisteredTenantDb()
// para el mismo riesgo -- antes de cualquier I/O. Si dbPath resolviera al mismo archivo que SOURCE_DB
// (database/guernica.db real), copyFileSync(SOURCE_DB, dbPath) copiaria el archivo sobre si mismo
// (comportamiento no garantizado por Node, con riesgo real de truncar/corromper la autoridad real).
// Ningun caller actual (los 43 usan tempDbPath()) dispara esto hoy -- el guard es pura defensa contra
// un futuro call-site equivocado, y falla cerrado ANTES de tocar el filesystem.
async function copiarSourceDbCurrent(dbPath) {
  if (path.resolve(dbPath) === path.resolve(SOURCE_DB)) {
    throw new Error("copiarSourceDbCurrent: dbPath no puede resolver a database/guernica.db real -- SOURCE_DB jamas puede ser destino de una fixture disposable");
  }
  fs.copyFileSync(SOURCE_DB, dbPath);
  stamparHistorialBaselineActual(dbPath);
  const estado = await verificarBusinessSchemaVersion(dbPath);
  if (estado.state !== "CURRENT") {
    throw new Error(`copiarSourceDbCurrent: la copia disposable de SOURCE_DB no quedo CURRENT (state=${estado.state})`);
  }
}

// MT-1A.1: camino de bootstrap "desde cero" para tests -- nunca copia database/guernica.db.
// Ejecuta database/init-db.js como proceso hijo (aislando conexion/lifecycle/module cache, igual
// que withServer ya hace con backend/server.js), apuntandolo via GUERNICA_DB_PATH a una ruta que
// SIEMPRE vive dentro de os.tmpdir().
function bootstrapFreshTestDb() {
  const dbPath = tempDbPath();
  const tmpRoot = path.resolve(os.tmpdir());
  const resuelto = path.resolve(dbPath);
  if (resuelto !== tmpRoot && !resuelto.startsWith(tmpRoot + path.sep)) {
    throw new Error(`bootstrapFreshTestDb: destino invalido (debe vivir en os.tmpdir()): ${resuelto}`);
  }
  if (fs.existsSync(dbPath)) fs.rmSync(dbPath, { force: true });

  const resultado = spawnSync(process.execPath, ["database/init-db.js"], {
    cwd: ROOT,
    env: { ...process.env, GUERNICA_DB_PATH: dbPath },
    encoding: "utf8"
  });
  if (resultado.error) {
    throw new Error(`bootstrapFreshTestDb: no se pudo ejecutar database/init-db.js: ${resultado.error.message}`);
  }
  if (resultado.status !== 0) {
    throw new Error(`bootstrapFreshTestDb: database/init-db.js termino con status=${resultado.status}\n${resultado.stderr || resultado.stdout}`);
  }
  if (!fs.existsSync(dbPath)) {
    throw new Error("bootstrapFreshTestDb: database/init-db.js termino OK pero no se creo el archivo esperado");
  }
  stamparHistorialBaselineActual(dbPath);
  return dbPath;
}

const REAL_ATLAS_CONTROL_DB = path.join(ROOT, "database", "atlas_control.db");

// MT-1D.2B: TEST-ONLY. resolveEmpresaDbPath (autoridad de canonicalizacion/anti-path-traversal de
// database/init-control-db.js) solo acepta paths registrados que resuelvan dentro de ROOT/database/
// -- una business DB en os.tmpdir() (como tempDbPath()/bootstrapFreshTestDb() generan) nunca puede
// registrarse como tenant DB real, asi que ningun test que necesite que el Central Boot Identity
// Gate compare paths exitosamente puede usar esas dos. Este helper crea una business DB efimera,
// completamente seedeada (mismo camino que bootstrapFreshTestDb: database/init-db.js como proceso
// hijo, nunca copia guernica.db), pero DIRECTAMENTE dentro de ROOT/database/, con nombre unico.
// bootstrapFreshTestDb() en si NO se toca -- el resto de la suite sigue usando os.tmpdir() sin
// cambios.
function bootstrapFreshRegisteredTenantDb() {
  const nombre = `tenant-test-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}.db`;
  const dbPath = path.join(ROOT, "database", nombre);

  if (path.resolve(dbPath) === path.resolve(SOURCE_DB)) {
    throw new Error("bootstrapFreshRegisteredTenantDb: el path generado coincide con database/guernica.db real");
  }
  if (path.resolve(dbPath) === path.resolve(REAL_ATLAS_CONTROL_DB)) {
    throw new Error("bootstrapFreshRegisteredTenantDb: el path generado coincide con database/atlas_control.db real");
  }
  if (fs.existsSync(dbPath)) fs.rmSync(dbPath, { force: true });

  const resultado = spawnSync(process.execPath, ["database/init-db.js"], {
    cwd: ROOT,
    env: { ...process.env, GUERNICA_DB_PATH: dbPath },
    encoding: "utf8"
  });
  if (resultado.error) {
    throw new Error(`bootstrapFreshRegisteredTenantDb: no se pudo ejecutar database/init-db.js: ${resultado.error.message}`);
  }
  if (resultado.status !== 0) {
    throw new Error(`bootstrapFreshRegisteredTenantDb: database/init-db.js termino con status=${resultado.status}\n${resultado.stderr || resultado.stdout}`);
  }
  if (!fs.existsSync(dbPath)) {
    throw new Error("bootstrapFreshRegisteredTenantDb: database/init-db.js termino OK pero no se creo el archivo esperado");
  }
  stamparHistorialBaselineActual(dbPath);
  return dbPath;
}

// Cleanup obligatorio para bootstrapFreshRegisteredTenantDb(): .db + los sidecar de WAL (-wal/-shm)
// que sqlite3 puede dejar en database/ si el proceso hijo no cerro en modo journal por defecto.
function limpiarTenantTestDb(dbPath) {
  for (const sufijo of ["", "-wal", "-shm"]) {
    fs.rmSync(`${dbPath}${sufijo}`, { force: true });
  }
}

async function withFreshTestDb(fn) {
  const dbPath = bootstrapFreshTestDb();
  try {
    await withServer(dbPath, (baseUrl) => fn(baseUrl, dbPath));
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

// QA-RUNSQL-CLOSE: db.close() sin esperar su callback dejaba que la Promise resolviera/rechazara
// antes de que el handle de SQLite se liberara realmente -- en Windows eso permitia que un
// fs.rmSync inmediatamente posterior (p.ej. en el finally de un test) chocara contra el archivo
// todavia bloqueado (EPERM). Ahora se espera el callback de cierre antes de resolver o rechazar.
// El error de la operacion SQL, si existe, tiene prioridad sobre un eventual error de cierre.
function runSql(dbPath, sql, params = []) {
  return new Promise((resolve, reject) => {
    const db = new sqlite3.Database(dbPath);
    db.run(sql, params, function (error) {
      const result = this;
      db.close((closeError) => {
        if (error) reject(error);
        else if (closeError) reject(closeError);
        else resolve(result);
      });
    });
  });
}

async function crearProductoParaReporteVentas(baseUrl, token, nombreBase, overrides = {}) {
  const sufijo = `${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const categoriaNombre = `TEST Reportes ${nombreBase} ${sufijo}`;
  const categoriaId = await crearCategoria(baseUrl, token, categoriaNombre);
  const nombre = `TEST Producto Reportes ${nombreBase} ${sufijo}`;
  const productoId = await crearProducto(baseUrl, token, {
    nombre,
    categoria: categoriaNombre,
    categoria_id: categoriaId,
    stock: 100,
    precio_venta: 100,
    ...overrides
  });
  return {
    categoriaId,
    productoId,
    nombre,
    precio: Number(overrides.precio_venta ?? 100)
  };
}

