      await registrarPago(baseUrl, token, {
        proveedor_id: proveedor.id,
        concepto: "TEST pago balance",
        monto_total: 80,
        tipo_pago: "efectivo",
        estado: "registrado",
        cuenta_cobro_id: cuentaEfectivo.id
      });

      const { response, data } = await requestJson(baseUrl, "GET", "/reportes/resumen", null, token);
