// MT-1C.1A-CLOSE: hardening #1 -- el archivo de control plane NO debe autocrearse si esta
// ausente (directorio existente, archivo inexistente): esto es distinto del caso anterior
// (directorio inexistente), y exige OPEN_READWRITE sin OPEN_CREATE en la apertura runtime.
async function testMT1CBridgeControlPlaneAusenteNoLoCrea() {
  const businessDbPath = bootstrapFreshTestDb();
  const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "atlas-control-ausente-"));
  const controlDbPathAusente = path.join(tmpDir, "atlas_control.db");
  try {
    if (!fs.existsSync(tmpDir)) throw new Error("el directorio temporal debe existir antes del test");
    if (fs.existsSync(controlDbPathAusente)) throw new Error("el archivo de control plane no debe existir antes del test");

    const localAdmin = (await allSql(businessDbPath, "SELECT id, password FROM usuarios WHERE usuario = ?", ["admin"]))[0];

    await withServer(businessDbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      const cambio = await requestJson(baseUrl, "PATCH", `/usuarios/${localAdmin.id}/password`, {
        password: "ArchivoAusente1", confirmar_password: "ArchivoAusente1"
      }, token);
      if (cambio.response.ok) throw new Error("archivo de control plane ausente deberia fallar con 503");
      assertEqual(cambio.response.status, 503, "archivo de control plane ausente debe responder 503");
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPathAusente,
      ATLAS_EMPRESA_SLUG: "guernica"
    });

    const localDespues = (await allSql(businessDbPath, "SELECT password FROM usuarios WHERE id = ?", [localAdmin.id]))[0];
    if (localDespues.password === localAdmin.password) {
      throw new Error("por orden authority-first, el local deberia haber cambiado igual");
    }

    if (fs.existsSync(controlDbPathAusente)) {
      throw new Error("el bridge NO debe crear atlas_control.db cuando el archivo esta ausente -- se creo por error");
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(tmpDir, { recursive: true, force: true });
  }
}

// MT-1C.1A-CLOSE: hardening #4 -- la conexion runtime del bridge debe activar
// PRAGMA foreign_keys=ON. Se prueba directamente contra el primitivo de apertura exportado
// (abrirControlDbBridge), que es el mismo que usa syncPasswordHash -- no se crea una API nueva
// solo para el test, se reutiliza la unica funcion de apertura que ya existe.
async function testMT1CBridgeAperturaActivaForeignKeys() {
  const controlDbPath = tempDbPath();
  try {
    const bootstrap = await bootstrapControlDb(controlDbPath, { seed: false });
    await closeControlDb(bootstrap);

    const db = await userControlBridge.abrirControlDbBridge(controlDbPath);
    try {
      const pragma = await getControlQuery(db, "PRAGMA foreign_keys");
      assertEqual(pragma.foreign_keys, 1, "la apertura runtime del bridge debe activar PRAGMA foreign_keys = ON");
    } finally {
      await closeControlDb(db);
    }
  } finally {
    fs.rmSync(controlDbPath, { force: true });
  }
}

// MT-1C.1A-CLOSE: hardening #6 -- actualizarPasswordUsuarioCentral debe verificar changes === 1
// y nunca reportar exito silencioso si el usuario central no existia. Probado directamente sobre
// el helper, sin servidor, para mantener el scope acotado (seccion 7).
async function testMT1CBridgeActualizarPasswordCentralHelper() {
  const controlDbPath = tempDbPath();
  try {
    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const placeholderHash = await bcrypt.hash("PlaceholderHelperTest1", 10);
      const usuarioCentral = await crearUsuarioCentral(controlDb, {
        nombre: "Helper Central Test",
        usuarioReferencia: "helper.central.test",
        passwordHash: placeholderHash,
        activo: 1
      });

      const nuevoHash = await bcrypt.hash("NuevoHashHelperTest1", 10);
      await actualizarPasswordUsuarioCentral(controlDb, usuarioCentral.id, nuevoHash);
      const despues = await getControlQuery(controlDb, "SELECT password_hash FROM usuarios WHERE id = ?", [usuarioCentral.id]);
      assertSame(despues.password_hash, nuevoHash, "el helper debe persistir exactamente el hash recibido en el usuario existente");

      let fallo = false;
      try {
        await actualizarPasswordUsuarioCentral(controlDb, usuarioCentral.id + 999999, await bcrypt.hash("NoDeberiaAplicarse1", 10));
      } catch (error) {
        fallo = true;
      }
      if (!fallo) throw new Error("actualizarPasswordUsuarioCentral debe rechazar un usuarioId inexistente (0 filas afectadas), no reportar exito silencioso");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(controlDbPath, { force: true });
  }
}

// MT-1C.1B: role + active bridge (dual-write local + usuario_empresas para rol/activo por
// empresa, sin tocar central.activo global). Auth sigue 100% legacy.

async function testMT1CBridgeRoleActiveOffPreservaLegacy() {
  const businessDbPath = bootstrapFreshTestDb();
  try {
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const usuarioLogin = `colaborador.roleoff.${Date.now()}`;
      const creado = await requestJson(baseUrl, "POST", "/usuarios", {
        nombre: "Colaborador Role Off TEST",
        usuario: usuarioLogin,
        password: "ColaboradorOff1",
        confirmar_password: "ColaboradorOff1",
        rol: "colaborador"
      }, tokenAdmin);
      if (!creado.response.ok) throw new Error(`crear usuario fallo: ${creado.data?.message || creado.response.status}`);
      const localId = creado.data.usuario.id;

      const put = await requestJson(baseUrl, "PUT", `/usuarios/${localId}`, {
        nombre: "Colaborador Role Off TEST",
        usuario: usuarioLogin,
        rol: "encargado",
        email: "",
        telefono: "",
        activo: true
      }, tokenAdmin);
      if (!put.response.ok) throw new Error(`PUT rol (bridge off) fallo: ${put.data?.message || put.response.status}`);
      assertSame(put.data.usuario.rol, "encargado", "bridge off debe seguir actualizando rol local normalmente");

      const patchEstado = await requestJson(baseUrl, "PATCH", `/usuarios/${localId}/estado`, { activo: false }, tokenAdmin);
      if (!patchEstado.response.ok) throw new Error(`PATCH estado (bridge off) fallo: ${patchEstado.data?.message || patchEstado.response.status}`);
      assertEqual(patchEstado.data.usuario.activo ? 1 : 0, 0, "bridge off debe seguir desactivando localmente");
    }, { ATLAS_USER_BRIDGE_MODE: "off" });
  } finally {
    fs.rmSync(businessDbPath, { force: true });
  }
}

// AUTH-SYNC-B2-S1A2B-PROFILE-GUARD: reemplaza a la vieja testMT1CBridgeShadowPutSincronizaRolYActivo
// -- el comportamiento que esa prueba verificaba (PUT sincronizando rol/activo a Control DB) es
// exactamente el que este checkpoint elimina deliberadamente. Se conserva el mismo escenario para
// dejar trazabilidad, invirtiendo la aserción: ahora debe rechazarse con 409 y NINGUNA base debe
// cambiar.
async function testMT1CBridgePutShadowRolActivoDiferentesRechaza409() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `bridge-rol-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Bridge Rol Test", dbPath: "guernica.db" });

    let localId;
    const usuarioLogin = `colaborador.rolshadow.${Date.now()}`;
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const creado = await requestJson(baseUrl, "POST", "/usuarios", {
        nombre: "Colaborador Rol Shadow TEST",
        usuario: usuarioLogin,
        password: "ColaboradorShadow1",
        confirmar_password: "ColaboradorShadow1",
        rol: "colaborador"
      }, tokenAdmin);
      if (!creado.response.ok) throw new Error(`crear usuario fallo: ${creado.data?.message || creado.response.status}`);
      localId = creado.data.usuario.id;
    });

    const placeholderHash = await bcrypt.hash("PlaceholderRol1", 10);
    const usuarioCentral = await crearUsuarioCentral(controlDb, {
      nombre: "Colaborador Rol Shadow TEST", usuarioReferencia: usuarioLogin, passwordHash: placeholderHash, activo: 1
    });
    const membership = await crearMembership(controlDb, {
      usuarioId: usuarioCentral.id, empresaId: empresa.id, usuarioLocalId: localId, rol: "colaborador", activo: 1
    });
    await closeControlDb(controlDb);

    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const put = await requestJson(baseUrl, "PUT", `/usuarios/${localId}`, {
        nombre: "Colaborador Rol Shadow TEST",
        usuario: usuarioLogin,
        rol: "encargado",
        email: "",
        telefono: "",
        activo: false
      }, tokenAdmin);
      assertEqual(put.response.status, 409, `PUT con rol/activo distintos en shadow debe rechazar 409: ${JSON.stringify(put.data)}`);
      assertSame(put.data?.acceso?.rol_rechazado, true, "debe reportar explicitamente el rechazo de rol");
      assertSame(put.data?.acceso?.activo_rechazado, true, "debe reportar explicitamente el rechazo de activo");
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPath,
      ATLAS_EMPRESA_SLUG: empresaSlug
    });

    const localDespues = (await allSql(businessDbPath, "SELECT nombre, rol, activo FROM usuarios WHERE id = ?", [localId]))[0];
    assertSame(localDespues.nombre, "Colaborador Rol Shadow TEST", "nombre local no debe cambiar tras un 409 (sin escritura parcial)");
    assertSame(localDespues.rol, "colaborador", "rol local NO debe cambiar tras el rechazo");
    assertEqual(Number(localDespues.activo), 1, "activo local NO debe cambiar tras el rechazo");

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const membershipDespues = await getControlQuery(controlDb, "SELECT rol, activo FROM usuario_empresas WHERE id = ?", [membership.id]);
      assertSame(membershipDespues.rol, "colaborador", "membership.rol NO debe tocarse -- PUT ya no sincroniza acceso");
      assertEqual(Number(membershipDespues.activo), 1, "membership.activo NO debe tocarse -- PUT ya no sincroniza acceso");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

// AUTH-SYNC-B2-S1A2C-STATE-GUARD: reemplaza a la vieja
// testMT1CBridgeShadowEstadoDesactivaYReactivaSinTocarRolNiCentral -- el comportamiento que esa
// prueba verificaba (PATCH estado aplicando y sincronizando activo a Control DB) es exactamente el
// que este checkpoint elimina deliberadamente. Se conserva el mismo escenario (admin activo,
// intento de desactivar y de reactivar) para dejar trazabilidad, invirtiendo la asercion: ambas
// solicitudes deben rechazarse con 409 y NINGUNA base debe cambiar, ni siquiera actualizado_en.
async function testMT1CBridgePatchEstadoShadowRechaza409SinTocarRolNiCentral() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `bridge-estado-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Bridge Estado Test", dbPath: "guernica.db" });

    let localId;
    const usuarioLogin = `colaborador.estadoshadow.${Date.now()}`;
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const creado = await requestJson(baseUrl, "POST", "/usuarios", {
        nombre: "Colaborador Estado Shadow TEST",
        usuario: usuarioLogin,
        password: "ColaboradorEstado1",
        confirmar_password: "ColaboradorEstado1",
        rol: "admin"
      }, tokenAdmin);
      if (!creado.response.ok) throw new Error(`crear usuario fallo: ${creado.data?.message || creado.response.status}`);
      localId = creado.data.usuario.id;
    });

    const placeholderHash = await bcrypt.hash("PlaceholderEstado1", 10);
    const usuarioCentral = await crearUsuarioCentral(controlDb, {
      nombre: "Colaborador Estado Shadow TEST", usuarioReferencia: usuarioLogin, passwordHash: placeholderHash, activo: 1
    });
    const membership = await crearMembership(controlDb, {
      usuarioId: usuarioCentral.id, empresaId: empresa.id, usuarioLocalId: localId, rol: "admin", activo: 1
    });
    await closeControlDb(controlDb);

    const antes = (await allSql(businessDbPath, "SELECT activo, actualizado_en FROM usuarios WHERE id = ?", [localId]))[0];

    const extraEnv = {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPath,
      ATLAS_EMPRESA_SLUG: empresaSlug
    };

    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");

      const desactivar = await requestJson(baseUrl, "PATCH", `/usuarios/${localId}/estado`, { activo: false }, tokenAdmin);
      assertEqual(desactivar.response.status, 409, `PATCH estado desactivar (shadow) debe rechazar 409: ${JSON.stringify(desactivar.data)}`);

      const reactivar = await requestJson(baseUrl, "PATCH", `/usuarios/${localId}/estado`, { activo: true }, tokenAdmin);
      assertEqual(reactivar.response.status, 409, `PATCH estado reactivar (shadow) tambien debe rechazar 409: ${JSON.stringify(reactivar.data)}`);
    }, extraEnv);

    const despues = (await allSql(businessDbPath, "SELECT activo, actualizado_en FROM usuarios WHERE id = ?", [localId]))[0];
    assertEqual(Number(despues.activo), Number(antes.activo), "usuarios.activo local NO debe cambiar tras ninguno de los dos rechazos");
    assertSame(despues.actualizado_en, antes.actualizado_en, "actualizado_en NO debe tocarse -- ninguna escritura debe ocurrir");

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const membershipDespues = await getControlQuery(controlDb, "SELECT rol, activo FROM usuario_empresas WHERE id = ?", [membership.id]);
      assertSame(membershipDespues.rol, "admin", "membership.rol NO debe tocarse -- PATCH estado ya no abre Control DB");
      assertEqual(Number(membershipDespues.activo), 1, "membership.activo NO debe tocarse -- PATCH estado ya no abre Control DB");
      const centralDespues = await getControlQuery(controlDb, "SELECT activo FROM usuarios WHERE id = ?", [usuarioCentral.id]);
      assertEqual(Number(centralDespues.activo), 1, "usuarios central.activo debe permanecer intacto");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

async function testMT1CBridgeMultiempresaAislamiento() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaASlug = `bridge-multi-a-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresaBSlug = `bridge-multi-b-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresaA = await registrarEmpresa(controlDb, { slug: empresaASlug, nombre: "Bridge Multi A", dbPath: "guernica.db" });
    const empresaB = await registrarEmpresa(controlDb, { slug: empresaBSlug, nombre: "Bridge Multi B", dbPath: "guernica.db" });

    let localId;
    const usuarioLogin = `colaborador.multi.${Date.now()}`;
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const creado = await requestJson(baseUrl, "POST", "/usuarios", {
        nombre: "Colaborador Multi TEST",
        usuario: usuarioLogin,
        password: "ColaboradorMulti1",
        confirmar_password: "ColaboradorMulti1",
        rol: "colaborador"
      }, tokenAdmin);
      if (!creado.response.ok) throw new Error(`crear usuario fallo: ${creado.data?.message || creado.response.status}`);
      localId = creado.data.usuario.id;
    });

    const placeholderHash = await bcrypt.hash("PlaceholderMulti1", 10);
    const usuarioCentral = await crearUsuarioCentral(controlDb, {
      nombre: "Colaborador Multi TEST", usuarioReferencia: usuarioLogin, passwordHash: placeholderHash, activo: 1
    });
    const membershipA = await crearMembership(controlDb, {
      usuarioId: usuarioCentral.id, empresaId: empresaA.id, usuarioLocalId: localId, rol: "admin", activo: 1
    });
    // Membership B: misma identidad central, OTRA empresa, usuario_local_id ficticio -- nunca se
    // abre el business DB de B en este test, solo interesa que la fila de B quede intacta.
    const membershipB = await crearMembership(controlDb, {
      usuarioId: usuarioCentral.id, empresaId: empresaB.id, usuarioLocalId: 999001, rol: "colaborador", activo: 1
    });
    await closeControlDb(controlDb);

    // AUTH-SYNC-B2-S1A2B-PROFILE-GUARD: el PUT ya no puede sincronizar rol/activo bajo ninguna
    // circunstancia -- el payload intenta cambiarlos deliberadamente para confirmar que el 409
    // resultante no deja NINGUNA huella cruzada entre empresas (ni siquiera toca la membership de
    // la propia empresa A, mucho menos la de B).
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const put = await requestJson(baseUrl, "PUT", `/usuarios/${localId}`, {
        nombre: "Colaborador Multi TEST",
        usuario: usuarioLogin,
        rol: "encargado",
        email: "",
        telefono: "",
        activo: false
      }, tokenAdmin);
      assertEqual(put.response.status, 409, `PUT rol/activo multiempresa (empresa A) debe rechazar 409: ${JSON.stringify(put.data)}`);
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPath,
      ATLAS_EMPRESA_SLUG: empresaASlug
    });

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const aDespues = await getControlQuery(controlDb, "SELECT rol, activo FROM usuario_empresas WHERE id = ?", [membershipA.id]);
      assertSame(aDespues.rol, "admin", "membership A NO debe cambiar -- PUT ya no sincroniza acceso");
      assertEqual(Number(aDespues.activo), 1, "membership A NO debe desactivarse -- PUT ya no sincroniza acceso");

      const bDespues = await getControlQuery(controlDb, "SELECT rol, activo FROM usuario_empresas WHERE id = ?", [membershipB.id]);
      assertSame(bDespues.rol, "colaborador", "membership B NO debe cambiar de rol por una operacion en empresa A");
      assertEqual(Number(bDespues.activo), 1, "membership B NO debe desactivarse por una operacion en empresa A");

      const centralDespues = await getControlQuery(controlDb, "SELECT activo FROM usuarios WHERE id = ?", [usuarioCentral.id]);
      assertEqual(Number(centralDespues.activo), 1, "usuarios central.activo no debe tocarse por ninguna operacion de empresa individual");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

async function testMT1CBridgePutPerfilNoCopiaCentral() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `bridge-perfil-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Bridge Perfil Test", dbPath: "guernica.db" });

    let localId;
    const usuarioLogin = `colaborador.perfil.${Date.now()}`;
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const creado = await requestJson(baseUrl, "POST", "/usuarios", {
        nombre: "LOCAL ORIGINAL",
        usuario: usuarioLogin,
        password: "ColaboradorPerfil1",
        confirmar_password: "ColaboradorPerfil1",
        rol: "colaborador",
        email: "local@test.invalid"
      }, tokenAdmin);
      if (!creado.response.ok) throw new Error(`crear usuario fallo: ${creado.data?.message || creado.response.status}`);
      localId = creado.data.usuario.id;
    });

    const placeholderHash = await bcrypt.hash("PlaceholderPerfil1", 10);
    const usuarioCentral = await crearUsuarioCentral(controlDb, {
      nombre: "CENTRAL ORIGINAL", usuarioReferencia: usuarioLogin, email: "central@test.invalid", passwordHash: placeholderHash, activo: 1
    });
    const membership = await crearMembership(controlDb, {
      usuarioId: usuarioCentral.id, empresaId: empresa.id, usuarioLocalId: localId, rol: "colaborador", activo: 1
    });
    await closeControlDb(controlDb);

    // AUTH-SYNC-B2-S1A2B-PROFILE-GUARD: rol/usuario/activo se envian IGUALES a los locales actuales
    // (colaborador/activo=true) -- es una edicion de perfil pura bajo el nuevo contrato, que debe
    // aplicarse sin abrir la Control DB en absoluto.
    await withServer(businessDbPath, async (baseUrl) => {
      const tokenAdmin = await login(baseUrl, "admin", "admin123");
      const put = await requestJson(baseUrl, "PUT", `/usuarios/${localId}`, {
        nombre: "LOCAL NUEVO",
        usuario: usuarioLogin,
        rol: "colaborador",
        email: "local-nuevo@test.invalid",
        telefono: "",
        activo: true
      }, tokenAdmin);
      if (!put.response.ok) throw new Error(`PUT perfil-only fallo: ${put.data?.message || put.response.status}`);
      assertSame(put.data.usuario.nombre, "LOCAL NUEVO", "el local debe reflejar el nuevo nombre");
      assertSame(put.data.usuario.email, "local-nuevo@test.invalid", "el local debe reflejar el nuevo email");
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPath,
      ATLAS_EMPRESA_SLUG: empresaSlug
    });

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const membershipDespues = await getControlQuery(controlDb, "SELECT rol FROM usuario_empresas WHERE id = ?", [membership.id]);
      assertSame(membershipDespues.rol, "colaborador", "membership.rol NO debe tocarse -- PUT perfil-only no abre Control DB");

      const centralDespues = await getControlQuery(controlDb, "SELECT nombre, email FROM usuarios WHERE id = ?", [usuarioCentral.id]);
      assertSame(centralDespues.nombre, "CENTRAL ORIGINAL", "PUT perfil-only NUNCA debe copiar nombre al central");
      assertSame(centralDespues.email, "central@test.invalid", "PUT perfil-only NUNCA debe copiar email al central");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

// AUTH-SYNC-B2-S1A2B-PROFILE-GUARD: reemplaza a la vieja testMT1CBridgeRoleMembershipInexistente503.
// Bajo el contrato anterior, PUT escribia local PRIMERO (authority-first) y solo despues intentaba
// sincronizar a Control DB -- sin membership, esa sincronizacion fallaba con 503 pero el rol local
// ya habia cambiado. El nuevo contrato invierte esto por completo: un cambio de rol se rechaza de
// inmediato por comparacion puramente local, sin abrir la Control DB en ningun momento -- la
// existencia o no de una membership deja de ser relevante para esta decision.
async function testMT1CBridgePutShadowRolDiferenteRechaza409SinAbrirControlDb() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `bridge-rolnomembership-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "Bridge Rol No Membership", dbPath: "guernica.db" });
    const usuariosCentralAntes = await allControlQuery(controlDb, "SELECT id FROM usuarios");
    await closeControlDb(controlDb);

    const localAdmin = (await allSql(businessDbPath, "SELECT id, rol FROM usuarios WHERE usuario = ?", ["admin"]))[0];

    await withServer(businessDbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      const put = await requestJson(baseUrl, "PUT", `/usuarios/${localAdmin.id}`, {
        nombre: "Admin Sin Membership",
        usuario: "admin",
        rol: "encargado",
        email: "",
        telefono: "",
        activo: true
      }, token);
      assertEqual(put.response.status, 409, `sin membership, un cambio de rol debe rechazarse 409 igual (nunca 503, nunca se abre Control DB): ${JSON.stringify(put.data)}`);
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPath,
      ATLAS_EMPRESA_SLUG: empresaSlug
    });

    const localDespues = (await allSql(businessDbPath, "SELECT nombre, rol FROM usuarios WHERE id = ?", [localAdmin.id]))[0];
    assertSame(localDespues.rol, localAdmin.rol, "el rol local NO debe cambiar tras el rechazo");
    assertSame(localDespues.nombre !== "Admin Sin Membership", true, "tampoco el nombre debe cambiar -- sin escritura parcial tras un 409");

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const usuariosCentralDespues = await allControlQuery(controlDb, "SELECT id FROM usuarios");
      assertEqual(usuariosCentralDespues.length, usuariosCentralAntes.length, "no debe crearse ninguna identidad central nueva (PUT ya ni siquiera abre Control DB)");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

// AUTH-SYNC-B2-S1A2C-STATE-GUARD: reemplaza a la vieja testMT1CBridgeRoleActiveControlPlaneCaido503.
// El estado de la Control DB (caida, inexistente) ya no es relevante para esta decision -- PATCH
// estado rechaza incondicionalmente por modo del bridge, sin abrir Control DB en absoluto, asi que
// ni siquiera llega a intentar conectarse. Se conserva el escenario (Control DB en un path
// inexistente) para probar que eso tampoco cambia el resultado: sigue siendo 409, no 503, el local
// no cambia, y el archivo de Control DB nunca se crea.
async function testMT1CBridgePatchEstadoShadowRechaza409ConControlDbInaccesible() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPathInvalido = path.join(os.tmpdir(), `no-existe-rolactivo-${Date.now()}-${Math.random().toString(16).slice(2)}`, "atlas_control.db");
  try {
    const localAdmin = (await allSql(businessDbPath, "SELECT id, activo FROM usuarios WHERE usuario = ?", ["admin"]))[0];

    await withServer(businessDbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      const patch = await requestJson(baseUrl, "PATCH", `/usuarios/${localAdmin.id}/estado`, { activo: false }, token);
      assertEqual(patch.response.status, 409, `con Control DB inaccesible, PATCH estado debe rechazar 409 igual (nunca 503, nunca se abre Control DB): ${JSON.stringify(patch.data)}`);
    }, {
      ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_CONTROL_DB_PATH: controlDbPathInvalido,
      ATLAS_EMPRESA_SLUG: "cualquier-slug-rolactivo-down"
    });

    const localDespues = (await allSql(businessDbPath, "SELECT activo FROM usuarios WHERE id = ?", [localAdmin.id]))[0];
    assertEqual(Number(localDespues.activo), Number(localAdmin.activo), "el activo local NO debe cambiar tras el rechazo");
    if (fs.existsSync(controlDbPathInvalido)) {
      throw new Error("PATCH estado NO debe crear atlas_control.db -- no debe intentar abrirla en absoluto");
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
  }
}

