async function testMT1F1FalloConcurrenteNoQuedaCacheado() {
  const escenario = await mt1f1CrearEscenario(["fallo"]);
  const instrumento = mt1f1InstrumentarSqlite();
  // MT-1F5C1-R4B: aperturas locales SIN modo explicito (igual que runSql) -- mt1f1InstrumentarSqlite()
  // solo cuenta aperturas con modo numerico explicito (ver su propio comentario en su definicion), asi
  // que estas lecturas/verificaciones de snapshot no contaminan las aserciones de "un solo open"/
  // "conexion nueva" que este test certifica sobre el runtime productivo (a diferencia de allSql o
  // verificarBusinessSchemaVersion(), que abren con sqlite3.OPEN_READONLY explicito y SI contarian).
  function abrirSinContar(dbPath) {
    return new Promise((resolve, reject) => {
      const db = new sqlite3.Database(dbPath, (error) => {
        if (error) { reject(error); return; }
        resolve(db);
      });
    });
  }
  function cerrarSinContar(db) {
    return new Promise((resolve) => db.close(() => resolve()));
  }
  function leerFilasSinContar(dbPath, sql, params = []) {
    return new Promise((resolve, reject) => {
      const db = new sqlite3.Database(dbPath);
      db.all(sql, params, (error, rows) => {
        db.close((closeErr) => {
          if (error) reject(error);
          else if (closeErr) reject(closeErr);
          else resolve(rows);
        });
      });
    });
  }
  try {
    const [tenant] = escenario.tenants;

    // MT-1F5C1-R4B: snapshot exacto del bookkeeping ANTES de corromperlo -- inverso exacto de la
    // corrupcion deliberada de abajo. Nunca se sintetiza desde BUSINESS_MIGRATIONS ni se reaplica
    // ninguna migration: se restaura tal cual estaba.
    const ddlPrevio = (await leerFilasSinContar(
      tenant.dbPath,
      "SELECT sql FROM sqlite_master WHERE type='table' AND name='atlas_schema_migrations'"
    ))[0].sql;
    const filasPrevias = await leerFilasSinContar(
      tenant.dbPath,
      "SELECT sequence, migration_id, applied_at FROM atlas_schema_migrations ORDER BY sequence ASC"
    );
    assertEqual(filasPrevias.length, BUSINESS_MIGRATIONS.length, "snapshot PRE debe reflejar el catalogo real completo");

    // UNVERSIONED corre baseline completo antes de fallar (~cientos de ms): todas las llamadas
    // concurrentes llegan mientras la verificacion sigue en vuelo.
    await runSql(tenant.dbPath, "DROP TABLE atlas_schema_migrations");

    const resultados = await Promise.all(Array.from({ length: 5 }, () => mt1f1Resolver(tenant, escenario.controlDbPath)));
    for (const resultado of resultados) {
      mt1f1AssertFallo(resultado, TENANT_RUNTIME_ERROR_CODES.TENANT_SCHEMA_NOT_CURRENT, "fallo concurrente");
    }
    assertEqual(instrumento.de(tenant.dbPath).length, 1, "el fallo tambien es single-flight: un solo open para las 5 llamadas");
    assertSame(await mt1f1ConexionCerrada(instrumento.de(tenant.dbPath)[0].instancia), true, "la conexion del fallo se cerro");

    // Reparacion EXTERNA (operador): inversa EXACTA de "DROP TABLE atlas_schema_migrations" -- mismo
    // DDL, mismas filas, capturados antes de la corrupcion. Nunca stamparHistorialBaselineActual(): el
    // schema fisico (incluidas las tablas de la migration 002) nunca dejo de existir, asi que reaplicar
    // up() colisionaria exactamente como en #612 (ver MT-1F5C1-R4/R4A).
    await runSql(tenant.dbPath, ddlPrevio);
    for (const fila of filasPrevias) {
      await runSql(
        tenant.dbPath,
        "INSERT INTO atlas_schema_migrations (sequence, migration_id, applied_at) VALUES (?, ?, ?)",
        [fila.sequence, fila.migration_id, fila.applied_at]
      );
    }
    const filasRestauradas = await leerFilasSinContar(
      tenant.dbPath,
      "SELECT sequence, migration_id, applied_at FROM atlas_schema_migrations ORDER BY sequence ASC"
    );
    assertSame(JSON.stringify(filasRestauradas), JSON.stringify(filasPrevias), "el bookkeeping restaurado debe coincidir exactamente con el snapshot PRE-corrupcion");

    const conexionVerificacion = await abrirSinContar(tenant.dbPath);
    let estadoRestaurado;
    try {
      estadoRestaurado = await verificarBusinessSchemaVersionEnConexion(conexionVerificacion);
    } finally {
      await cerrarSinContar(conexionVerificacion);
    }
    assertSame(estadoRestaurado.state, "CURRENT", "restaurado exactamente el bookkeeping eliminado, el schema vuelve a CURRENT sin reaplicar ninguna migration");

    const recuperado = await mt1f1Resolver(tenant, escenario.controlDbPath);
    assertSame(recuperado.ok, true, `tras la reparacion externa la tenant debe resolver: el fallo no quedo cacheado (resultado=${JSON.stringify(recuperado)})`);
    assertEqual(instrumento.de(tenant.dbPath).length, 2, "el reintento abrio una conexion nueva (no reutilizo estado de fallo)");
  } finally {
    instrumento.restaurar();
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F1TenantAErrorNoAfectaTenantB() {
  const escenario = await mt1f1CrearEscenario(["aislaA", "aislaB"]);
  try {
    const [tenantA, tenantB] = escenario.tenants;
    await runSql(tenantA.dbPath, "UPDATE tenant_identity SET tenant_slug = 'identity-ajena' WHERE id = 1");

    const [resultadoA, resultadoB] = await Promise.all([
      mt1f1Resolver(tenantA, escenario.controlDbPath),
      mt1f1Resolver(tenantB, escenario.controlDbPath)
    ]);
    mt1f1AssertFallo(resultadoA, TENANT_RUNTIME_ERROR_CODES.TENANT_IDENTITY_INVALID, "tenant A con identity ajena");
    assertSame(resultadoB.ok, true, `la tenant B sana debe resolver aunque A falle (resultado=${JSON.stringify(resultadoB)})`);

    const otraVezB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    assertSame(otraVezB.handle, resultadoB.handle, "el fallo de A no invalido el handle publicado de B");
    const filas = await mt1f1Consultar(resultadoB.handle.db, "SELECT tenant_slug FROM tenant_identity WHERE id = 1");
    assertSame(filas[0].tenant_slug, tenantB.slug, "la conexion de B sigue sirviendo la DB de B");

    const otraVezA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    mt1f1AssertFallo(otraVezA, TENANT_RUNTIME_ERROR_CODES.TENANT_IDENTITY_INVALID, "A sigue rechazada, sin fallback a B");

    // A se corrige: se recupera sin reiniciar, y B sigue intacta.
    await runSql(tenantA.dbPath, "UPDATE tenant_identity SET tenant_slug = ? WHERE id = 1", [tenantA.slug]);
    const recuperadaA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    assertSame(recuperadaA.ok, true, "A corregida debe resolver");
    assertEqual(recuperadaA.handle.empresaId, tenantA.empresa.id, "el handle de A queda atado a A, no a B");
  } finally {
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F1TenantsDistintosHandlesDistintos() {
  const escenario = await mt1f1CrearEscenario(["distintoA", "distintoB"]);
  const instrumento = mt1f1InstrumentarSqlite();
  try {
    const [tenantA, tenantB] = escenario.tenants;
    const [resultadoA, resultadoB] = await Promise.all([
      mt1f1Resolver(tenantA, escenario.controlDbPath),
      mt1f1Resolver(tenantB, escenario.controlDbPath)
    ]);
    assertSame(resultadoA.ok && resultadoB.ok, true, "ambas tenants deben resolver en paralelo");
    const handleA = resultadoA.handle;
    const handleB = resultadoB.handle;

    assertSame(handleA === handleB, false, "handles distintos");
    assertSame(handleA.db === handleB.db, false, "conexiones distintas");
    assertSame(handleA.canonicalPath === handleB.canonicalPath, false, "paths canonicos distintos");
    assertSame(handleA.empresaId === handleB.empresaId, false, "empresaId distintos");
    assertEqual(instrumento.de(tenantA.dbPath).length, 1, "A se abre una sola vez");
    assertEqual(instrumento.de(tenantB.dbPath).length, 1, "B se abre una sola vez");

    const filasA = await mt1f1Consultar(handleA.db, "SELECT empresa_control_id, tenant_slug FROM tenant_identity WHERE id = 1");
    const filasB = await mt1f1Consultar(handleB.db, "SELECT empresa_control_id, tenant_slug FROM tenant_identity WHERE id = 1");
    assertEqual(filasA[0].empresa_control_id, tenantA.empresa.id, "la conexion de A lee la identity de A");
    assertSame(filasA[0].tenant_slug, tenantA.slug, "slug de A");
    assertEqual(filasB[0].empresa_control_id, tenantB.empresa.id, "la conexion de B lee la identity de B");
    assertSame(filasB[0].tenant_slug, tenantB.slug, "slug de B");
  } finally {
    instrumento.restaurar();
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F1PathDuplicadoEntreEmpresasFailsClosed() {
  const escenario = await mt1f1CrearEscenario(["dupA"]);
  const instrumento = mt1f1InstrumentarSqlite();
  try {
    const [tenantA] = escenario.tenants;
    const slugB = mt1f1Slug("dupB");
    const empresaB = await mt1f1RegistrarEmpresaExtra(escenario.controlDbPath, { slug: slugB, dbPath: path.basename(tenantA.dbPath), activa: 1 });
    const tenantB = { slug: slugB, empresa: empresaB };

    // Dos empresas ACTIVAS en el mismo path canonico: ambas fallan cerrado, sin importar el orden.
    const resultadoA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    const resultadoB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    mt1f1AssertFallo(resultadoA, TENANT_RUNTIME_ERROR_CODES.TENANT_PATH_COLLISION, "empresa A con path duplicado");
    mt1f1AssertFallo(resultadoB, TENANT_RUNTIME_ERROR_CODES.TENANT_PATH_COLLISION, "empresa B con path duplicado");
    assertEqual(instrumento.de(tenantA.dbPath).length, 0, "la colision se detecta ANTES de abrir la business DB");

    // Si la otra empresa esta INACTIVA no hay colision: la duplicidad solo cuenta entre activas.
    await runSql(escenario.controlDbPath, "UPDATE empresas SET activa = 0 WHERE id = ?", [empresaB.id]);
    const sinColision = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    assertSame(sinColision.ok, true, `con la duplicada inactiva A debe resolver (resultado=${JSON.stringify(sinColision)})`);
    assertEqual(instrumento.de(tenantA.dbPath).length, 1, "ahora si se abre, una sola vez");

    // Reactivada la duplicada: incluso con un handle YA publicado para A, la resolucion falla cerrado.
    await runSql(escenario.controlDbPath, "UPDATE empresas SET activa = 1 WHERE id = ?", [empresaB.id]);
    const conCache = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    mt1f1AssertFallo(conCache, TENANT_RUNTIME_ERROR_CODES.TENANT_PATH_COLLISION, "colision sobreviniente con handle cacheado");
    const conCacheB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    mt1f1AssertFallo(conCacheB, TENANT_RUNTIME_ERROR_CODES.TENANT_PATH_COLLISION, "B tampoco puede tomar el path publicado para A");
    assertEqual(instrumento.de(tenantA.dbPath).length, 1, "ninguna resolucion colisionada abrio otra conexion");
  } finally {
    instrumento.restaurar();
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F1CerrarTenantNoCierraOtro() {
  const escenario = await mt1f1CrearEscenario(["cierraA", "cierraB"]);
  try {
    const [tenantA, tenantB] = escenario.tenants;
    const resultadoA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    const resultadoB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    assertSame(resultadoA.ok && resultadoB.ok, true, "ambas tenants deben resolver");

    const cierre = await closeTenantHandle(resultadoA.handle);
    assertSame(cierre.ok, true, "cerrar A debe funcionar");
    assertSame(cierre.closed, true, "A estaba publicado y se cerro");
    assertSame(await mt1f1ConexionCerrada(resultadoA.handle.db), true, "la conexion de A quedo cerrada");
    const filasB = await mt1f1Consultar(resultadoB.handle.db, "SELECT 1 AS uno");
    assertEqual(filasB[0].uno, 1, "cerrar A no cerro B");
    const otraVezB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    assertSame(otraVezB.handle, resultadoB.handle, "B sigue cacheada con el mismo handle");

    const reabiertaA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    assertSame(reabiertaA.ok, true, "tras cerrar, A se resuelve de nuevo");
    assertSame(reabiertaA.handle === resultadoA.handle, false, "A reabre con un handle NUEVO");
    assertEqual((await mt1f1Consultar(reabiertaA.handle.db, "SELECT 1 AS uno"))[0].uno, 1, "el handle nuevo de A funciona");

    // Un handle viejo (ya no publicado) es un no-op: no cierra el handle nuevo.
    const cierreViejo = await closeTenantHandle(resultadoA.handle);
    assertSame(cierreViejo.ok, true, "cerrar un handle ya cerrado es idempotente");
    assertSame(cierreViejo.closed, false, "no cierra nada");
    assertEqual((await mt1f1Consultar(reabiertaA.handle.db, "SELECT 1 AS uno"))[0].uno, 1, "el handle nuevo de A sigue vivo");

    const invalido = await closeTenantHandle(null);
    mt1f1AssertFallo(invalido, TENANT_RUNTIME_ERROR_CODES.TENANT_HANDLE_INVALID, "handle nulo");
  } finally {
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F1CerrarTodosPermiteReabrir() {
  const escenario = await mt1f1CrearEscenario(["todosA", "todosB"]);
  const instrumento = mt1f1InstrumentarSqlite();
  try {
    const [tenantA, tenantB] = escenario.tenants;
    const resultadoA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    const resultadoB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    assertSame(resultadoA.ok && resultadoB.ok, true, "ambas tenants deben resolver");

    const cierre = await closeAllTenantHandles();
    assertSame(cierre.ok, true, "cerrar todo debe funcionar");
    assertEqual(cierre.closed, 2, "se cerraron los 2 handles publicados");
    assertEqual(cierre.failed, 0, "ningun cierre fallo");
    assertSame(await mt1f1ConexionCerrada(resultadoA.handle.db), true, "conexion A cerrada");
    assertSame(await mt1f1ConexionCerrada(resultadoB.handle.db), true, "conexion B cerrada");

    const reabiertaA = await mt1f1Resolver(tenantA, escenario.controlDbPath);
    const reabiertaB = await mt1f1Resolver(tenantB, escenario.controlDbPath);
    assertSame(reabiertaA.ok && reabiertaB.ok, true, "tras cerrar todo ambas tenants reabren y reverifican");
    assertSame(reabiertaA.handle === resultadoA.handle, false, "A: handle nuevo");
    assertSame(reabiertaB.handle === resultadoB.handle, false, "B: handle nuevo");
    assertEqual((await mt1f1Consultar(reabiertaA.handle.db, "SELECT 1 AS uno"))[0].uno, 1, "A reabierta funciona");
    assertEqual((await mt1f1Consultar(reabiertaB.handle.db, "SELECT 1 AS uno"))[0].uno, 1, "B reabierta funciona");
    assertEqual(instrumento.de(tenantA.dbPath).length, 2, "A: dos aperturas totales (original + reapertura)");
    assertEqual(instrumento.de(tenantB.dbPath).length, 2, "B: dos aperturas totales (original + reapertura)");

    const segundoCierre = await closeAllTenantHandles();
    assertEqual(segundoCierre.closed, 2, "el segundo cierre total cierra las dos reaperturas");
    const vacio = await closeAllTenantHandles();
    assertSame(vacio.ok, true, "cerrar todo sin handles es un no-op exitoso");
    assertEqual(vacio.closed, 0, "nada que cerrar");
  } finally {
    instrumento.restaurar();
    await mt1f1Limpiar(escenario);
  }
}

// ====================================================================================================
// MT-1F2: contexto asincrono de tenant (backend/tenantRequestContext.js) + backend/db.js consciente de
// contexto. Todo el comportamiento se ejercita contra DBs de prueba efimeras. Los handles SQL son
// handles REALES de MT-1F1 (backend/runtimeTenantRegistry.js) sobre business DBs frescas registrables.
// El singleton legacy de backend/db.js se ejercita SIEMPRE a traves de una instancia AISLADA del
// modulo, ligada a una DB "decoy" temporal (mt1f2CargarModulosAislados): asi ningun test, ni siquiera
// ante una regresion de fallback, puede abrir database/guernica.db real. TX-SAME-TENANT sigue OPEN:
// estos tests certifican aislamiento ENTRE tenants, jamas transacciones concurrentes del MISMO tenant.
// ====================================================================================================
function mt1f2HandleFalso(empresaId, empresaSlug) {
  const contadores = { run: 0, get: 0, all: 0 };
  const db = { run() { contadores.run += 1; }, get() { contadores.get += 1; }, all() { contadores.all += 1; } };
  const handle = Object.freeze({
    empresaId,
    empresaSlug,
    registeredPath: `${empresaSlug}.db`,
    canonicalPath: path.join(os.tmpdir(), `${empresaSlug}.db`),
    db,
    verifiedAt: new Date().toISOString()
  });
  return { handle, contadores };
}

// Carga una instancia NUEVA de backend/db.js (y de los servicios pedidos) ligada a `decoyPath`, sin
// alterar el modulo real del proceso ni el entorno: al terminar se restauran cache de require y env.
function mt1f2CargarModulosAislados(decoyPath, servicios = []) {
  const claveDb = require.resolve("../backend/db");
  const claves = [claveDb, ...servicios.map((nombre) => require.resolve(`../backend/services/${nombre}`))];
  const originales = claves.map((clave) => require.cache[clave]);
  const envAnterior = process.env.GUERNICA_DB_PATH;
  process.env.GUERNICA_DB_PATH = decoyPath;
  try {
    claves.forEach((clave) => { delete require.cache[clave]; });
    const db = require("../backend/db");
    const cargados = {};
    for (const nombre of servicios) cargados[nombre] = require(`../backend/services/${nombre}`);
    return { db, servicios: cargados };
  } finally {
    if (envAnterior === undefined) delete process.env.GUERNICA_DB_PATH;
    else process.env.GUERNICA_DB_PATH = envAnterior;
    claves.forEach((clave, indice) => {
      if (originales[indice]) require.cache[clave] = originales[indice];
      else delete require.cache[clave];
    });
  }
}

async function mt1f2CrearDecoy() {
  const decoyPath = tempDbPath();
  await runSql(decoyPath, "CREATE TABLE singleton_marker (valor TEXT NOT NULL)");
  await runSql(decoyPath, "INSERT INTO singleton_marker (valor) VALUES ('decoy-singleton')");
  return decoyPath;
}

async function mt1f2LimpiarDecoy(decoyPath) {
  for (const sufijo of ["", "-journal", "-wal", "-shm"]) {
    await mt1f1EliminarArchivo(`${decoyPath}${sufijo}`);
  }
}

// Escenario completo: N tenants F1 con handles REALES resueltos, decoy singleton, instrumentacion de
// aperturas sqlite y modulos aislados. mt1f2Cerrar deja todo sin residuos.
async function mt1f2Preparar(tags, servicios = []) {
  const estado = { escenario: null, decoyPath: null, instrumento: null, db: null, servicios: {}, handles: [], tenants: [] };
  try {
    estado.escenario = await mt1f1CrearEscenario(tags);
    estado.tenants = estado.escenario.tenants;
    estado.decoyPath = await mt1f2CrearDecoy();
    estado.instrumento = mt1f1InstrumentarSqlite();
    const aislado = mt1f2CargarModulosAislados(estado.decoyPath, servicios);
    estado.db = aislado.db;
    estado.servicios = aislado.servicios;
    for (const tenant of estado.tenants) {
      const resultado = await mt1f1Resolver(tenant, estado.escenario.controlDbPath);
      assertSame(resultado.ok, true, `el handle F1 de ${tenant.tag} debe resolver (resultado=${JSON.stringify(resultado)})`);
      estado.handles.push(resultado.handle);
    }
    return estado;
  } catch (error) {
    await mt1f2Cerrar(estado);
    throw error;
  }
}

async function mt1f2Cerrar(estado) {
  if (estado.db) { try { await estado.db.closeDb(); } catch (error) { /* singleton aislado ya cerrado */ } }
  if (estado.instrumento) estado.instrumento.restaurar();
  if (estado.escenario) await mt1f1Limpiar(estado.escenario);
  if (estado.decoyPath) await mt1f2LimpiarDecoy(estado.decoyPath);
}

function mt1f2Barrera() {
  let liberar;
  const promesa = new Promise((resolve) => { liberar = resolve; });
  return { promesa, liberar };
}

function mt1f2AperturasProhibidas(instrumento, decoyPath) {
  const guernica = path.resolve(SOURCE_DB).toLowerCase();
  const decoy = path.resolve(decoyPath).toLowerCase();
  return {
    guernica: instrumento.todas().filter((apertura) => apertura.archivo === guernica).length,
    decoy: instrumento.todas().filter((apertura) => apertura.archivo === decoy && typeof apertura.modo === "number").length
  };
}

async function testMT1F2ContextoAusentePorDefecto() {
  assertSame(hasTenantContext(), false, "sin runWithTenantHandle no debe haber contexto");
  assertSame(getTenantHandle(), null, "getTenantHandle sin contexto devuelve null");
  assertSame(getTenantContext(), null, "getTenantContext sin contexto devuelve null");
  assertSame(
    JSON.stringify(Object.keys(require("../backend/tenantRequestContext")).sort()),
    JSON.stringify(["getTenantContext", "getTenantHandle", "hasTenantContext", "runWithTenantHandle"]),
    "la API publica del modulo de contexto es exactamente la congelada"
  );

  // Testigo estatico: solo el built-in async_hooks; sin Express/auth/Host/Control/sqlite ni entorno.
  const fuente = fs.readFileSync(path.join(ROOT, "backend", "tenantRequestContext.js"), "utf8");
  const ejecutable = fuente.replace(/\/\/.*$/gm, "");
  const dependencias = Array.from(ejecutable.matchAll(/require\("([^"]+)"\)/g), (coincidencia) => coincidencia[1]);
  assertSame(JSON.stringify(dependencias), JSON.stringify(["async_hooks"]), "la unica dependencia del modulo de contexto es el built-in async_hooks");
  for (const prohibido of ["express", "sqlite3", "process.env", "runtimeTenantRegistry", "init-control-db", "centralAuth", "tenantHostContext", "userControlBridge", "sesiones"]) {
    assertSame(ejecutable.includes(prohibido), false, `el modulo de contexto no debe depender de ${prohibido}`);
  }

  // Requerir contexto + db.js + servicios en un proceso limpio jamas crea contexto ni abre/crea la DB.
  const decoyInexistente = tempDbPath();
  const script = `
    const ctx = require(${JSON.stringify(path.join(ROOT, "backend", "tenantRequestContext.js"))});
    require(${JSON.stringify(path.join(ROOT, "backend", "db.js"))});
    for (const servicio of ["ventaService", "cajaService", "stockService", "configService"]) {
      require(${JSON.stringify(path.join(ROOT, "backend", "services"))} + "/" + servicio);
    }
    console.log(JSON.stringify({ has: ctx.hasTenantContext(), handle: ctx.getTenantHandle(), contexto: ctx.getTenantContext() }));
  `;
  const resultado = spawnSync(process.execPath, ["-e", script], { cwd: ROOT, env: { ...process.env, GUERNICA_DB_PATH: decoyInexistente }, encoding: "utf8" });
  assertEqual(resultado.status, 0, `el require de los modulos en proceso limpio debe salir 0\n${resultado.stderr}`);
  const observado = JSON.parse(resultado.stdout.trim());
  assertSame(observado.has, false, "requerir modulos no crea contexto");
  assertSame(observado.handle, null, "no hay tenant por defecto tras requerir");
  assertSame(observado.contexto, null, "no hay contexto tras requerir");
  assertSame(fs.existsSync(decoyInexistente), false, "requerir db.js/servicios no abre ni crea ninguna DB");
}

async function testMT1F2HandleInvalidoNoEntraContexto() {
  const { handle: valido, contadores } = mt1f2HandleFalso(1, "tenant-valido");
  const { empresaId, ...sinEmpresaId } = valido;
  const { empresaSlug, ...sinSlug } = valido;
  const { canonicalPath, ...sinCanonical } = valido;
  const { db, ...sinDb } = valido;
  const invalidos = [
    ["null", null], ["undefined", undefined], ["string", "handle"], ["numero", 7], ["array", []],
    ["objeto valido pero SIN congelar", { ...valido }],
    ["sin empresaId", Object.freeze(sinEmpresaId)], ["empresaId 0", Object.freeze({ ...valido, empresaId: 0 })],
    ["empresaId negativo", Object.freeze({ ...valido, empresaId: -3 })], ["empresaId string", Object.freeze({ ...valido, empresaId: "1" })],
    ["empresaId decimal", Object.freeze({ ...valido, empresaId: 1.5 })],
    ["sin slug", Object.freeze(sinSlug)], ["slug vacio", Object.freeze({ ...valido, empresaSlug: "" })],
    ["slug con espacios", Object.freeze({ ...valido, empresaSlug: " tenant " })], ["slug no string", Object.freeze({ ...valido, empresaSlug: 5 })],
    ["sin canonicalPath", Object.freeze(sinCanonical)], ["canonicalPath vacio", Object.freeze({ ...valido, canonicalPath: "" })],
    ["canonicalPath solo espacios", Object.freeze({ ...valido, canonicalPath: "   " })],
    ["sin db", Object.freeze(sinDb)], ["db null", Object.freeze({ ...valido, db: null })],
    ["db sin metodos", Object.freeze({ ...valido, db: {} })], ["db parcial", Object.freeze({ ...valido, db: { run() {} } })]
  ];
  for (const [nombre, candidato] of invalidos) {
    let invocado = false;
    let error = null;
    try {
      runWithTenantHandle(candidato, () => { invocado = true; });
    } catch (capturado) {
      error = capturado;
    }
    assertSame(error instanceof TypeError, true, `${nombre}: debe rechazarse con TypeError (error=${error})`);
    assertSame(error.code, "TENANT_CONTEXT_INVALID_HANDLE", `${nombre}: codigo de rechazo estable`);
    assertSame(invocado, false, `${nombre}: el callback jamas se invoca con un handle invalido`);
    assertSame(hasTenantContext(), false, `${nombre}: no queda contexto tras el rechazo`);
  }

  for (const callbackInvalido of [null, undefined, "no-funcion", 42]) {
    let error = null;
    try { runWithTenantHandle(valido, callbackInvalido); } catch (capturado) { error = capturado; }
    assertSame(error && error.code, "TENANT_CONTEXT_INVALID_HANDLE", "un callback que no es funcion se rechaza");
  }

  // Un handle bien formado SI entra: el contexto solo transporta, no reabre ni reverifica la conexion.
  let observado = null;
  const retorno = runWithTenantHandle(valido, () => { observado = getTenantHandle(); return "devuelto"; });
  assertSame(retorno, "devuelto", "runWithTenantHandle devuelve lo que devuelve el callback");
  assertSame(observado, valido, "el contexto transporta el MISMO handle, no una copia");
  assertEqual(contadores.run + contadores.get + contadores.all, 0, "entrar/salir del contexto no toca la conexion del handle");
  assertSame(hasTenantContext(), false, "al terminar el callback el contexto desaparece");

  // El store del contexto es inmutable: nadie puede cambiar el binding empresa/path/conexion a mitad de cadena.
  let contexto = null;
  runWithTenantHandle(valido, () => { contexto = getTenantContext(); });
  assertSame(Object.isFrozen(contexto), true, "el store del contexto esta congelado");
  assertSame(
    JSON.stringify(Object.keys(contexto).sort()),
    JSON.stringify(["canonicalPath", "empresaId", "empresaSlug", "tenantHandle"]),
    "el store contiene exactamente el minimo contractual"
  );
  assertSame(contexto.tenantHandle, valido, "el store transporta el mismo handle verificado");
  assertEqual(contexto.empresaId, valido.empresaId, "empresaId del store");
  assertSame(contexto.empresaSlug, valido.empresaSlug, "empresaSlug del store");
  assertSame(contexto.canonicalPath, valido.canonicalPath, "canonicalPath del store");
  const mutacionesStore = [
    () => { "use strict"; contexto.empresaId = 999; },
    () => { "use strict"; contexto.empresaSlug = "otro"; },
    () => { "use strict"; contexto.canonicalPath = "C:\otro.db"; },
    () => { "use strict"; contexto.tenantHandle = null; },
    () => { "use strict"; contexto.extra = true; },
    () => { "use strict"; delete contexto.tenantHandle; }
  ];
  for (let indice = 0; indice < mutacionesStore.length; indice += 1) {
    assertThrows(mutacionesStore[indice], `la mutacion #${indice + 1} del store debe rechazarse`);
  }
  assertSame(contexto.tenantHandle, valido, "el binding del store no cambio tras los intentos de mutacion");
  assertSame(Object.isFrozen(valido.db), false, "la conexion del handle NO se congela: su ciclo de vida es del registry");
}

async function testMT1F2ContextoPropagaAwaitYTimers() {
  const { handle } = mt1f2HandleFalso(11, "propaga");
  const memoria = new sqlite3.Database(":memory:");
  const observaciones = [];
  const ver = (etapa) => { observaciones.push([etapa, getTenantHandle() === handle]); };
  // Helper anidado SIN parametros de contexto: la propagacion debe ser implicita.
  const helperAnidado = async () => {
    ver("helper anidado (antes)");
    await Promise.resolve();
    ver("helper anidado (tras await)");
    await delay(2);
    ver("helper anidado (tras timer)");
  };

  try {
    const retorno = await runWithTenantHandle(handle, async () => {
      ver("inicio");
      await Promise.resolve(); ver("await Promise.resolve");
      await new Promise((resolve) => setImmediate(resolve)); ver("await setImmediate");
      await delay(5); ver("await setTimeout");
      await new Promise((resolve) => process.nextTick(resolve)); ver("await process.nextTick");
      await Promise.resolve().then(() => ver("cadena then 1")).then(() => ver("cadena then 2")).finally(() => ver("cadena finally"));
      await new Promise((resolve) => queueMicrotask(() => { ver("queueMicrotask"); resolve(); }));
      // Contrato relevante para backend/db.js: sqlite3 envuelto en una promesa. El callback nativo crudo
      // de sqlite3 corre fuera del contexto ALS (detalle del addon, NO se exige ni se asume), pero db.js
      // solo lo usa para resolver/rechazar la promesa: la continuacion del await SI conserva el contexto.
      await new Promise((resolve, reject) => memoria.get("SELECT 1 AS uno", (error, fila) => {
        if (error) reject(error); else resolve(fila);
      }));
      ver("await tras query sqlite3 envuelta en promesa");
      await new Promise((resolve, reject) => memoria.all("SELECT 2 AS dos", (error, filas) => {
        if (error) reject(error); else resolve(filas);
      }));
      ver("segunda query sqlite3 envuelta en promesa");
      await new Promise((resolve) => setTimeout(() => { ver("dentro del callback de setTimeout"); resolve(); }, 3));
      await new Promise((resolve) => setImmediate(() => { ver("dentro del callback de setImmediate"); resolve(); }));
      await helperAnidado(); ver("tras helper anidado");
      await Promise.all([helperAnidado(), helperAnidado()]); ver("tras Promise.all de helpers");
      await Promise.race([delay(1), delay(6)]); ver("tras Promise.race");
      return "completo";
    });
    assertSame(retorno, "completo", "la cadena async completa debe terminar");
  } finally {
    await new Promise((resolve) => memoria.close(() => resolve()));
  }

  const perdidas = observaciones.filter(([, presente]) => !presente).map(([etapa]) => etapa);
  assertEqual(perdidas.length, 0, `el contexto se perdio en: ${JSON.stringify(perdidas)}`);
  assertSame(observaciones.length >= 20, true, `se esperaban >= 20 observaciones, hubo ${observaciones.length}`);
  assertSame(hasTenantContext(), false, "fuera de la cadena no queda contexto");
}

async function testMT1F2ContextosConcurrentesAislados() {
  const { handle: handleA } = mt1f2HandleFalso(21, "concurrente-a");
  const { handle: handleB } = mt1f2HandleFalso(22, "concurrente-b");
  const orden = [];
  const rama = (handle, pasos) => runWithTenantHandle(handle, async () => {
    const errores = [];
    const verificar = (etapa) => { if (getTenantHandle() !== handle) errores.push(`${handle.empresaSlug}:${etapa}`); };
    for (let indice = 0; indice < pasos; indice += 1) {
      await delay(Math.floor(Math.random() * 4)); verificar(`timer#${indice}`); orden.push(handle.empresaSlug);
      await Promise.resolve(); verificar(`microtask#${indice}`);
      await new Promise((resolve) => setImmediate(resolve)); verificar(`immediate#${indice}`);
    }
    return errores;
  });

  const resultados = await Promise.all([rama(handleA, 50), rama(handleB, 50), rama(handleA, 30), rama(handleB, 30)]);
  for (const errores of resultados) {
    assertEqual(errores.length, 0, `contaminacion entre contextos concurrentes: ${JSON.stringify(errores.slice(0, 5))}`);
  }
  let alternancias = 0;
  for (let indice = 1; indice < orden.length; indice += 1) if (orden[indice] !== orden[indice - 1]) alternancias += 1;
  assertSame(alternancias >= 10, true, `el test debe haber intercalado ramas A y B de verdad (alternancias=${alternancias})`);
  assertSame(hasTenantContext(), false, "tras completar ambas ramas el contexto externo esta ausente");
  assertSame(getTenantHandle(), null, "y no queda ningun handle 'ultimo usado'");
}

async function testMT1F2ContextoAnidadoRestauraAnterior() {
  const { handle: handleA } = mt1f2HandleFalso(31, "anidado-a");
  const { handle: handleB } = mt1f2HandleFalso(32, "anidado-b");
  const eventos = [];
  const anotar = (etiqueta, esperado) => eventos.push([etiqueta, getTenantHandle() === esperado]);
  let contextoA = null;
  let contextoB = null;

  await runWithTenantHandle(handleA, async () => {
    contextoA = getTenantContext();
    anotar("A antes de anidar", handleA);
    await runWithTenantHandle(handleB, async () => {
      contextoB = getTenantContext();
      anotar("B dentro", handleB);
      await delay(3);
      anotar("B tras await", handleB);
      await runWithTenantHandle(handleA, async () => { anotar("A anidado en B", handleA); });
      anotar("B tras A anidado", handleB);
    });
    anotar("A tras volver de B", handleA);
    await delay(2);
    anotar("A tras await posterior", handleA);
    const sincrono = runWithTenantHandle(handleB, () => getTenantHandle() === handleB);
    eventos.push(["B sincronico anidado", sincrono]);
    anotar("A tras anidado sincronico", handleA);
    assertSame(getTenantContext(), contextoA, "el store de A vuelve a ser exactamente el original");
  });
  anotar("afuera", null);

  const fallidos = eventos.filter(([, ok]) => !ok).map(([etiqueta]) => etiqueta);
  assertEqual(fallidos.length, 0, `semantica de pila incorrecta en: ${JSON.stringify(fallidos)}`);
  assertSame(contextoA === contextoB, false, "cada nivel tiene su propio store");
  assertSame(contextoB.tenantHandle, handleB, "el store de B transporta el handle de B");
  assertSame(hasTenantContext(), false, "terminado el nivel externo no hay contexto");
}

async function testMT1F2DbGetDbUsaHandleActivo() {
  const estado = await mt1f2Preparar(["getdb"]);
  try {
    const [handle] = estado.handles;
    const [tenant] = estado.tenants;
    assertEqual(estado.instrumento.de(estado.decoyPath).length, 0, "cargar el modulo aislado no abre el singleton (apertura lazy)");

    await runWithTenantHandle(handle, async () => {
      assertSame(estado.db.getDb(), handle.db, "getDb con contexto activo devuelve EXACTAMENTE la conexion del handle");
      const fila = await estado.db.getQuery("SELECT tenant_slug FROM tenant_identity WHERE id = 1");
      assertSame(fila.tenant_slug, tenant.slug, "getQuery lee la business DB del tenant activo");
    });

    const prohibidas = mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath);
    assertEqual(prohibidas.decoy, 0, "con contexto activo el singleton jamas se abre");
    assertEqual(prohibidas.guernica, 0, "database/guernica.db real jamas se abre");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2DbSinContextoConservaSingleton() {
  const decoyPath = await mt1f2CrearDecoy();
  const instrumento = mt1f1InstrumentarSqlite();
  let db = null;
  try {
    db = mt1f2CargarModulosAislados(decoyPath).db;
    assertEqual(instrumento.de(decoyPath).length, 0, "require no abre ni crea la DB (apertura lazy)");
    assertSame(db.dbPath, path.resolve(decoyPath), "dbPath sigue viniendo del entorno, como siempre");
    assertSame(hasTenantContext(), false, "el test corre SIN contexto");

    const fila = await db.getQuery("SELECT valor FROM singleton_marker");
    assertSame(fila.valor, "decoy-singleton", "sin contexto getQuery usa el singleton legacy");
    const escrito = await db.runQuery("INSERT INTO singleton_marker (valor) VALUES (?)", ["segunda"]);
    assertEqual(escrito.changes, 1, "sin contexto runQuery escribe en el singleton legacy");
    const filas = await db.allQuery("SELECT valor FROM singleton_marker ORDER BY valor");
    assertEqual(filas.length, 2, "sin contexto allQuery lee el singleton legacy");

    const aperturas = instrumento.de(decoyPath);
    assertEqual(aperturas.length, 1, "una sola apertura lazy del singleton para tres operaciones");
    assertSame(aperturas[0].modo, sqlite3.OPEN_READWRITE, "el singleton conserva OPEN_READWRITE explicito");
    assertEqual(aperturas[0].modo & sqlite3.OPEN_CREATE, 0, "y sigue sin OPEN_CREATE");
    assertSame(db.getDb(), aperturas[0].instancia, "getDb devuelve la instancia singleton");
    assertSame(db.getDb(), db.getDb(), "el singleton es estable entre llamadas");

    await db.closeDb();
    assertSame(await mt1f1ConexionCerrada(aperturas[0].instancia), true, "closeDb cierra el singleton");
    await db.closeDb();
    const reabierta = await db.getQuery("SELECT COUNT(*) AS total FROM singleton_marker");
    assertEqual(reabierta.total, 2, "tras closeDb la proxima operacion reabre el singleton");
    assertEqual(instrumento.de(decoyPath).length, 2, "el singleton se reabrio una vez");
    assertEqual(mt1f2AperturasProhibidas(instrumento, decoyPath).guernica, 0, "database/guernica.db real jamas se abre");
  } finally {
    if (db) { try { await db.closeDb(); } catch (error) { /* ya cerrado */ } }
    instrumento.restaurar();
    await mt1f2LimpiarDecoy(decoyPath);
  }
}

async function testMT1F2DbContextoNoFallbackASingleton() {
  const estado = await mt1f2Preparar(["nofallback"]);
  try {
    const [handle] = estado.handles;
    const cierre = await closeTenantHandle(handle);
    assertSame(cierre.ok && cierre.closed, true, "el registry (dueno del ciclo de vida) cierra el handle");
    assertSame(await mt1f1ConexionCerrada(handle.db), true, "precondicion: la conexion del handle esta cerrada");

    await runWithTenantHandle(handle, async () => {
      assertSame(estado.db.getDb(), handle.db, "con contexto activo getDb sigue devolviendo la conexion del handle, aunque este cerrada");
      for (const [nombre, operacion] of [
        ["runQuery", () => estado.db.runQuery("SELECT 1")],
        ["getQuery", () => estado.db.getQuery("SELECT 1 AS uno")],
        ["allQuery", () => estado.db.allQuery("SELECT 1 AS uno")]
      ]) {
        let error = null;
        try { await operacion(); } catch (capturado) { error = capturado; }
        assertSame(error !== null, true, `${nombre} sobre un handle cerrado debe fallar`);
        assertSame(/closed|MISUSE/i.test(`${error.code} ${error.message}`), true, `${nombre}: debe ser el error de sqlite de conexion cerrada (fue: ${error.code} ${error.message})`);
      }
    });

    const prohibidas = mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath);
    assertEqual(prohibidas.decoy, 0, "el fallo NO abrio el singleton como fallback");
    assertEqual(prohibidas.guernica, 0, "el fallo NO abrio database/guernica.db");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2CloseDbNoCierraHandleTenant() {
  const estado = await mt1f2Preparar(["closedb"]);
  try {
    const [handle] = estado.handles;
    const [tenant] = estado.tenants;

    // Abre el singleton FUERA de contexto y luego llama closeDb DENTRO de un contexto de tenant.
    const marcador = await estado.db.getQuery("SELECT valor FROM singleton_marker");
    assertSame(marcador.valor, "decoy-singleton", "precondicion: singleton abierto fuera de contexto");
    const instanciaSingleton = estado.instrumento.de(estado.decoyPath)[0].instancia;

    await runWithTenantHandle(handle, async () => { await estado.db.closeDb(); });
    assertSame(await mt1f1ConexionCerrada(instanciaSingleton), true, "closeDb cierra SOLO el singleton legacy");
    const filas = await mt1f1Consultar(handle.db, "SELECT 1 AS uno");
    assertEqual(filas[0].uno, 1, "closeDb dentro del contexto NO cerro la conexion del handle");

    // Sin singleton abierto, closeDb dentro del contexto tampoco toca el handle.
    await runWithTenantHandle(handle, async () => {
      await estado.db.closeDb();
      const fila = await estado.db.getQuery("SELECT tenant_slug FROM tenant_identity WHERE id = 1");
      assertSame(fila.tenant_slug, tenant.slug, "el handle sigue sirviendo su DB tras closeDb");
    });

    const otra = await mt1f1Resolver(tenant, estado.escenario.controlDbPath);
    assertSame(otra.handle, handle, "el registry sigue teniendo publicado el mismo handle: el ciclo de vida sigue siendo suyo");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2HelpersDesestructuradosResuelvenEnEjecucion() {
  const estado = await mt1f2Preparar(["destructA", "destructB"], ["configService"]);
  try {
    const [handleA, handleB] = estado.handles;
    // Referencias capturadas ANTES de entrar a cualquier contexto, como hacen los servicios reales.
    const { runQuery, getQuery, allQuery } = estado.db;
    const { getConfiguracionGlobal } = estado.servicios.configService;
    const sqlNombre = "SELECT valor FROM configuracion_global WHERE clave = 'negocio_nombre_comercial'";
    const escribir = (etiqueta) => runQuery(
      "INSERT OR REPLACE INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('negocio_nombre_comercial', ?, 'negocio', datetime('now'))",
      [JSON.stringify(etiqueta)]
    );

    await runWithTenantHandle(handleA, async () => { await escribir("Comercio A"); });
    await runWithTenantHandle(handleB, async () => { await escribir("Comercio B"); });

    for (const [handle, etiqueta] of [[handleA, "Comercio A"], [handleB, "Comercio B"]]) {
      await runWithTenantHandle(handle, async () => {
        assertSame((await getQuery(sqlNombre)).valor, JSON.stringify(etiqueta), `getQuery capturado resuelve al tenant activo (${etiqueta})`);
        assertEqual((await allQuery(sqlNombre)).length, 1, "allQuery capturado ve una sola fila");
        const config = await getConfiguracionGlobal();
        assertSame(config.negocio_nombre_comercial, etiqueta, `el servicio REAL configService (require al cargar) lee ${etiqueta}`);
      });
    }

    // La MISMA referencia capturada, fuera de todo contexto, sigue usando el singleton legacy.
    const fueraDeContexto = await getQuery("SELECT valor FROM singleton_marker");
    assertSame(fueraDeContexto.valor, "decoy-singleton", "sin contexto la referencia capturada usa el singleton");

    const enA = await allSql(estado.tenants[0].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'negocio_nombre_comercial'");
    const enB = await allSql(estado.tenants[1].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'negocio_nombre_comercial'");
    assertSame(JSON.stringify(enA.map((fila) => fila.valor)), JSON.stringify(['"Comercio A"']), "verificacion directa: A solo tiene A");
    assertSame(JSON.stringify(enB.map((fila) => fila.valor)), JSON.stringify(['"Comercio B"']), "verificacion directa: B solo tiene B");
    assertEqual(mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath).guernica, 0, "database/guernica.db real jamas se abre");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2SqlLecturaEsAisladaAB() {
  const estado = await mt1f2Preparar(["lecturaA", "lecturaB"]);
  try {
    const [tenantA, tenantB] = estado.tenants;
    const [handleA, handleB] = estado.handles;
    const sembrar = (tenant, valor, propio) => Promise.all([
      runSql(tenant.dbPath, "INSERT INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('mt1f2_marker', ?, 'test', datetime('now'))", [valor]),
      runSql(tenant.dbPath, "INSERT INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES (?, '1', 'test', datetime('now'))", [propio])
    ]);
    // Sembrado secuencial por tenant (runSql abre conexiones propias sobre el archivo, ya con handle F1 abierto).
    await sembrar(tenantA, "A", "mt1f2_solo_a");
    await sembrar(tenantB, "B", "mt1f2_solo_b");

    const leer = (handle, esperado, propio, ajeno) => runWithTenantHandle(handle, async () => {
      const errores = [];
      for (let indice = 0; indice < 25; indice += 1) {
        await delay(Math.floor(Math.random() * 3));
        const marcador = await estado.db.getQuery("SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_marker'");
        if (!marcador || marcador.valor !== esperado) errores.push(`marcador#${indice}=${marcador && marcador.valor}`);
        const claves = (await estado.db.allQuery("SELECT clave FROM configuracion_global WHERE clave LIKE 'mt1f2_%' ORDER BY clave")).map((fila) => fila.clave);
        if (JSON.stringify(claves) !== JSON.stringify(["mt1f2_marker", propio])) errores.push(`claves#${indice}=${JSON.stringify(claves)}`);
        const delAjeno = await estado.db.getQuery("SELECT valor FROM configuracion_global WHERE clave = ?", [ajeno]);
        if (delAjeno !== undefined) errores.push(`ajeno#${indice} visible`);
        await estado.db.runQuery("SELECT 1");
      }
      return errores;
    });

    const [erroresA, erroresB] = await Promise.all([
      leer(handleA, "A", "mt1f2_solo_a", "mt1f2_solo_b"),
      leer(handleB, "B", "mt1f2_solo_b", "mt1f2_solo_a")
    ]);
    assertEqual(erroresA.length, 0, `lecturas concurrentes en A vieron datos ajenos: ${JSON.stringify(erroresA.slice(0, 3))}`);
    assertEqual(erroresB.length, 0, `lecturas concurrentes en B vieron datos ajenos: ${JSON.stringify(erroresB.slice(0, 3))}`);
    assertEqual(mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath).decoy, 0, "ninguna lectura toco el singleton");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2SqlEscrituraConcurrenteEsAisladaAB() {
  const estado = await mt1f2Preparar(["escrituraA", "escrituraB"]);
  try {
    const [tenantA, tenantB] = estado.tenants;
    const [handleA, handleB] = estado.handles;
    const total = 30;
    const escribir = (handle, etiqueta) => runWithTenantHandle(handle, async () => {
      for (let indice = 0; indice < total; indice += 1) {
        await delay(Math.floor(Math.random() * 3));
        const resultado = await estado.db.runQuery(
          "INSERT INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES (?, ?, 'test', datetime('now'))",
          [`mt1f2_w_${etiqueta}_${indice}`, etiqueta]
        );
        if (resultado.changes !== 1) throw new Error(`insert ${etiqueta}#${indice} changes=${resultado.changes}`);
      }
    });
    await Promise.all([escribir(handleA, "A"), escribir(handleB, "B")]);

    const filasA = await allSql(tenantA.dbPath, "SELECT clave, valor FROM configuracion_global WHERE clave LIKE 'mt1f2_w_%'");
    const filasB = await allSql(tenantB.dbPath, "SELECT clave, valor FROM configuracion_global WHERE clave LIKE 'mt1f2_w_%'");
    assertEqual(filasA.length, total, "verificacion directa: A recibio exactamente sus escrituras");
    assertEqual(filasB.length, total, "verificacion directa: B recibio exactamente sus escrituras");
    assertSame(filasA.every((fila) => fila.valor === "A" && fila.clave.startsWith("mt1f2_w_A_")), true, "A contiene SOLO escrituras de A");
    assertSame(filasB.every((fila) => fila.valor === "B" && fila.clave.startsWith("mt1f2_w_B_")), true, "B contiene SOLO escrituras de B");
    assertEqual(mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath).decoy, 0, "ninguna escritura toco el singleton");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2TransaccionANoInterfiereConB() {
  const estado = await mt1f2Preparar(["txA", "txB"]);
  try {
    const [tenantA, tenantB] = estado.tenants;
    const [handleA, handleB] = estado.handles;
    const insertar = (clave, valor) => estado.db.runQuery(
      "INSERT INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES (?, ?, 'test', datetime('now'))",
      [clave, valor]
    );

    // Escenario 1: A abre su transaccion y la mantiene ABIERTA mientras B abre y cierra la suya.
    // Si compartieran conexion, B fallaria con "cannot start a transaction within a transaction".
    const aAbierta = mt1f2Barrera();
    const bAbierta = mt1f2Barrera();
    const transaccionA = runWithTenantHandle(handleA, async () => {
      await estado.db.runQuery("BEGIN TRANSACTION");
      await insertar("mt1f2_tx1", "A-commit");
      aAbierta.liberar();
      await bAbierta.promesa;
      await delay(20);
      await estado.db.runQuery("COMMIT");
      return "A-ok";
    });
    const transaccionB = runWithTenantHandle(handleB, async () => {
      await aAbierta.promesa;
      await estado.db.runQuery("BEGIN IMMEDIATE");
      await insertar("mt1f2_tx1", "B-commit");
      bAbierta.liberar();
      const propio = await estado.db.getQuery("SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_tx1'");
      await estado.db.runQuery("COMMIT");
      return propio.valor;
    });
    const [resultadoA, resultadoB] = await Promise.all([transaccionA, transaccionB]);
    assertSame(resultadoA, "A-ok", "la transaccion de A completa sin error causado por B");
    assertSame(resultadoB, "B-commit", "B lee su propia escritura dentro de su transaccion");
    assertSame(JSON.stringify((await allSql(tenantA.dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_tx1'")).map((fila) => fila.valor)), JSON.stringify(["A-commit"]), "A committeo solo lo suyo");
    assertSame(JSON.stringify((await allSql(tenantB.dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_tx1'")).map((fila) => fila.valor)), JSON.stringify(["B-commit"]), "B committeo solo lo suyo");

    // Escenario 2: A hace ROLLBACK mientras B escribe SIN transaccion propia. Con un singleton compartido
    // la escritura de B se perderia junto al ROLLBACK de A; con conexiones separadas no hay cruce.
    const aEscribio = mt1f2Barrera();
    const bEscribio = mt1f2Barrera();
    const rollbackA = runWithTenantHandle(handleA, async () => {
      await estado.db.runQuery("BEGIN TRANSACTION");
      await insertar("mt1f2_tx2", "A-rollback");
      aEscribio.liberar();
      await bEscribio.promesa;
      await estado.db.runQuery("ROLLBACK");
      return "A-rollback-ok";
    });
    const autocommitB = runWithTenantHandle(handleB, async () => {
      await aEscribio.promesa;
      await insertar("mt1f2_tx2", "B-autocommit");
      bEscribio.liberar();
      return "B-autocommit-ok";
    });
    assertSame((await Promise.all([rollbackA, autocommitB])).join(","), "A-rollback-ok,B-autocommit-ok", "ambas ramas completan sin errores cruzados");
    assertEqual((await allSql(tenantA.dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_tx2'")).length, 0, "el ROLLBACK de A descarto la escritura de A");
    assertSame(
      JSON.stringify((await allSql(tenantB.dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'mt1f2_tx2'")).map((fila) => fila.valor)),
      JSON.stringify(["B-autocommit"]),
      "el ROLLBACK de A NO revirtio la escritura de B"
    );
    assertEqual(mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath).decoy, 0, "ninguna transaccion toco el singleton");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

async function testMT1F2ErrorLimpiaContextoSinAfectarOtro() {
  const estado = await mt1f2Preparar(["errorA", "errorB"]);
  try {
    const [tenantA, tenantB] = estado.tenants;
    const [handleA, handleB] = estado.handles;

    // B corre una cadena larga mientras A falla en mitad de la suya.
    const ramaB = runWithTenantHandle(handleB, async () => {
      const errores = [];
      for (let indice = 0; indice < 20; indice += 1) {
        await delay(4);
        if (getTenantHandle() !== handleB) errores.push(`handle#${indice}`);
        const fila = await estado.db.getQuery("SELECT tenant_slug FROM tenant_identity WHERE id = 1");
        if (fila.tenant_slug !== tenantB.slug) errores.push(`db#${indice}=${fila.tenant_slug}`);
      }
      return errores;
    });

    let capturado = null;
    try {
      await runWithTenantHandle(handleA, async () => {
        await delay(8);
        await estado.db.runQuery("SELECT 1");
        throw new Error("boom-A");
      });
    } catch (error) {
      capturado = error;
    }
    assertSame(capturado && capturado.message, "boom-A", "el error de un callback async se propaga intacto");
    assertSame(hasTenantContext(), false, "tras el rechazo el contexto de A desaparecio");
    const erroresB = await ramaB;
    assertEqual(erroresB.length, 0, `el contexto concurrente de B quedo intacto: ${JSON.stringify(erroresB.slice(0, 3))}`);

    let sincrono = null;
    try { runWithTenantHandle(handleA, () => { throw new Error("boom-sync"); }); } catch (error) { sincrono = error; }
    assertSame(sincrono && sincrono.message, "boom-sync", "el error de un callback sincronico se propaga intacto");
    assertSame(hasTenantContext(), false, "tras el throw sincronico tampoco queda contexto");

    // El error NO cierra conexiones ni invalida el cache del registry.
    assertEqual((await mt1f1Consultar(handleA.db, "SELECT 1 AS uno"))[0].uno, 1, "la conexion de A sigue abierta");
    const otraVez = await mt1f1Resolver(tenantA, estado.escenario.controlDbPath);
    assertSame(otraVez.handle, handleA, "el registry conserva el mismo handle publicado de A");

    // Ningun tenant 'ultimo usado' se vuelve el default.
    for (let indice = 0; indice < 30; indice += 1) {
      await runWithTenantHandle(indice % 2 === 0 ? handleA : handleB, async () => { await estado.db.getQuery("SELECT 1 AS uno"); });
      assertSame(getTenantHandle(), null, `tras la corrida #${indice} no queda handle por defecto`);
    }
    const singleton = estado.db.getDb();
    assertSame(singleton === handleA.db || singleton === handleB.db, false, "fuera de contexto getDb vuelve al singleton, no a un tenant previo");
    const aperturas = estado.instrumento.de(estado.decoyPath);
    assertEqual(aperturas.length, 1, "recien FUERA de contexto se abre el singleton legacy");
    assertSame(singleton, aperturas[0].instancia, "y es la instancia singleton sobre el decoy");
    assertEqual(mt1f2AperturasProhibidas(estado.instrumento, estado.decoyPath).guernica, 0, "database/guernica.db real jamas se abre");
  } finally {
    await mt1f2Cerrar(estado);
  }
}

// ====================================================================================================
// MT-1F3: middleware de contexto de tenant por request (backend/tenantRequestMiddleware.js) cableado en
// backend/server.js. Dos niveles de prueba:
//  - END-TO-END: backend/server.js REAL como proceso hijo en modo central + multi, con Host real sobre
//    http.request (fetch no permite fijar Host). En multi el GUERNICA_DB_PATH del hijo apunta a un path
//    INEXISTENTE: cualquier fallback al singleton legacy abriria ese path sin OPEN_CREATE y tumbaria el
//    proceso, lo que el test detecta. database/guernica.db real jamas se abre.
//  - EN PROCESO: app Express minima con el MISMO middleware, para observar el contexto ALS real y el
//    diagnostico interno. El singleton de db.js se ejercita solo via instancia aislada sobre un decoy.
// El Host resuelve CONTEXTO, no autoriza: nada de esto prueba ni afirma autorizacion (eso es MT-1F4).
// ====================================================================================================
// MT-1F4: servidor real, Control desechable y colision deliberada admin/id entre A y B.
// AUTH-CONFIG-FIX-B1: bridge=true (shadow) por default -- central+multi ya no arranca con bridge
// off (backend/server.js), y ninguno de los escenarios de este helper depende de que el bridge este
// apagado (las fixtures de control DB se siembran por SQL directo, nunca via el bridge). El unico
// llamador que ejercita el bridge en si (testMT1F4MultiBridgeUsaEmpresaExplicita) ya pasaba
// {bridge:true} explicito -- queda igual, ahora redundante pero inofensivo.
async function mt1f4ConEscenario(fn, { membershipB = true, bridge = true } = {}) {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  const decoyPath = tempDbPath();
  try {
    const control = await bootstrapControlDb(escenario.controlDbPath, { seed: false });
    try {
      for (const tenant of escenario.tenants) {
        tenant.local = (await allSql(tenant.dbPath, "SELECT * FROM usuarios WHERE usuario = 'admin'"))[0];
        await runSql(tenant.dbPath, "UPDATE usuarios SET rol = 'colaborador' WHERE id = ?", [tenant.local.id]);
        tenant.password = `CentralF4-${tenant.tag}-123`;
        tenant.central = await crearUsuarioCentral(control, { nombre: `Central ${tenant.tag}`, usuarioReferencia: "admin", passwordHash: await bcrypt.hash(tenant.password, 10) });
        if (tenant.tag === "a" || membershipB) {
          tenant.membership = await crearMembership(control, { usuarioId: tenant.central.id, empresaId: tenant.empresa.id, usuarioLocalId: tenant.local.id, rol: "admin" });
        }
      }
    } finally { await closeControlDb(control); }
    const [a, b] = escenario.tenants;
    assertEqual(a.local.id, b.local.id, "colision local deliberada: mismo ID");
    assertSame(a.local.usuario, b.local.usuario, "colision local deliberada: mismo login");
    await mt1f3ConServidor({ ...mt1f3EntornoMulti(escenario, decoyPath), ATLAS_USER_BRIDGE_MODE: bridge ? "shadow" : "off" }, async (servidor) => {
      const pedir = (tenant, metodo, ruta, cuerpo = null, token = null, cabecerasExtra = null) => mt1f3Pedir(servidor.port, { host: mt1f3Host(tenant), metodo, ruta, cuerpo, autorizacion: token ? `Bearer ${token}` : null, cabecerasExtra });
      const loginTenant = async (tenant) => {
        const respuesta = await pedir(tenant, "POST", "/login", { usuario: "admin", password: tenant.password });
        assertEqual(respuesta.status, 200, `login ${tenant.tag}: ${respuesta.texto}`);
        assertSame(typeof respuesta.json.token, "string", "login emite token");
        return respuesta.json.token;
      };
      await fn({ escenario, a, b, pedir, loginTenant });
      assertSame(servidor.salio(), null, "servidor permanece vivo sin fallback");
    });
    assertSame(fs.existsSync(decoyPath), false, "singleton inexistente no se crea");
  } finally { await mt1f1Limpiar(escenario); }
}

async function mt1f4Sesion(tenant, token) {
  return (await allSql(tenant.dbPath, "SELECT * FROM sesiones WHERE token = ?", [token]))[0];
}

async function testMT1F4MultiLoginUsaTenantContexto() {
  await mt1f4ConEscenario(async ({ a, b, pedir, loginTenant }) => {
    for (const [tenant, otro] of [[a, b], [b, a]]) {
      const token = await loginTenant(tenant);
      const sesion = await mt1f4Sesion(tenant, token);
      assertSame(sesion.auth_mode, "central", "procedencia central");
      assertEqual(sesion.empresa_id, tenant.empresa.id, "empresa del Host/ALS");
      assertEqual(sesion.membership_id, tenant.membership.id, "membership de ese tenant");
      assertEqual(sesion.central_id, tenant.central.id, "identidad central correcta");
      assertSame(await mt1f4Sesion(otro, token), undefined, "sesion solo en su DB");
      assertEqual((await pedir(tenant, "GET", "/configuracion", null, token)).status, 200, "sesion revalidable sin slug de entorno");
    }
  });
}

async function testMT1F4MultiLoginMembershipOtroTenantNoAutoriza() {
  await mt1f4ConEscenario(async ({ a, b, pedir, loginTenant }) => {
    await loginTenant(a);
    const rechazo = await pedir(b, "POST", "/login", { usuario: a.local.usuario, password: a.password, empresaSlug: a.slug, empresaId: a.empresa.id });
    assertSame(mt1f3EsNoAutenticado(rechazo), true, "credencial A no autoriza B aunque usuario local exista y body reclame A");
    assertEqual((await allSql(b.dbPath, "SELECT * FROM sesiones")).length, 0, "B no emite sesion");
  }, { membershipB: false });
}

async function testMT1F4MultiColisionUsuarioABNoCruzaMembership() {
  await mt1f4ConEscenario(async ({ a, b, pedir, loginTenant }) => {
    for (const [tenant, otro] of [[a, b], [b, a]]) {
      const rechazo = await pedir(tenant, "POST", "/login", { usuario: "admin", password: otro.password });
      assertSame(mt1f3EsNoAutenticado(rechazo), true, "mismo usuario/id local no cruza identidades centrales");
      assertEqual((await allSql(tenant.dbPath, "SELECT * FROM sesiones")).length, 0, "sin sesion por credencial ajena");
      const token = await loginTenant(tenant);
      assertEqual((await mt1f4Sesion(tenant, token)).central_id, tenant.central.id, "credencial propia resuelve su membership");
      await pedir(tenant, "POST", "/logout", null, token);
    }
  });
}

async function testMT1F4MultiSesionValidaLigadaATenant() {
  await mt1f4ConEscenario(async ({ escenario, a, pedir, loginTenant }) => {
    const token = await loginTenant(a);
    const sesion = await mt1f4Sesion(a, token);
    const binding = (await allSql(escenario.controlDbPath, "SELECT * FROM usuario_empresas WHERE id = ?", [sesion.membership_id]))[0];
    assertEqual(sesion.usuario_id, a.local.id, "ID local persistido sin endpoint debug");
    assertEqual(binding.usuario_local_id, sesion.usuario_id, "Control vincula exactamente ese usuario local");
    assertEqual(binding.usuario_id, sesion.central_id, "Control vincula identidad central");
    assertEqual(binding.empresa_id, sesion.empresa_id, "Control vincula empresa");
    assertSame(sesion.rol, "admin", "rol de membership, local es colaborador");
    for (let i = 0; i < 2; i += 1) assertEqual((await pedir(a, "GET", "/configuracion", null, token)).status, 200, "revalidacion real repetida");
    assertSame(Boolean(await mt1f4Sesion(a, token)), true, "slug env vacio no revoca A");
  });
}

async function testMT1F4MultiSesionCrossTenantFailsClosed() {
  await mt1f4ConEscenario(async ({ a, b, pedir, loginTenant }) => {
    const token = await loginTenant(a);
    assertSame(mt1f3EsNoAutenticado(await pedir(b, "GET", "/configuracion", null, token)), true, "token A ausente en B");
    const sesion = await mt1f4Sesion(a, token);
    for (const empresaId of [a.empresa.id, b.empresa.id]) {
      await runSql(b.dbPath, "INSERT INTO sesiones (token, usuario_id, nombre, rol, expira, auth_mode, central_id, membership_id, empresa_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)", [token, sesion.usuario_id, sesion.nombre, sesion.rol, sesion.expira, sesion.auth_mode, sesion.central_id, sesion.membership_id, empresaId]);
      assertSame(mt1f3EsNoAutenticado(await pedir(b, "GET", "/configuracion", null, token)), true, "fila inyectada denegada por empresa/membership incluso con empresa_id B");
      assertSame(await mt1f4Sesion(b, token), undefined, "fila ajena revocada en B");
      assertEqual((await pedir(a, "GET", "/configuracion", null, token)).status, 200, "A no se revoca por rechazo en B");
    }
  });
}

async function testMT1F4MultiMembershipYEmpresaRevocanSesion() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir, loginTenant }) => {
    const control = escenario.controlDbPath;
    const restaurar = async () => {
      await runSql(control, "UPDATE usuarios SET activo = 1 WHERE id = ?", [a.central.id]);
      await runSql(control, "INSERT OR REPLACE INTO usuario_empresas (id, usuario_id, empresa_id, usuario_local_id, rol, activo) VALUES (?, ?, ?, ?, 'admin', 1)", [a.membership.id, a.central.id, a.empresa.id, a.local.id]);
    };
    const cambios = [
      ["UPDATE usuario_empresas SET activo = 0 WHERE id = ?", [a.membership.id]],
      ["DELETE FROM usuario_empresas WHERE id = ?", [a.membership.id]],
      ["UPDATE usuario_empresas SET usuario_id = ? WHERE id = ?", [b.central.id, a.membership.id]],
      ["UPDATE usuario_empresas SET usuario_local_id = 987654 WHERE id = ?", [a.membership.id]],
      ["UPDATE usuarios SET activo = 0 WHERE id = ?", [a.central.id]]
    ];
    for (const [sql, params] of cambios) {
      await restaurar();
      const token = await loginTenant(a);
      await runSql(control, sql, params);
      assertSame(mt1f3EsNoAutenticado(await pedir(a, "GET", "/configuracion", null, token)), true, `revocacion: ${sql}`);
      assertSame(await mt1f4Sesion(a, token), undefined, "sesion revocada sin rebind");
    }
    await restaurar();
    for (const columna of ["central_id", "membership_id", "empresa_id"]) {
      const token = await loginTenant(a);
      await runSql(a.dbPath, `UPDATE sesiones SET ${columna} = -1 WHERE token = ?`, [token]);
      assertSame(mt1f3EsNoAutenticado(await pedir(a, "GET", "/configuracion", null, token)), true, `ancla invalida ${columna}`);
    }
    const token = await loginTenant(a);
    await runSql(control, "UPDATE empresas SET activa = 0 WHERE id = ?", [a.empresa.id]);
    assertSame(mt1f3EsNoAutenticado(await pedir(a, "GET", "/configuracion", null, token)), true, "empresa inactiva falla cerrado desde routing/revalidacion");
    const tokenB = await loginTenant(b);
    assertEqual((await pedir(b, "GET", "/configuracion", null, tokenB)).status, 200, "empresa B permanece autorizada");
  });
}

async function testMT1F4MultiBridgeUsaEmpresaExplicita() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir, loginTenant }) => {
    const tokens = new Map([[a, await loginTenant(a)], [b, await loginTenant(b)]]);
    const creados = new Map();
    for (const tenant of [a, b]) {
      const payload = { nombre: "Bridge F4", usuario: "bridge-f4", password: "BridgeF4pass123", confirmar_password: "BridgeF4pass123", rol: "colaborador", activo: true };
      const respuesta = await pedir(tenant, "POST", "/usuarios", payload, tokens.get(tenant));
      assertEqual(respuesta.status, 200, `bridge create ${tenant.tag}: ${respuesta.texto}`);
      const local = (await allSql(tenant.dbPath, "SELECT * FROM usuarios WHERE usuario = 'bridge-f4'"))[0];
      const membership = (await allSql(escenario.controlDbPath, "SELECT * FROM usuario_empresas WHERE empresa_id = ? AND usuario_local_id = ?", [tenant.empresa.id, local.id]))[0];
      assertSame(Boolean(membership), true, "create sincroniza empresa explicita");
      creados.set(tenant, { local, membership });
    }
    assertEqual(creados.get(a).local.id, creados.get(b).local.id, "bridge tambien usa IDs locales colisionados");
    assertSame(creados.get(a).membership.usuario_id !== creados.get(b).membership.usuario_id, true, "create no auto-link entre empresas");
    for (const [tenant, otro] of [[a, b], [b, a]]) {
      const { local, membership } = creados.get(tenant);
      const fotoOtro = JSON.stringify(await allSql(escenario.controlDbPath, "SELECT m.*, u.password_hash FROM usuario_empresas m JOIN usuarios u ON u.id = m.usuario_id WHERE m.empresa_id = ?", [otro.empresa.id]));
      const pedirCambio = async (metodo, ruta, cuerpo, cabecerasExtra = null) => {
        const respuesta = await pedir(tenant, metodo, ruta, cuerpo, tokens.get(tenant), cabecerasExtra);
        assertEqual(respuesta.status, 200, `${ruta}: ${respuesta.texto}`);
      };
      // AUTH-SYNC-B2-S1A2B-PROFILE-GUARD: rol/activo se envian IGUALES a los locales actuales
      // (colaborador/true, creados asi en la linea 35933) -- PUT ya no sincroniza acceso bajo
      // ningun payload, asi que esta llamada ahora es puramente perfil-only por diseno.
      await pedirCambio("PUT", `/usuarios/${local.id}`, { nombre: "Bridge edit", usuario: "bridge-f4", rol: "colaborador", activo: true });
      assertSame((await allSql(escenario.controlDbPath, "SELECT rol FROM usuario_empresas WHERE id = ?", [membership.id]))[0].rol, "colaborador", "PUT ya no sincroniza rol -- membership permanece intacta");
      // AUTH-SYNC-B2-S1b2 (adaptacion autorizada): en auth central PATCH estado es central-first via el
      // writer idempotente S1b1 -- confirma en la membership de la empresa EXPLICITA del tenant, con
      // lapida y respuesta durable; la Business DB local no cambia (sin proyeccion en este slice).
      const membershipAntesEstado = (await allSql(escenario.controlDbPath, "SELECT activo, version FROM usuario_empresas WHERE id = ?", [membership.id]))[0];
      const claveEstado = nuevaIdempotencyKeyHeader();
      const patchEstado = await pedir(tenant, "PATCH", `/usuarios/${local.id}/estado`, { activo: false, expected_version: Number(membershipAntesEstado.version) }, tokens.get(tenant), claveEstado);
      assertEqual(patchEstado.status, 200, `PATCH estado central-first debe confirmar: ${patchEstado.texto}`);
      assertSame(patchEstado.json.code, "ESTADO_ACTUALIZADO", "codigo funcional de exito");
      assertSame(patchEstado.json.sincronizacion_tenant, "pendiente_al_commit", "estado de sincronizacion conocido al commit");
      const membershipDespuesEstado = (await allSql(escenario.controlDbPath, "SELECT activo, version, empresa_id FROM usuario_empresas WHERE id = ?", [membership.id]))[0];
      assertSame(JSON.stringify([membershipDespuesEstado.activo, membershipDespuesEstado.version, membershipDespuesEstado.empresa_id]), JSON.stringify([0, Number(membershipAntesEstado.version) + 1, tenant.empresa.id]), "activo=0 y una generacion exacta en la membership de la empresa explicita");
      const pendienteEstado = (await allSql(escenario.controlDbPath, "SELECT estado, version_objetivo, empresa_id FROM sync_pendiente WHERE membership_id = ? AND tipo_operacion = 'rol_activo'", [membership.id]))[0];
      assertSame(JSON.stringify([pendienteEstado.estado, pendienteEstado.version_objetivo, pendienteEstado.empresa_id]), JSON.stringify(["pendiente", Number(membershipAntesEstado.version) + 1, tenant.empresa.id]), "lapida rol_activo durable con la generacion confirmada");
      const idempotenciaEstado = (await allSql(escenario.controlDbPath, "SELECT estado, resultado_http, resultado_json FROM operacion_idempotencia WHERE clave = ?", [claveEstado["Idempotency-Key"]]))[0];
      assertSame(JSON.stringify([idempotenciaEstado.estado, idempotenciaEstado.resultado_http]), JSON.stringify(["confirmada", 200]), "operacion de idempotencia confirmada");
      assertSame(idempotenciaEstado.resultado_json, JSON.stringify(patchEstado.json), "resultado durable = respuesta HTTP");
      assertEqual((await allSql(tenant.dbPath, "SELECT activo FROM usuarios WHERE id = ?", [local.id]))[0].activo, 1, "Business DB local sin cambio de estado (sin proyeccion)");
      const password = `BridgeNuevo-${tenant.tag}-456`;
      await pedirCambio("PATCH", `/usuarios/${local.id}/password`, { password, confirmar_password: password }, nuevaIdempotencyKeyHeader());
      const central = (await allSql(escenario.controlDbPath, "SELECT password_hash FROM usuarios WHERE id = ?", [membership.usuario_id]))[0];
      assertSame(await bcrypt.compare(password, central.password_hash), true, "password sincroniza identidad correcta");
      assertSame(JSON.stringify(await allSql(escenario.controlDbPath, "SELECT m.*, u.password_hash FROM usuario_empresas m JOIN usuarios u ON u.id = m.usuario_id WHERE m.empresa_id = ?", [otro.empresa.id])), fotoOtro, "los cuatro bridges no mutan otra empresa");
    }
  }, { bridge: true });
}

async function testMT1F4MultiLogoutNoRevocaOtroTenant() {
  await mt1f4ConEscenario(async ({ a, b, pedir, loginTenant }) => {
    const tokenA = await loginTenant(a);
    const tokenB = await loginTenant(b);
    assertEqual((await pedir(a, "POST", "/logout", null, tokenB)).status, 200, "logout publico en A");
    assertEqual((await pedir(b, "GET", "/configuracion", null, tokenB)).status, 200, "token B sigue autorizado");
    assertSame(Boolean(await mt1f4Sesion(b, tokenB)), true, "fila B intacta");
    await pedir(a, "POST", "/logout", null, tokenA);
    assertSame(await mt1f4Sesion(a, tokenA), undefined, "logout propio borra A");
    assertSame(mt1f3EsNoAutenticado(await pedir(a, "GET", "/configuracion", null, tokenA)), true, "token A revocado");
  });
}

// Ejecuta funciones REALES de server.js aisladas, sin arrancar servidor ni agregar endpoints.
// Permite inducir contexto ausente/corrupto y resultado central inconsistente, imposibles desde Host sano.
function mt1f4AuthAislada(overrides = {}) {
  const fuente = fs.readFileSync(path.join(ROOT, "backend/server.js"), "utf8");
  const nombres = ["empresaAuthDelRequest", "rechazarNoAutenticado", "requireAuth", "loginCentral", "responderFalloAuthCentral"];
  const funciones = nombres.map((nombre) => {
    const match = fuente.match(new RegExp(`^(?:async )?function ${nombre}\\([^]*?^\\}`, "m"));
    if (!match) throw new Error(`Funcion real no encontrada: ${nombre}`);
    return match[0];
  }).join("\n");
  const prohibido = () => { throw new Error("Acceso fuera del contexto autorizado"); };
  return require("vm").runInNewContext(`${funciones}\n({ ${nombres.join(", ")} })`, {
    ATLAS_TENANCY_MODE: "multi", TENANCY_MODES, ATLAS_AUTH_MODE: "central", ATLAS_EMPRESA_SLUG: "fallback-prohibido",
    PREAUTH_UNIFORME: true, getTenantContext: () => null,
    responderNoAutenticado: require("../backend/tenantRequestMiddleware").responderNoAutenticado,
    getQuery: prohibido, runQuery: prohibido, autenticarCredencialCentral: prohibido, revalidarSesionCentral: prohibido,
    esRutaPublicaSinAuth: () => false, process: { env: { GUERNICA_DB_PATH: "fallback-prohibido" } }, console,
    ...overrides
  });
}

async function testMT1F4MultiSinContextoNoFallback() {
  const respuesta = () => ({ statusCode: 200, status(code) { this.statusCode = code; return this; }, json(body) { this.body = body; return this; } });
  for (const contexto of [null, {}, { empresaId: 0, empresaSlug: "a" }, { empresaId: 1.5, empresaSlug: "a" }, { empresaId: "1", empresaSlug: "a" }, { empresaId: 1, empresaSlug: "" }, { empresaId: 1, empresaSlug: " a " }]) {
    const auth = mt1f4AuthAislada({ getTenantContext: () => contexto });
    assertSame(auth.empresaAuthDelRequest(), null, "contexto invalido no toma env/body/ultimo tenant");
    const loginRes = respuesta();
    await auth.loginCentral({ body: { empresaSlug: "fallback-prohibido" } }, loginRes, { usuario: "admin", password: "123" });
    assertEqual(loginRes.statusCode, 401, "sin contexto login rechaza antes de DB/Control");
    const authRes = respuesta();
    await auth.requireAuth({ path: "/configuracion", headers: { authorization: "Bearer valido" } }, authRes, () => { throw new Error("next no autorizado"); });
    assertEqual(authRes.statusCode, 401, "sin contexto requireAuth rechaza antes de DB/Control");
  }
  let autenticaciones = 0;
  const auth = mt1f4AuthAislada({
    getTenantContext: () => ({ empresaId: 1, empresaSlug: "a" }),
    getQuery: async () => ({ id: 7 }),
    autenticarCredencialCentral: async ({ empresaSlug, usuarioLocalId }) => {
      autenticaciones += 1;
      assertSame(empresaSlug, "a", "se pasa slug ALS");
      assertEqual(usuarioLocalId, 7, "se pasa ID local");
      return { ok: true, empresa: { id: 2 } };
    }
  });
  const res = respuesta();
  await auth.loginCentral({}, res, { usuario: "admin", password: "123" });
  assertEqual(autenticaciones, 1, "resultado central inconsistente ejercitado");
  assertEqual(res.statusCode, 401, "empresa distinta no emite token ni escribe sesion");
}

async function testMT1F4MultiLoginNoEnumeraMembership() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir }) => {
    const respuestas = [];
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "no-existe-f4", password: a.password }));
    respuestas.push(await pedir(b, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuario_empresas SET activo = 0 WHERE id = ?", [a.membership.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuario_empresas SET activo = 1 WHERE id = ?", [a.membership.id]);
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET activo = 0 WHERE id = ?", [a.central.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: a.password }));
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET activo = 1 WHERE id = ?", [a.central.id]);
    respuestas.push(await pedir(a, "POST", "/login", { usuario: "admin", password: "incorrecta" }));
    const firma = (r) => JSON.stringify([r.status, r.contentType, r.texto]);
    for (const r of respuestas) {
      assertSame(mt1f3EsNoAutenticado(r), true, "login anonimo generico sin token");
      assertSame(firma(r), firma(respuestas[0]), "mismo 401, Content-Type y body");
    }
    assertEqual((await allSql(a.dbPath, "SELECT * FROM sesiones")).length, 0, "ningun fallo emite sesion A");
    assertEqual((await allSql(b.dbPath, "SELECT * FROM sesiones")).length, 0, "ningun fallo emite sesion B");
    await runSql(escenario.controlDbPath, "UPDATE usuarios SET intentos_fallidos = 99, bloqueado_hasta = ? WHERE id = ?", [new Date(Date.now() + 600000).toISOString(), a.central.id]);
    assertEqual((await pedir(a, "POST", "/login", { usuario: "admin", password: a.password })).status, 429, "lockout central conserva 429");
    await runSql(escenario.controlDbPath, "ALTER TABLE usuario_empresas RENAME TO membresias_indisponibles_f4");
    const operacional = await pedir(a, "POST", "/login", { usuario: "admin", password: a.password });
    assertEqual(operacional.status, 503, "error operacional Control conserva 503");
    assertSame(operacional.json.message, "Servicio de autenticacion no disponible", "503 no filtra detalles Control");
  }, { membershipB: false });
}

// ====================================================================================================
// MT-1F5A: la cola de ingreso fisico de stock (backend/server.js) pasa de UNA sola Promise
// process-global a una lane por tenant (Map<key, Promise>). Los tests extraen el codigo REAL de
// server.js via vm (misma tecnica que mt1f4AuthAislada) en vez de reimplementar la logica, para
// probar el comportamiento shippeado, no una copia.
// ====================================================================================================
function mt1f5aColaAislada(overrides = {}) {
  const fuente = fs.readFileSync(path.join(ROOT, "backend/server.js"), "utf8");
  const constantes = fuente.match(/^const stockIngresoFisicoQueues = new Map\(\);\r?\nconst STOCK_INGRESO_FISICO_QUEUE_KEY_SINGLE = "single";\r?$/m);
  if (!constantes) throw new Error("Constantes reales de la cola de stock no encontradas en server.js");
  const nombresFn = ["resolverStockIngresoFisicoQueueKey", "encolarIngresoFisicoStock"];
  const funciones = nombresFn.map((nombre) => {
    const match = fuente.match(new RegExp(`^(?:async )?function ${nombre}\\([^]*?^\\}`, "m"));
    if (!match) throw new Error(`Funcion real no encontrada: ${nombre}`);
    return match[0];
  }).join("\n");
  const bloque = `${constantes[0]}\n${funciones}`;
  const nombres = ["stockIngresoFisicoQueues", "resolverStockIngresoFisicoQueueKey", "encolarIngresoFisicoStock"];
  return require("vm").runInNewContext(`${bloque}\n({ ${nombres.join(", ")} })`, {
    ATLAS_TENANCY_MODE: "multi",
    TENANCY_MODES,
    getTenantContext: () => null,
    ...overrides
  });
}

async function testMT1F5AColaStockSeParticionaPorTenant() {
  let contextoActual = null;
  const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext: () => contextoActual });
  const eventos = [];

  let liberarA;
  const gateA = new Promise((resolve) => { liberarA = resolve; });

  contextoActual = { empresaId: 501 };
  const promesaA = encolarIngresoFisicoStock(async () => {
    eventos.push("A-inicio");
    await gateA;
    eventos.push("A-fin");
    return "A";
  });

  contextoActual = { empresaId: 502 };
  const promesaB = encolarIngresoFisicoStock(async () => {
    eventos.push("B-inicio");
    eventos.push("B-fin");
    return "B";
  });

  const resultadoB = await promesaB;
  assertSame(resultadoB, "B", "B (tenant 502) debe completar sin esperar a A (tenant 501)");
  assertSame(eventos.includes("A-fin"), false, "A debe seguir pendiente en su gate cuando B ya termino: sin head-of-line blocking cruzado");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A-inicio", "B-inicio", "B-fin"]), "orden de eventos: B se ejecuta y termina integramente mientras A sigue bloqueado en su propio gate");

  liberarA();
  const resultadoA = await promesaA;
  assertSame(resultadoA, "A", "A completa recien al liberar su gate, en su propia lane");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A-inicio", "B-inicio", "B-fin", "A-fin"]), "orden final: A termina despues, sin haber afectado a B");
}

async function testMT1F5AMismoTenantConservaSerializacion() {
  const contexto = { empresaId: 601 };
  const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext: () => contexto });
  const eventos = [];

  let liberarA1;
  const gateA1 = new Promise((resolve) => { liberarA1 = resolve; });
  const promesaA1 = encolarIngresoFisicoStock(async () => {
    eventos.push("A1-inicio");
    await gateA1;
    eventos.push("A1-fin");
    return "A1";
  });
  const promesaA2 = encolarIngresoFisicoStock(async () => {
    eventos.push("A2-inicio");
    return "A2";
  });

  // Evidencia primaria: la dependencia estructural de la cadena de promesas (A2 solo puede
  // iniciar despues de que A1 asiente, sea cual sea el timing real). El delay es solo una
  // confirmacion adicional, no la prueba.
  await delay(30);
  assertSame(JSON.stringify(eventos), JSON.stringify(["A1-inicio"]), "A2 no debe iniciar mientras A1 (mismo tenant) sigue pendiente en su gate");

  liberarA1();
  const [resultadoA1, resultadoA2] = await Promise.all([promesaA1, promesaA2]);
  assertSame(resultadoA1, "A1", "A1 completa tras liberar su gate");
  assertSame(resultadoA2, "A2", "A2 completa despues de A1");
  assertSame(JSON.stringify(eventos), JSON.stringify(["A1-inicio", "A1-fin", "A2-inicio"]), "orden estricto: A1 termina antes de que A2 inicie, mismo tenant sigue serializado FIFO");

  // Una operacion rechazada no debe envenenar la lane: la siguiente operacion del MISMO tenant
  // debe seguir ejecutandose con normalidad.
  let capturado = null;
  try {
    await encolarIngresoFisicoStock(async () => { throw new Error("falla deliberada A3"); });
  } catch (error) {
    capturado = error;
  }
  assertSame(capturado?.message, "falla deliberada A3", "A3 rechaza propagando el error real del callback");

  const resultadoA4 = await encolarIngresoFisicoStock(async () => "A4");
  assertSame(resultadoA4, "A4", "una operacion posterior del MISMO tenant sigue ejecutandose tras un fallo previo: la lane no queda envenenada");
}

async function testMT1F5AColaPreservaContextoTenant() {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  try {
    const [resultadoA, resultadoB] = await Promise.all([
      mt1f1Resolver(escenario.tenants[0], escenario.controlDbPath),
      mt1f1Resolver(escenario.tenants[1], escenario.controlDbPath)
    ]);
    assertSame(resultadoA.ok, true, "handle A debe resolver");
    assertSame(resultadoB.ok, true, "handle B debe resolver");
    const handleA = resultadoA.handle;
    const handleB = resultadoB.handle;

    // getTenantContext REAL (no mockeado): probamos que la cola vm-extraida, corriendo dentro de
    // runWithTenantHandle REAL, ve el contexto ALS verdadero -- no una copia de test.
    const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ getTenantContext });

    const valorA = `f5a-marca-a-${Date.now()}`;
    const valorB = `f5a-marca-b-${Date.now()}`;

    const promesaA = runWithTenantHandle(handleA, () => encolarIngresoFisicoStock(async () => {
      const contexto = getTenantContext();
      assertEqual(contexto.empresaId, escenario.tenants[0].empresa.id, "callback encolado desde A ve el empresaId de A dentro de la lane");
      await dbRunQuery("INSERT OR REPLACE INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('f5a_marca_disponible', ?, 'test', datetime('now'))", [JSON.stringify(valorA)]);
      return "A";
    }));

    const promesaB = runWithTenantHandle(handleB, () => encolarIngresoFisicoStock(async () => {
      const contexto = getTenantContext();
      assertEqual(contexto.empresaId, escenario.tenants[1].empresa.id, "callback encolado desde B ve el empresaId de B dentro de la lane");
      await dbRunQuery("INSERT OR REPLACE INTO configuracion_global (clave, valor, seccion, actualizado_en) VALUES ('f5a_marca_disponible', ?, 'test', datetime('now'))", [JSON.stringify(valorB)]);
      return "B";
    }));

    const [okA, okB] = await Promise.all([promesaA, promesaB]);
    assertSame(okA, "A", "operacion A completa dentro de su propia lane/contexto");
    assertSame(okB, "B", "operacion B completa dentro de su propia lane/contexto");

    const filaA = (await allSql(escenario.tenants[0].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'f5a_marca_disponible'"))[0];
    const filaB = (await allSql(escenario.tenants[1].dbPath, "SELECT valor FROM configuracion_global WHERE clave = 'f5a_marca_disponible'"))[0];
    assertSame(JSON.parse(filaA.valor), valorA, "la DB fisica de A tiene el valor escrito por el callback A -- prueba empirica, no solo teoria de ALS");
    assertSame(JSON.parse(filaB.valor), valorB, "la DB fisica de B tiene el valor escrito por el callback B, nunca el de A: sin cruce de escritura entre lanes");
  } finally {
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5AMultiSinContextoNoFallback() {
  const contextosInvalidos = [null, {}, { empresaId: 0 }, { empresaId: -1 }, { empresaId: 1.5 }, { empresaId: "1" }];
  for (const contexto of contextosInvalidos) {
    let ejecutado = false;
    const { encolarIngresoFisicoStock } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "multi", getTenantContext: () => contexto });
    let error = null;
    try {
      await encolarIngresoFisicoStock(async () => { ejecutado = true; return "no-debe-pasar"; });
    } catch (err) {
      error = err;
    }
    assertSame(ejecutado, false, `contexto invalido ${JSON.stringify(contexto)}: el callback NO debe ejecutarse`);
    assertSame(error !== null, true, `contexto invalido ${JSON.stringify(contexto)}: debe fallar cerrado (rechazar), nunca caer a una lane global/SINGLE`);
  }

  // Contexto multi valido SI debe ejecutar (no es que la cola este rota en general).
  const { encolarIngresoFisicoStock: encolarValido } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "multi", getTenantContext: () => ({ empresaId: 777, empresaSlug: "ok" }) });
  const resultadoValido = await encolarValido(async () => "ejecutado");
  assertSame(resultadoValido, "ejecutado", "un contexto multi valido SI ejecuta el callback normalmente");

  // Modo single: key estable, getTenantContext NUNCA se consulta (short-circuit antes de leerlo).
  const prohibido = () => { throw new Error("getTenantContext no debe consultarse en modo single"); };
  const { encolarIngresoFisicoStock: encolarSingle, stockIngresoFisicoQueues: colasSingle } = mt1f5aColaAislada({ ATLAS_TENANCY_MODE: "single", getTenantContext: prohibido });
  const resultadoSingle = await encolarSingle(async () => "single-ok");
  assertSame(resultadoSingle, "single-ok", "modo single ejecuta con su key estable sin tocar getTenantContext");
  assertEqual(colasSingle.size, 0, "tras asentarse, la lane single tambien se limpia del Map (sin fuga)");
}

// ====================================================================================================
// MT-1F5B: almacenamiento de uploads tenant-aware. Los helpers de fixture SOLO escriben bajo
// uploads/tenants/<empresaId>/... (namespace que no existia antes de F5B) o bajo un archivo LEGACY con
// nombre inequivocamente de test (mt1f5b-...) -- jamas tocan ninguno de los 61 archivos reales. Todo
// fixture se limpia deterministicamente en finally.
// ====================================================================================================
function mt1f5bRutaTenant(empresaId, categoria, filename) {
  return path.join(ROOT, "uploads", "tenants", String(empresaId), categoria, filename);
}
function mt1f5bSembrarTenant(empresaId, categoria, filename, contenido) {
  const ruta = mt1f5bRutaTenant(empresaId, categoria, filename);
  fs.mkdirSync(path.dirname(ruta), { recursive: true });
  fs.writeFileSync(ruta, contenido, "utf8");
  return ruta;
}
function mt1f5bLimpiarTenant(empresaId) {
  fs.rmSync(path.join(ROOT, "uploads", "tenants", String(empresaId)), { recursive: true, force: true });
}
function mt1f5bRutaLegacy(categoria, filename) {
  return path.join(ROOT, "uploads", categoria, filename);
}
function mt1f5bSembrarLegacy(categoria, filename, contenido) {
  const ruta = mt1f5bRutaLegacy(categoria, filename);
  fs.mkdirSync(path.dirname(ruta), { recursive: true });
  fs.writeFileSync(ruta, contenido, "utf8");
  return ruta;
}
function mt1f5bLimpiarLegacy(categoria, filename) {
  fs.rmSync(mt1f5bRutaLegacy(categoria, filename), { force: true });
}
function mt1f5bNombreTest(etiqueta) {
  return `mt1f5b-test-${etiqueta}-${Date.now()}-${Math.random().toString(16).slice(2, 8)}.txt`;
}
// fetch() trata "Host" como forbidden header y lo ignora silenciosamente (manda el Host real de la
// conexion, no el que uno pide) -- por eso estos tests reusan mt1f3Pedir (http.request crudo, mismo
// mecanismo ya probado por toda la suite MT-1F3/F4/F5A) en vez de fetch().
async function mt1f5bGetTexto(port, ruta, host) {
  const respuesta = await mt1f3Pedir(port, { host, ruta });
  return { status: respuesta.status, texto: respuesta.texto, contentType: respuesta.contentType };
}

async function testMT1F5BMultiWriteUsaRootTenant() {
  const { crearTenantUploadStorage, CATEGORIAS_VALIDAS } = require("../backend/tenantUploadStorage");
  const uploadsRoot = path.join(ROOT, "uploads");
  let contexto = null;
  const storage = crearTenantUploadStorage({ tenancyMode: "multi", getTenantContext: () => contexto, uploadsRoot });

  const tenants = [
    { empresaId: 910001, empresaSlug: "mt1f5b-tenant-a" },
    { empresaId: 910002, empresaSlug: "mt1f5b-tenant-b" },
    { empresaId: 1, empresaSlug: "guernica" }
  ];
  for (const tenant of tenants) {
    contexto = tenant;
    for (const categoria of CATEGORIAS_VALIDAS) {
      const destino = storage.resolverDestinoEscritura({ categoria, filename: "archivo-test.png" });
      assertSame(Boolean(destino), true, `destino de escritura valido: empresaId=${tenant.empresaId} categoria=${categoria}`);
      const relativo = path.relative(path.join(uploadsRoot, "tenants"), destino.ruta);
      const segmentos = relativo.split(path.sep);
      assertSame(segmentos[0], String(tenant.empresaId), `segmento de empresa exacto (empresaId=${tenant.empresaId})`);
      assertSame(segmentos[1], categoria, "segmento de categoria exacto");
      assertSame(segmentos[2], "archivo-test.png", "segmento de filename exacto");
      assertSame(destino.ruta.startsWith(uploadsRoot + path.sep + "tenants" + path.sep), true, "jamas la raiz legacy compartida como destino de escritura en multi (incluye Guernica)");
    }
  }
}

async function testMT1F5BMismoPathAisladoEntreTenants() {
  const { crearTenantUploadStorage } = require("../backend/tenantUploadStorage");
  const uploadsRoot = fs.mkdtempSync(path.join(os.tmpdir(), "mt1f5b-aislado-"));
  try {
    let contexto = { empresaId: 501, empresaSlug: "tenant-a" };
    const storage = crearTenantUploadStorage({ tenancyMode: "multi", getTenantContext: () => contexto, uploadsRoot });

    const destinoA = storage.resolverDestinoEscritura({ categoria: "productos", filename: "mismo.png" });
    fs.mkdirSync(destinoA.directorio, { recursive: true });
    fs.writeFileSync(destinoA.ruta, "CONTENIDO-A");

    contexto = { empresaId: 502, empresaSlug: "tenant-b" };
    const destinoB = storage.resolverDestinoEscritura({ categoria: "productos", filename: "mismo.png" });
    fs.mkdirSync(destinoB.directorio, { recursive: true });
    fs.writeFileSync(destinoB.ruta, "CONTENIDO-B");

    assertSame(destinoA.ruta !== destinoB.ruta, true, "misma categoria+filename produce rutas fisicas distintas para A y B (misma forma de URL externa: productos/mismo.png)");

    contexto = { empresaId: 501, empresaSlug: "tenant-a" };
    const candidatosA = storage.resolverCandidatosLectura({ categoria: "productos", filename: "mismo.png" });
    assertEqual(candidatosA.length, 1, "A no tiene fallback legacy (no es guernica)");
    assertSame(fs.readFileSync(candidatosA[0], "utf8"), "CONTENIDO-A", "lectura bajo contexto A produce bytes de A");

    contexto = { empresaId: 502, empresaSlug: "tenant-b" };
    const candidatosB = storage.resolverCandidatosLectura({ categoria: "productos", filename: "mismo.png" });
    assertSame(fs.readFileSync(candidatosB[0], "utf8"), "CONTENIDO-B", "lectura bajo contexto B produce bytes de B, nunca los de A");
  } finally {
    fs.rmSync(uploadsRoot, { recursive: true, force: true });
  }
}

async function testMT1F5BHostANoLeeArchivoB() {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  const decoyPath = tempDbPath();
  const [tenantA, tenantB] = escenario.tenants;
  const nombreArchivo = mt1f5bNombreTest("solo-b");
  try {
    mt1f5bSembrarTenant(tenantB.empresa.id, "productos", nombreArchivo, "SOLO-B");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      // control: B lee su propio archivo.
      const propio = await mt1f5bGetTexto(servidor.port, `/uploads/productos/${nombreArchivo}`, mt1f3Host(tenantB));
      assertEqual(propio.status, 200, "B lee su propio archivo (control positivo)");
      assertSame(propio.texto, "SOLO-B", "B recibe sus propios bytes");

      // A no tiene ese archivo en su propia raiz: debe fallar cerrado, sin buscar en B ni en legacy.
      const viaA = await mt1f5bGetTexto(servidor.port, `/uploads/productos/${nombreArchivo}`, mt1f3Host(tenantA));
      assertEqual(viaA.status, 404, "A no puede leer un archivo que solo existe en la raiz de B");
      assertSame(viaA.texto.includes("SOLO-B"), false, "la respuesta a A no filtra el contenido de B");
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    mt1f5bLimpiarTenant(tenantB.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

async function testMT1F5BPublicProductosYLogoSinAuth() {
  const escenario = await mt1f1CrearEscenario(["a"]);
  const decoyPath = tempDbPath();
  const [tenantA] = escenario.tenants;
  const nombreProducto = mt1f5bNombreTest("producto-publico");
  const nombreLogo = mt1f5bNombreTest("logo-publico");
  try {
    mt1f5bSembrarTenant(tenantA.empresa.id, "productos", nombreProducto, "IMAGEN-PRODUCTO-PUBLICA");
    mt1f5bSembrarTenant(tenantA.empresa.id, "configuracion", nombreLogo, "IMAGEN-LOGO-PUBLICA");
    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const port = servidor.port;
      const producto = await mt1f5bGetTexto(port, `/uploads/productos/${nombreProducto}`, mt1f3Host(tenantA));
      assertEqual(producto.status, 200, "producto se sirve sin Authorization en central+multi");
      assertSame(producto.texto, "IMAGEN-PRODUCTO-PUBLICA", "bytes correctos de producto");

      const logo = await mt1f5bGetTexto(port, `/uploads/configuracion/${nombreLogo}`, mt1f3Host(tenantA));
      assertEqual(logo.status, 200, "logo se sirve sin Authorization en central+multi");
      assertSame(logo.texto, "IMAGEN-LOGO-PUBLICA", "bytes correctos de logo");

      // el storefront publico sigue alcanzable y no requiere auth: la forma de URL /uploads/... que
      // devuelve (si el producto la tuviera) no cambia -- eso ya lo prueban los tests de arriba.
      const storefront = await mt1f5bGetTexto(port, "/tienda/publica/productos", mt1f3Host(tenantA));
      assertEqual(storefront.status, 200, "el storefront publico sigue respondiendo sin auth");
      const logoInfo = await mt1f5bGetTexto(port, "/tienda/publica", mt1f3Host(tenantA));
      assertEqual(logoInfo.status, 200, "GET /tienda/publica (nombre+logo_url) sigue respondiendo sin auth");
    });
  } finally {
    mt1f5bLimpiarTenant(tenantA.empresa.id);
    await mt1f1Limpiar(escenario);
  }
}

