// Multi + HTTP real + ALS: dos tenants reales, cada uno con su propia credencial DB-managed,
// autenticados via login central real (Host -> tenant middleware -> runWithTenantHandle envuelve
// TODA la cadena, incluida la ruta debug y su llamada fetch() mockeada). No basta con invocar
// resolverCredencial() de forma aislada -- esta prueba ejercita la ruta HTTP real de punta a punta.
async function testMT1F5C3DebugMultiAisladoTokenPorTenant() {
  const escenario = await mt1f1CrearEscenario(["f5c3a", "f5c3b"]);
  const masterKeyAnterior = process.env.ATLAS_INTEGRATION_MASTER_KEY_B64;
  const masterKey = crypto.randomBytes(32).toString("base64");
  const centralPassword = "F5c3CentralPass123!";
  const mockScriptPath = mt1f5c3EscribirMockFetch();
  const mockLogPath = mt1f5c3CrearMockLogPath();
  try {
    process.env.ATLAS_INTEGRATION_MASTER_KEY_B64 = masterKey;
    const servicio = crearIntegracionTenantService({ tenancyMode: "multi", getTenantContext });
    const [tenantA, tenantB] = escenario.tenants;
    const handleA = (await mt1f1Resolver(tenantA, escenario.controlDbPath)).handle;
    const handleB = (await mt1f1Resolver(tenantB, escenario.controlDbPath)).handle;
    const secretoA = "MT1F5C3-multi-tenant-A-secreto";
    const secretoB = "MT1F5C3-multi-tenant-B-secreto";
    await runWithTenantHandle(handleA, () => servicio.establecerCredencial("mercadopago_point", secretoA));
    await runWithTenantHandle(handleA, () => servicio.establecerHabilitado("mercadopago_point", true));
    await runWithTenantHandle(handleB, () => servicio.establecerCredencial("mercadopago_point", secretoB));
    await runWithTenantHandle(handleB, () => servicio.establecerHabilitado("mercadopago_point", true));

    const controlDb = await bootstrapControlDb(escenario.controlDbPath, { seed: false });
    const centralHash = await bcrypt.hash(centralPassword, 10);
    const central = await crearUsuarioCentral(controlDb, { nombre: "MT1F5C3 Central", usuarioReferencia: "mt1f5c3-central", passwordHash: centralHash, activo: 1 });
    for (const tenant of [tenantA, tenantB]) {
      const localAdmin = (await allSql(tenant.dbPath, "SELECT id FROM usuarios WHERE usuario = 'admin'"))[0];
      await crearMembership(controlDb, { usuarioId: central.id, empresaId: tenant.empresa.id, usuarioLocalId: localAdmin.id, rol: "admin", activo: 1 });
    }
    await closeControlDb(controlDb);

    const decoyPath = tempDbPath();
    await mt1f3ConServidor(
      {
        ...mt1f3EntornoMulti(escenario, decoyPath),
        ATLAS_INTEGRATION_MASTER_KEY_B64: masterKey,
        ...mt1f5c3EnvMock(mockScriptPath, mockLogPath, "success")
      },
      async ({ port }) => {
        const loginA = await mt1f3Pedir(port, { host: mt1f3Host(tenantA), metodo: "POST", ruta: "/login", cuerpo: { usuario: "admin", password: centralPassword } });
        assertEqual(loginA.status, 200, "login central real para tenant A debe funcionar");
        const tokenA = loginA.json.token;

        const respA = await mt1f3Pedir(port, { host: mt1f3Host(tenantA), metodo: "GET", ruta: MT1F5C3_TERMINALES_RUTA, autorizacion: `Bearer ${tokenA}` });
        assertEqual(respA.status, 200, "la ruta debug debe responder 200 para tenant A autenticado");
        assertSame(respA.json.ok, true, "tenant A tiene credencial DB_MANAGED habilitada: debe poder consultar terminales");

        const loginB = await mt1f3Pedir(port, { host: mt1f3Host(tenantB), metodo: "POST", ruta: "/login", cuerpo: { usuario: "admin", password: centralPassword } });
        const tokenB = loginB.json.token;
        const respB = await mt1f3Pedir(port, { host: mt1f3Host(tenantB), metodo: "GET", ruta: MT1F5C3_TERMINALES_RUTA, autorizacion: `Bearer ${tokenB}` });
        assertSame(respB.json.ok, true, "tenant B tambien debe poder consultar terminales con su propia credencial");

        const entradas = mt1f5c3LeerMockLog(mockLogPath);
        assertEqual(entradas.length, 2, "deben registrarse exactamente 2 llamadas salientes interceptadas, una por tenant");
        assertSame(entradas[0].authorization, `Bearer ${secretoA}`, "la primera llamada (tenant A via HTTP real) debe usar EXACTAMENTE el secreto de A");
        assertSame(entradas[1].authorization, `Bearer ${secretoB}`, "la segunda llamada (tenant B via HTTP real) debe usar EXACTAMENTE el secreto de B");
        assertSame(entradas[0].authorization !== entradas[1].authorization, true, "los tokens efectivos de A y B jamas deben cruzarse");
      }
    );
  } finally {
    if (masterKeyAnterior === undefined) delete process.env.ATLAS_INTEGRATION_MASTER_KEY_B64;
    else process.env.ATLAS_INTEGRATION_MASTER_KEY_B64 = masterKeyAnterior;
    fs.rmSync(mockScriptPath, { force: true });
    fs.rmSync(mockLogPath, { force: true });
    await mt1f1Limpiar(escenario);
  }
}

// MT-1F5C3-B1B (documentacion explicita de cobertura, exigida por B1A hallazgo 1): esta funcion
// contiene DOS aserciones de naturaleza distinta que NO deben confundirse:
//   1) "sin contexto" (mas abajo, primeras lineas del try) es una INVOCACION DIRECTA DEL SERVICIO
//      (crearIntegracionTenantService + resolverCredencial sin runWithTenantHandle activo) --
//      NO ejercita ninguna ruta HTTP. Se prueba asi porque, en este codebase, el middleware de
//      tenant (tenantRequestMiddleware.js) envuelve TODA la cadena de rutas dentro de
//      runWithTenantHandle antes de que cualquier handler se ejecute en modo multi autenticado --
//      por lo tanto no existe una request HTTP legitima que alcance la ruta debug sin contexto ya
//      establecido, y este edge case solo es observable en el limite del propio servicio.
//   2) "multi nunca usa env" (el resto de la funcion, con mt1f3ConServidor + mt1f3Pedir + Host real)
//      SI es HTTP real de punta a punta: login central real, Host real, la ruta debug real, y el
//      mock de fetch real -- demuestra la propagacion ALS completa, no solo el servicio aislado.
async function testMT1F5C3DebugMultiNuncaUsaEnvNiSinContexto() {
  const envToken = "MT1F5C3-multi-env-jamas";
  const escenario = await mt1f1CrearEscenario(["f5c3multi"]);
  const masterKeyAnterior = process.env.ATLAS_INTEGRATION_MASTER_KEY_B64;
  const masterKey = crypto.randomBytes(32).toString("base64");
  const centralPassword = "F5c3MultiNoEnvPass123!";
  const mockScriptPath = mt1f5c3EscribirMockFetch();
  const mockLogPath = mt1f5c3CrearMockLogPath();
  try {
    process.env.ATLAS_INTEGRATION_MASTER_KEY_B64 = masterKey;
    // Sin fila managed para este tenant: el servicio, en multi, jamas debe caer al env aunque este seteada.
    const servicio = crearIntegracionTenantService({ tenancyMode: "multi", getTenantContext });
    let lanzo = null;
    try { await servicio.resolverCredencial("mercadopago_point"); } catch (error) { lanzo = error; }
    assertSame(lanzo && lanzo.code, "TENANT_CONTEXT_REQUIRED", "sin contexto de tenant activo, resolverCredencial debe fallar cerrado ANTES de considerar env");

    const [tenant] = escenario.tenants;
    const controlDb = await bootstrapControlDb(escenario.controlDbPath, { seed: false });
    const centralHash = await bcrypt.hash(centralPassword, 10);
    const central = await crearUsuarioCentral(controlDb, { nombre: "MT1F5C3 MultiNoEnv", usuarioReferencia: "mt1f5c3-multi-noenv", passwordHash: centralHash, activo: 1 });
    const localAdmin = (await allSql(tenant.dbPath, "SELECT id FROM usuarios WHERE usuario = 'admin'"))[0];
    await crearMembership(controlDb, { usuarioId: central.id, empresaId: tenant.empresa.id, usuarioLocalId: localAdmin.id, rol: "admin", activo: 1 });
    await closeControlDb(controlDb);

    const decoyPath = tempDbPath();
    await mt1f3ConServidor(
      {
        ...mt1f3EntornoMulti(escenario, decoyPath),
        ATLAS_INTEGRATION_MASTER_KEY_B64: masterKey,
        MERCADOPAGO_ACCESS_TOKEN: envToken,
        ...mt1f5c3EnvMock(mockScriptPath, mockLogPath, "success")
      },
      async ({ port }) => {
        const loginResp = await mt1f3Pedir(port, { host: mt1f3Host(tenant), metodo: "POST", ruta: "/login", cuerpo: { usuario: "admin", password: centralPassword } });
        assertEqual(loginResp.status, 200, "login central real debe funcionar");
        const token = loginResp.json.token;

        const resp = await mt1f3Pedir(port, { host: mt1f3Host(tenant), metodo: "GET", ruta: MT1F5C3_TERMINALES_RUTA, autorizacion: `Bearer ${token}` });
        assertEqual(resp.status, 200, "la ruta debug responde 200 (respuesta segura, no una excepcion)");
        assertSame(resp.json.ok, false, "sin fila managed en multi, aunque MERCADOPAGO_ACCESS_TOKEN este seteada, debe fallar de forma segura");
        assertSame(resp.json.origen, "config", "origen debe ser config, nunca un intento fallido contra mercadopago");

    const entradas = mt1f5c3LeerMockLog(mockLogPath);
        assertEqual(entradas.length, 0, "en multi, sin fila managed, jamas debe llamarse a Mercado Pago con el token de env");
      }
    );
  } finally {
    if (masterKeyAnterior === undefined) delete process.env.ATLAS_INTEGRATION_MASTER_KEY_B64;
    else process.env.ATLAS_INTEGRATION_MASTER_KEY_B64 = masterKeyAnterior;
    fs.rmSync(mockScriptPath, { force: true });
    fs.rmSync(mockLogPath, { force: true });
    await mt1f1Limpiar(escenario);
  }
}

// ==== MT-1F5C3-B1B: pruebas negativas exigidas por el hallazgo de auditoria B1A. ====

// Ambas rutas: el proveedor/cliente HTTP falla con un detalle que incluye una credencial ficticia
// identificable (modo "leak" del mock -- simula el peor caso, un error que ecoa la cabecera de
// autorizacion recibida). La respuesta HTTP y los logs del proceso hijo NO deben contener el
// sentinel bajo ninguna circunstancia.
// MT-1F5C3-B1D: version definitiva (post R3/B1D), usa el helper permanente de captura de logs --
// sin instrumentacion diagnostica temporal. Los mensajes de asercion de GET y POST se prefijan
// explicitamente para que un futuro fallo jamas vuelva a ser ambiguo entre ambas rutas (leccion de
// B1C-R0/D1/D2: un mensaje compartido entre 2 aserciones distintas oculto la causa raiz real).
async function testMT1F5C3DebugErrorExternoNoFiltraCredencial() {
  const sentinel = "MT1F5C3-SENTINEL-leak-en-error-a91f";
  const logs = await mt1f5c3ConServidorCapturaLogs(async (baseUrl, dbPath, masterKey) => {
    const adminToken = await login(baseUrl, "admin", "admin123");
    await requestJson(baseUrl, "PUT", "/integraciones/mercadopago-point/credencial", { secret: sentinel }, adminToken);
    await requestJson(baseUrl, "PATCH", "/integraciones/mercadopago-point/credencial/habilitado", { enabled: true }, adminToken);

    const resGet = await requestJson(baseUrl, "GET", MT1F5C3_TERMINALES_RUTA, null, adminToken);
    assertSame(resGet.data.ok, false, "GET: un error de red externo debe resultar en ok:false");
    assertSame(resGet.data.origen, "mercadopago", "GET: origen debe seguir siendo mercadopago en un fallo externo real");
    assertSame(JSON.stringify(resGet.data).includes(sentinel), false, "GET: el sentinel no debe aparecer en la response ante un error externo");
    assertSame(JSON.stringify(resGet.data).includes("Bearer"), false, "GET: la response no debe contener ninguna cabecera de autorizacion");

    const resPost = await requestJson(baseUrl, "POST", MT1F5C3_TEST_ORDEN_RUTA, { terminal_id: "T1", monto: 100 }, adminToken);
    assertSame(resPost.data.ok, false, "POST: un error de red externo en ambas llamadas debe resultar en ok:false");
    assertSame(resPost.data.parcial, false, "POST: si ambas llamadas fallan por red no es un resultado parcial");
    assertSame(resPost.data.payment_intents.ok, false, "POST: payment_intents debe reportar ok:false ante un error de red");
    assertSame(resPost.data.v1_orders.ok, false, "POST: v1_orders debe reportar ok:false ante un error de red");
    assertSame(JSON.stringify(resPost.data).includes(sentinel), false, "POST: el sentinel no debe aparecer en la response ante un error externo");
    assertSame(JSON.stringify(resPost.data).includes("Bearer"), false, "POST: la response no debe contener ninguna cabecera de autorizacion");
  }, { modo: "leak" });
  assertSame(logs.includes(sentinel), false, "el sentinel jamas debe aparecer en stdout/stderr del proceso servidor, ni siquiera en la rama de error");
  assertSame(logs.includes("Bearer"), false, "los logs del proceso servidor no deben contener ninguna cabecera de autorizacion, ni siquiera en la rama de error");
}

// MT-1F5C3-B1D: un HTTP no-2xx del proveedor (sin excepcion de red) jamas debe traducirse en
// ok:true, y el cuerpo de esa respuesta -- deliberadamente adversarial, refleja el Authorization
// recibido -- jamas debe reenviarse al cliente. Cubre 2 defectos reales de R3: la falta de chequeo
// de res.ok en llamarMpDebug, y la exposicion de raw/raw_text/error_red sin sanitizar.
async function testMT1F5C3DebugErrorHttpEsNoExitoso() {
  const sentinel = "MT1F5C3-SENTINEL-http-error-body-c4e1";
  await mt1f5c3ConServidor(async (baseUrl, dbPath, masterKey, mockLogPath) => {
    const adminToken = await login(baseUrl, "admin", "admin123");
    await requestJson(baseUrl, "PUT", "/integraciones/mercadopago-point/credencial", { secret: sentinel }, adminToken);
    await requestJson(baseUrl, "PATCH", "/integraciones/mercadopago-point/credencial/habilitado", { enabled: true }, adminToken);

    const resGet = await requestJson(baseUrl, "GET", MT1F5C3_TERMINALES_RUTA, null, adminToken);
    assertSame(resGet.data.ok, false, "GET: un HTTP no-2xx del proveedor debe resultar en ok:false");
    assertSame(JSON.stringify(resGet.data).includes(sentinel), false, "GET: el cuerpo adversarial del proveedor no debe filtrar el sentinel");

    const resPost = await requestJson(baseUrl, "POST", MT1F5C3_TEST_ORDEN_RUTA, { terminal_id: "T1", monto: 100 }, adminToken);
    assertSame(resPost.data.ok, false, "POST: un HTTP no-2xx en ambas llamadas debe resultar en ok:false");
    assertSame(resPost.data.parcial, false, "POST: si ambas llamadas fallan con HTTP no-2xx no es un resultado parcial");
    assertSame(resPost.data.payment_intents.ok, false, "POST: payment_intents debe reportar ok:false ante HTTP no-2xx");
    assertSame(resPost.data.v1_orders.ok, false, "POST: v1_orders debe reportar ok:false ante HTTP no-2xx");
    assertSame(resPost.data.payment_intents.http_status, 500, "POST: debe preservarse el codigo HTTP numerico devuelto por el proveedor");
    assertSame(resPost.data.v1_orders.http_status, 500, "POST: debe preservarse el codigo HTTP numerico devuelto por el proveedor");
    assertSame(JSON.stringify(resPost.data).includes(sentinel), false, "POST: el cuerpo adversarial del proveedor no debe filtrar el sentinel");
    assertSame(JSON.stringify(resPost.data).includes("raw"), false, "POST: la response publica jamas debe incluir un campo raw/raw_text del proveedor");
  }, { modo: "http_error" });
}

// MT-1F5C3-B1D: exito parcial (una de las 2 llamadas de test-orden 2xx, la otra no) jamas debe
// reportarse como ok:true -- decision funcional congelada en el checkpoint B1D seccion 4.
async function testMT1F5C3DebugParcialSeInformaComoParcial() {
  await mt1f5c3ConServidor(async (baseUrl, dbPath, masterKey, mockLogPath) => {
    const adminToken = await login(baseUrl, "admin", "admin123");
    await requestJson(baseUrl, "PUT", "/integraciones/mercadopago-point/credencial", { secret: "MT1F5C3-partial-token" }, adminToken);
    await requestJson(baseUrl, "PATCH", "/integraciones/mercadopago-point/credencial/habilitado", { enabled: true }, adminToken);

    const resPost = await requestJson(baseUrl, "POST", MT1F5C3_TEST_ORDEN_RUTA, { terminal_id: "T1", monto: 100 }, adminToken);
    assertSame(resPost.data.ok, false, "un exito parcial NUNCA debe reportarse como ok:true");
    assertSame(resPost.data.parcial, true, "debe marcarse explicitamente como resultado parcial");
    assertSame(resPost.data.payment_intents.ok, true, "payment-intents debio ser exitoso en este escenario");
    assertSame(resPost.data.v1_orders.ok, false, "v1/orders debio fallar en este escenario");
    assertSame(typeof resPost.data.message, "string", "debe incluir un mensaje explicando el resultado parcial");
    assertSame(resPost.data.message.toLowerCase().includes("parcial"), true, "el mensaje debe advertir explicitamente que el resultado es parcial");
  }, { modo: "partial" });
}

// El preloader debe rechazar localmente CUALQUIER solicitud no reconocida (dominio distinto o ruta
// MP no reconocida), sin acceder jamas al fetch original ni a la red real. Prueba determinista y
// sin dependencia de conectividad: el mock lanza sincronicamente antes de intentar cualquier
// conexion real. Se ejercita el MISMO modulo (MT1F5C3_MOCK_FETCH_SOURCE) que usan las 2 rutas
// reales, en un proceso hijo minimo sin backend/server.js ni base de datos.
async function testMT1F5C3MockFetchBloqueaSolicitudNoReconocida() {
  const mockScriptPath = mt1f5c3EscribirMockFetch();
  const mockLogPath = mt1f5c3CrearMockLogPath();
  const probeSource = [
    "const assert = require(\"assert\");",
    "(async () => {",
    "  let error1 = null;",
    "  try { await fetch(\"https://example.com/no-es-mercadopago\"); } catch (e) { error1 = e; }",
    "  assert.ok(error1 && /MP_MOCK_BLOCKED_UNEXPECTED_REQUEST/.test(error1.message), \"debe bloquear un dominio no reconocido\");",
    "",
    "  let error2 = null;",
    "  try { await fetch(\"https://api.mercadopago.com/no/es/una/ruta/reconocida\"); } catch (e) { error2 = e; }",
    "  assert.ok(error2 && /MP_MOCK_BLOCKED_UNEXPECTED_REQUEST/.test(error2.message), \"debe bloquear una ruta MP no reconocida aunque el origen sea correcto\");",
    "",
    "  let error3 = null;",
    "  try { await fetch(\"https://api.mercadopago.com.evil.example/terminals/v1/list\"); } catch (e) { error3 = e; }",
    "  assert.ok(error3 && /MP_MOCK_BLOCKED_UNEXPECTED_REQUEST/.test(error3.message), \"debe bloquear un origen que solo contiene el dominio real como substring\");",
    "",
    "  console.log(\"MOCK_FAIL_CLOSED_OK\");",
    "})().catch((e) => { console.error(e.message); process.exit(1); });"
  ].join("\n");
  const probePath = path.join(os.tmpdir(), `mp-mock-probe-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}.js`);
  fs.writeFileSync(probePath, probeSource, "utf8");
  try {
    const resultado = await new Promise((resolve, reject) => {
      const hijo = spawn(process.execPath, [probePath], {
        cwd: ROOT,
        env: { ...process.env, ...mt1f5c3EnvMock(mockScriptPath, mockLogPath, "success") },
        stdio: ["ignore", "pipe", "pipe"]
      });
      let salida = "";
      hijo.stdout.on("data", (d) => { salida += d.toString(); });
      hijo.stderr.on("data", (d) => { salida += d.toString(); });
      hijo.once("exit", (codigo) => resolve({ codigo, salida }));
      hijo.once("error", reject);
    });
    assertEqual(resultado.codigo, 0, `el proceso de prueba del mock debe salir 0: ${resultado.salida}`);
    assertSame(resultado.salida.includes("MOCK_FAIL_CLOSED_OK"), true, "el mock debe bloquear las 3 solicitudes no reconocidas, deterministicamente y sin red real");
    const entradas = mt1f5c3LeerMockLog(mockLogPath);
    assertEqual(entradas.length, 3, "las 3 solicitudes bloqueadas deben quedar registradas");
    assertSame(entradas.every((e) => e.bloqueado === true), true, "toda entrada registrada para una solicitud no reconocida debe estar marcada bloqueado:true");
  } finally {
    fs.rmSync(mockScriptPath, { force: true });
    fs.rmSync(mockLogPath, { force: true });
    fs.rmSync(probePath, { force: true });
  }
}

// ==================================================================================
// MT-1G-D1: certificacion cross-tenant end-to-end (G1, G2, G5, G7). Reutiliza integramente la
// infraestructura F1/F3/F4 ya existente (mt1f1CrearEscenario, mt1f3ConServidor/Pedir/Host/Sembrar,
// mt1f4ConEscenario) -- ningun fixture nuevo salvo el helper de membership dual exigido por G5.
// Contrato de rechazo reutilizado sin cambios: mt1f3EsNoAutenticado (401, uniforme, no-enumerable).
// Endpoint de negocio real elegido tras inspeccionar server.js: GET/POST /productos -- ya estaba
// clasificado como ruta protegida real en MT1F3_RUTAS_PROTEGIDAS_DE_PRUEBA (no un endpoint de
// diagnostico). POST /productos exige categoria_id valida (backend/server.js linea ~2680); se
// siembra una categoria minima por tenant via SQL directo, igual patron que mt1f3Sembrar.
// ==================================================================================

// Helper especifico de G5: UN UNICO usuario central U con membership real en A y en B (nunca dos
// usuarios). Preserva intacto mt1f4ConEscenario -- este helper es aditivo, no lo modifica.
async function mt1gCrearUsuarioDualMembership(controlDbPath, tenantA, tenantB, password) {
  const control = await bootstrapControlDb(controlDbPath, { seed: false });
  try {
    const localA = (await allSql(tenantA.dbPath, "SELECT * FROM usuarios WHERE usuario = 'admin'"))[0];
    const localB = (await allSql(tenantB.dbPath, "SELECT * FROM usuarios WHERE usuario = 'admin'"))[0];
    const central = await crearUsuarioCentral(control, {
      nombre: "MT1G Dual",
      usuarioReferencia: "admin",
      passwordHash: await bcrypt.hash(password, 10),
      activo: 1
    });
    const membershipA = await crearMembership(control, { usuarioId: central.id, empresaId: tenantA.empresa.id, usuarioLocalId: localA.id, rol: "admin", activo: 1 });
    const membershipB = await crearMembership(control, { usuarioId: central.id, empresaId: tenantB.empresa.id, usuarioLocalId: localB.id, rol: "admin", activo: 1 });
    return { central, membershipA, membershipB };
  } finally {
    await closeControlDb(control);
  }
}

async function mt1gSembrarCategoriaMinima(dbPath, nombre) {
  await runSql(dbPath, "INSERT INTO categorias (nombre, margen_porcentaje, maneja_stock, usa_costos_varios, activo) VALUES (?, 0, 0, 0, 1)", [nombre]);
  return (await allSql(dbPath, "SELECT id FROM categorias WHERE nombre = ?", [nombre]))[0];
}

// G1: lectura autenticada de negocio real (GET /productos) contra el Host de B usando un token
// valido SOLO en A. Debe rechazarse con el contrato uniforme (401, no-enumerable), sin filtrar
// ningun dato de B, y sin mutar ninguna de las dos bases.
async function testMT1G1LecturaAutenticadaCrossTenantDenegada() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir, loginTenant }) => {
    await mt1f3Sembrar(escenario);
    const tokenA = await loginTenant(a);

    const legitimo = await pedir(a, "GET", "/productos", null, tokenA);
    assertEqual(legitimo.status, 200, `el acceso legitimo de A a sus propios productos debe funcionar: ${legitimo.texto}`);
    assertSame(Array.isArray(legitimo.json) && legitimo.json.some((p) => p.nombre === "Producto A"), true, "A ve su propio producto sembrado");

    const productosBAntes = await allSql(b.dbPath, "SELECT * FROM productos");
    const sesionesBAntes = await allSql(b.dbPath, "SELECT * FROM sesiones");

    const cruzado = await pedir(b, "GET", "/productos", null, tokenA);
    assertSame(mt1f3EsNoAutenticado(cruzado), true, `el token de A debe ser rechazado contra el Host de B con el contrato uniforme (status=${cruzado.status} ${cruzado.texto.slice(0, 150)})`);
    assertSame(JSON.stringify(cruzado.json).includes("Producto B"), false, "la respuesta rechazada no debe filtrar ningun dato de negocio de B");

    const productosBDespues = await allSql(b.dbPath, "SELECT * FROM productos");
    const sesionesBDespues = await allSql(b.dbPath, "SELECT * FROM sesiones");
    assertEqual(productosBDespues.length, productosBAntes.length, "B no debe sufrir ninguna mutacion de productos por el intento de lectura rechazado");
    assertEqual(sesionesBDespues.length, sesionesBAntes.length, "B no debe registrar ninguna sesion nueva por el intento rechazado");
    assertSame(productosBDespues[0]?.nombre, "Producto B", "el unico producto de B sigue siendo exactamente el sembrado, sin alteracion");
  });
}

// G2: escritura autenticada de negocio real (POST /productos) contra el Host de B usando un token
// valido SOLO en A. Primero demuestra que la MISMA operacion esta legitimamente autorizada en A.
async function testMT1G2EscrituraAutenticadaCrossTenantDenegada() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir, loginTenant }) => {
    await mt1f3Sembrar(escenario);
    const categoriaA = await mt1gSembrarCategoriaMinima(a.dbPath, "MT1G2 Categoria");
    const tokenA = await loginTenant(a);

    const cuerpoLegitimo = { nombre: "MT1G2 Producto Legitimo A", categoria_id: categoriaA.id, precio_compra: 10, precio_venta: 50, maneja_stock: 0, activo: 1 };
    const legitimo = await pedir(a, "POST", "/productos", cuerpoLegitimo, tokenA);
    assertSame(legitimo.status >= 200 && legitimo.status < 300, true, `la escritura legitima de A debe estar autorizada (status=${legitimo.status} ${legitimo.texto.slice(0, 150)})`);
    const productosAAntes = await allSql(a.dbPath, "SELECT * FROM productos");
    assertSame(productosAAntes.some((p) => p.nombre === "MT1G2 Producto Legitimo A"), true, "el producto legitimo de A quedo persistido en la DB de A");

    const productosBAntes = await allSql(b.dbPath, "SELECT * FROM productos");
    const sesionesBAntes = await allSql(b.dbPath, "SELECT * FROM sesiones");

    const cuerpoCruzado = { nombre: "MT1G2 Producto Cruzado", categoria_id: categoriaA.id, precio_compra: 10, precio_venta: 50, maneja_stock: 0, activo: 1 };
    const cruzado = await pedir(b, "POST", "/productos", cuerpoCruzado, tokenA);
    assertSame(mt1f3EsNoAutenticado(cruzado), true, `la escritura cruzada contra B con token de A debe ser rechazada con el contrato uniforme (status=${cruzado.status} ${cruzado.texto.slice(0, 150)})`);

    // No se verifican caja/ventas por separado: POST /productos (backend/server.js) inserta
    // exclusivamente en la tabla `productos` -- no existe ningun camino de codigo en ese handler
    // hacia caja_movimientos/ventas, asi que "sin efectos secundarios en stock/caja/ventas" queda
    // estructuralmente garantizado por la eleccion del endpoint, no por una asercion adicional sobre
    // tablas que este endpoint no toca.
    const productosBDespues = await allSql(b.dbPath, "SELECT * FROM productos");
    const sesionesBDespues = await allSql(b.dbPath, "SELECT * FROM sesiones");
    assertEqual(productosBDespues.length, productosBAntes.length, "B no debe ganar ninguna fila de producto por el intento rechazado");
    assertEqual(sesionesBDespues.length, sesionesBAntes.length, "B no debe ganar ninguna sesion por el intento rechazado");
    assertSame(productosBDespues.every((p) => p.nombre !== "MT1G2 Producto Cruzado"), true, "el producto del intento cruzado nunca debe aparecer en B");

    const productosADespues = await allSql(a.dbPath, "SELECT * FROM productos");
    assertEqual(productosADespues.length, productosAAntes.length, "el estado protegido de A tampoco debe cambiar como consecuencia del intento rechazado contra B");
  });
}

// G5: un UNICO usuario central U, con membership real en A y en B. Atlas ata cada sesion a la DB de
// negocio del tenant resuelto por Host (arquitectura de subdominio + una business DB por tenant, con
// su propia tabla `sesiones`) -- se verifico por grep sobre backend/server.js que NO existe ningun
// endpoint de "cambiar de empresa dentro de una sesion" (cero coincidencias de switch/seleccion de
// empresa). El unico mecanismo real, coherente con esa arquitectura, es la autenticacion
// INDEPENDIENTE del MISMO usuario central en cada Host -- exactamente lo que este test demuestra.
// No se inventa una API de cambio de empresa dentro de sesion (opcion B de la seccion 7 del
// checkpoint): esa opcion no existe en el codigo actual, y se deja constancia explicita de ello aqui
// en vez de asumirla o de fabricarla.
async function testMT1G5UsuarioDualMembershipResuelveEmpresas() {
  const escenario = await mt1f1CrearEscenario(["a", "b"]);
  const decoyPath = tempDbPath();
  const password = "MT1G5-Dual-Pass-123!";
  try {
    await mt1f3Sembrar(escenario);
    const [tenantA, tenantB] = escenario.tenants;
    const { central, membershipA, membershipB } = await mt1gCrearUsuarioDualMembership(escenario.controlDbPath, tenantA, tenantB, password);
    assertSame(membershipA.usuario_id === central.id && membershipB.usuario_id === central.id, true, "ambas memberships deben pertenecer exactamente al mismo usuario central U");
    assertSame(membershipA.empresa_id !== membershipB.empresa_id, true, "las dos memberships deben apuntar a empresas distintas");

    await mt1f3ConServidor(mt1f3EntornoMulti(escenario, decoyPath), async (servidor) => {
      const loginEn = (tenant) => mt1f3Pedir(servidor.port, { host: mt1f3Host(tenant), metodo: "POST", ruta: "/login", cuerpo: { usuario: "admin", password } });
      const pedirEn = (tenant, token) => mt1f3Pedir(servidor.port, { host: mt1f3Host(tenant), ruta: "/productos", autorizacion: `Bearer ${token}` });

      const loginA = await loginEn(tenantA);
      assertEqual(loginA.status, 200, `U debe poder autenticarse en A: ${loginA.texto}`);
      const tokenA = loginA.json.token;
      const sesionA = (await allSql(tenantA.dbPath, "SELECT * FROM sesiones WHERE token = ?", [tokenA]))[0];
      assertEqual(sesionA.empresa_id, tenantA.empresa.id, "la sesion en A debe quedar ligada a la identidad de empresa A");
      assertEqual(sesionA.membership_id, membershipA.id, "la sesion en A debe usar exactamente la membership de A");
      assertEqual(sesionA.central_id, central.id, "la sesion en A debe pertenecer al usuario central U");

      const productosDesdeA = await pedirEn(tenantA, tokenA);
      assertEqual(productosDesdeA.status, 200, "U autorizado debe poder consultar productos de A");
      assertSame(productosDesdeA.json.some((p) => p.nombre === "Producto A"), true, "U debe ver el producto de A");
      assertSame(productosDesdeA.json.some((p) => p.nombre === "Producto B"), false, "U no debe ver el producto de B mientras opera sobre A");

      const loginB = await loginEn(tenantB);
      assertEqual(loginB.status, 200, `el MISMO usuario U debe poder autenticarse independientemente en B: ${loginB.texto}`);
      const tokenB = loginB.json.token;
      assertSame(tokenB !== tokenA, true, "cada autenticacion debe emitir un token propio: sesiones independientes por tenant");
      const sesionB = (await allSql(tenantB.dbPath, "SELECT * FROM sesiones WHERE token = ?", [tokenB]))[0];
      assertEqual(sesionB.empresa_id, tenantB.empresa.id, "la sesion en B debe quedar ligada a la identidad de empresa B");
      assertEqual(sesionB.membership_id, membershipB.id, "la sesion en B debe usar exactamente la membership de B");
      assertEqual(sesionB.central_id, central.id, "la sesion en B debe pertenecer al MISMO usuario central U");

      const productosDesdeB = await pedirEn(tenantB, tokenB);
      assertEqual(productosDesdeB.status, 200, "U autorizado debe poder consultar productos de B");
      assertSame(productosDesdeB.json.some((p) => p.nombre === "Producto B"), true, "U debe ver el producto de B");
      assertSame(productosDesdeB.json.some((p) => p.nombre === "Producto A"), false, "U no debe ver el producto de A mientras opera sobre B");

      const tokenAContraB = await mt1f3Pedir(servidor.port, { host: mt1f3Host(tenantB), ruta: "/productos", autorizacion: `Bearer ${tokenA}` });
      assertSame(mt1f3EsNoAutenticado(tokenAContraB), true, "el token de la sesion de A no debe autorizar en B, ni siquiera siendo el mismo usuario U");
      const tokenBContraA = await mt1f3Pedir(servidor.port, { host: mt1f3Host(tenantA), ruta: "/productos", autorizacion: `Bearer ${tokenB}` });
      assertSame(mt1f3EsNoAutenticado(tokenBContraA), true, "el token de la sesion de B no debe autorizar en A, ni siquiera siendo el mismo usuario U");

      assertSame(servidor.salio(), null, "el servidor debe permanecer vivo durante todo el escenario dual-membership");
    });
  } finally {
    await mt1f1Limpiar(escenario);
  }
}

// G7: concurrencia AUTENTICADA real -- login previo (fuera de la medicion), luego lecturas y
// escrituras intercaladas via Promise.all sobre las 2 DBs. Mismo patron de intercalado real que
// testMT1F3ConcurrenteRequestARequestBAisladas, pero con tokens autenticados y endpoints de negocio
// protegidos en vez de la tienda publica.
async function testMT1G7ConcurrenteAutenticadoAislado() {
  await mt1f4ConEscenario(async ({ escenario, a, b, pedir, loginTenant }) => {
    await mt1f3Sembrar(escenario);
    const categoriaA = await mt1gSembrarCategoriaMinima(a.dbPath, "MT1G7 Categoria");
    const categoriaB = await mt1gSembrarCategoriaMinima(b.dbPath, "MT1G7 Categoria");
    const tokenA = await loginTenant(a);
    const tokenB = await loginTenant(b);

    const operaciones = [];
    for (let indice = 0; indice < 10; indice += 1) {
      const esA = indice % 2 === 0;
      const tenant = esA ? a : b;
      const token = esA ? tokenA : tokenB;
      const categoriaId = esA ? categoriaA.id : categoriaB.id;
      const etiqueta = esA ? "A" : "B";
      const ajeno = esA ? "Producto B" : "Producto A";
      operaciones.push(
        pedir(tenant, "GET", "/productos", null, token).then((respuesta) => ({ tipo: "lectura", respuesta, etiqueta, ajeno }))
      );
      operaciones.push(
        pedir(tenant, "POST", "/productos", { nombre: `MT1G7 ${etiqueta} ${indice}`, categoria_id: categoriaId, precio_compra: 1, precio_venta: 2, maneja_stock: 0, activo: 1 }, token)
          .then((respuesta) => ({ tipo: "escritura", respuesta, etiqueta, indice }))
      );
    }
    const resultados = await Promise.all(operaciones);

    for (const resultado of resultados) {
      if (resultado.tipo === "lectura") {
        assertEqual(resultado.respuesta.status, 200, `lectura concurrente autenticada de ${resultado.etiqueta} debe responder 200`);
        assertSame(resultado.respuesta.json.some((p) => p.nombre === `Producto ${resultado.etiqueta}`), true, `lectura concurrente de ${resultado.etiqueta} debe ver su propio producto`);
        assertSame(resultado.respuesta.json.some((p) => p.nombre === resultado.ajeno), false, `lectura concurrente de ${resultado.etiqueta} jamas debe ver ${resultado.ajeno}`);
      } else {
        assertSame(resultado.respuesta.status >= 200 && resultado.respuesta.status < 300, true, `escritura concurrente autenticada ${resultado.etiqueta}#${resultado.indice} debe registrarse (status=${resultado.respuesta.status} ${resultado.respuesta.texto.slice(0, 100)})`);
      }
    }

    const productosA = await allSql(a.dbPath, "SELECT nombre FROM productos WHERE nombre LIKE 'MT1G7 A %'");
    const productosB = await allSql(b.dbPath, "SELECT nombre FROM productos WHERE nombre LIKE 'MT1G7 B %'");
    assertEqual(productosA.length, 5, "A debe recibir exactamente sus 5 escrituras concurrentes autenticadas");
    assertEqual(productosB.length, 5, "B debe recibir exactamente sus 5 escrituras concurrentes autenticadas");
    const cruceEnA = await allSql(a.dbPath, "SELECT nombre FROM productos WHERE nombre LIKE 'MT1G7 B %'");
    const cruceEnB = await allSql(b.dbPath, "SELECT nombre FROM productos WHERE nombre LIKE 'MT1G7 A %'");
    assertEqual(cruceEnA.length, 0, "ninguna escritura concurrente de B debe contaminar la DB de A");
    assertEqual(cruceEnB.length, 0, "ninguna escritura concurrente de A debe contaminar la DB de B");
  });
}

// PRODUCT-CODE-D1: regresion dirigida a la condicion de carrera demostrada en MT-1G-R2 -- codigos
// automaticos de producto bajo escritura concurrente REAL dentro del MISMO tenant. Deliberadamente
// en modo single (no requiere el fixture A/B de MT-1G): el defecto es intra-tenant, ortogonal al
// aislamiento multi-tenant, y single mode es el fixture minimo ya establecido en este harness para
// ejercitar POST /productos con servidor y autenticacion reales.
async function testProductoCodigoAutomaticoConcurrenteMismoTenant() {
  const dbPath = bootstrapFreshTestDb();
  try {
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      await runSql(dbPath, "INSERT INTO categorias (nombre, margen_porcentaje, maneja_stock, usa_costos_varios, activo) VALUES ('PRODCODE Categoria', 0, 0, 0, 1)");
      const categoria = (await allSql(dbPath, "SELECT id FROM categorias WHERE nombre = 'PRODCODE Categoria'"))[0];

      const TOTAL = 5;
      const creaciones = [];
      for (let indice = 0; indice < TOTAL; indice += 1) {
        creaciones.push(requestJson(baseUrl, "POST", "/productos", {
          nombre: `PRODCODE Concurrente ${indice}`,
          categoria_id: categoria.id,
          precio_compra: 1,
          precio_venta: 2,
          maneja_stock: 0,
          activo: 1
        }, token));
      }
      const resultados = await Promise.all(creaciones);

      resultados.forEach(({ response, data }, indice) => {
        assertSame(response.status >= 200 && response.status < 300, true, `creacion concurrente #${indice} debe terminar correctamente, sin 500 por colision (status=${response.status} ${JSON.stringify(data)})`);
      });

      const productos = await allSql(dbPath, "SELECT nombre, codigo FROM productos WHERE nombre LIKE 'PRODCODE Concurrente %'");
      assertEqual(productos.length, TOTAL, `deben crearse exactamente los ${TOTAL} productos solicitados`);
      for (const producto of productos) {
        assertSame(typeof producto.codigo === "string" && producto.codigo.trim().length > 0, true, `el producto "${producto.nombre}" debe tener un codigo automatico valido (no vacio)`);
      }
      const codigosUnicos = new Set(productos.map((p) => p.codigo));
      assertEqual(codigosUnicos.size, TOTAL, "todos los codigos generados deben ser distintos dentro de la misma base");

      // Creacion secuencial posterior: debe seguir funcionando y conservar el formato habitual
      // (PREFIJO de 3 letras derivado de la categoria + 3 digitos), sin repetir ningun codigo ya usado.
      const secuencial = await requestJson(baseUrl, "POST", "/productos", {
        nombre: "PRODCODE Secuencial",
        categoria_id: categoria.id,
        precio_compra: 1,
        precio_venta: 2,
        maneja_stock: 0,
        activo: 1
      }, token);
      assertSame(secuencial.response.status >= 200 && secuencial.response.status < 300, true, `la creacion secuencial posterior debe funcionar (status=${secuencial.response.status} ${JSON.stringify(secuencial.data)})`);
      const productoSecuencial = (await allSql(dbPath, "SELECT codigo FROM productos WHERE nombre = 'PRODCODE Secuencial'"))[0];
      assertSame(/^[A-Z]{3}\d{3}$/.test(productoSecuencial.codigo), true, `el codigo secuencial debe conservar el formato habitual PREFIJO+3digitos: "${productoSecuencial.codigo}"`);
      assertSame(codigosUnicos.has(productoSecuencial.codigo), false, "el codigo secuencial tampoco debe repetir ninguno de los generados concurrentemente");
    });
  } finally {
    fs.rmSync(dbPath, { force: true });
  }
}

// ==================================================================================
// PRODUCT-CODE-D2: prueba DETERMINISTA (no probabilistica) de que POST /productos recupera una
// colision UNIQUE real sobre productos.codigo durante el INSERT. Instrumentacion exclusivamente de
// prueba, cargada via NODE_OPTIONS=--require en un proceso hijo descartable dedicado a este test
// unicamente -- mismo patron ya establecido y certificado por F5C3 (MT1F5C3_MOCK_FETCH_SOURCE).
// No modifica backend/server.js ni backend/db.js. No afecta ninguna otra prueba: el hook solo
// intercepta el INSERT cuyo primer parametro (nombre) coincide con un marcador unico generado por
// esta prueba, y solo la PRIMERA vez que lo ve.
//
// Mecanismo: intercepta sqlite3.Database.prototype.run dentro del proceso hijo. Al ver el INSERT
// marcado, inserta -- ANTES de dejarlo pasar -- una fila "decoy" con el MISMO codigo que el servidor
// esta por usar (extraido dinamicamente de los parametros posicionales del propio INSERT, sin
// asumir un indice fijo). Esto garantiza que el INSERT real choque contra
// idx_productos_codigo_unique (indice UNICO parcial: database/business-schema-baseline.js,
// "WHERE codigo IS NOT NULL AND codigo != '' AND eliminado = 0") -- el error SQLITE_CONSTRAINT
// resultante es real, generado por el motor, no simulado. La restauracion del entorno no requiere
// desmontar el monkeypatch dentro del proceso: el hijo entero se mata y sus archivos temporales se
// borran en el finally (identico al patron ya usado por mt1f5c3ConServidorCapturaLogs), por lo que
// ninguna otra prueba (que siempre spawnea su propio proceso hijo nuevo) puede verse afectada.
//
// NOTA: require("sqlite3") desde un archivo en os.tmpdir() no resolveria el mismo modulo que usa
// backend/db.js (no hay node_modules ahi). Se usa module.createRequire anclado al package.json real
// del proyecto para garantizar que ambos requires devuelvan la MISMA instancia de modulo cacheada
// -- imprescindible para que el monkeypatch del prototipo afecte a las conexiones que abre db.js.
const MT1PRODCODE_MOCK_SOURCE = `
const path = require("path");
const fs = require("fs");
const { createRequire } = require("module");
const requireDelProyecto = createRequire(process.env.PRODCODE_PACKAGE_JSON);
const sqlite3 = requireDelProyecto("sqlite3").verbose();

const MARCADOR = process.env.PRODCODE_MARCADOR;
const diagPath = process.env.PRODCODE_DIAG_PATH;
let decoyDisparado = false;
let intentosVistos = 0;

function diag(entrada) {
  try { fs.appendFileSync(diagPath, JSON.stringify(Object.assign({ en: new Date().toISOString() }, entrada)) + "\\n"); } catch (e) {}
}

function indiceColumnaCodigo(sql) {
  const inicio = sql.indexOf("(");
  const fin = sql.indexOf(")", inicio);
  const columnas = sql.slice(inicio + 1, fin).split(",").map(function (c) { return c.trim(); });
  return columnas.indexOf("codigo");
}

const runOriginal = sqlite3.Database.prototype.run;
sqlite3.Database.prototype.run = function (sql, ...resto) {
  const params = Array.isArray(resto[0]) ? resto[0] : null;
  const esInsertMarcado = typeof sql === "string" && sql.indexOf("INSERT INTO productos") !== -1 && params && params[0] === MARCADOR;
  if (esInsertMarcado) {
    intentosVistos += 1;
    const idxCodigo = indiceColumnaCodigo(sql);
    const codigoIntento = idxCodigo >= 0 ? params[idxCodigo] : undefined;
    diag({ evento: "insert_intento", intento: intentosVistos, codigo: codigoIntento });

    if (!decoyDisparado) {
      decoyDisparado = true;
      const conexion = this;
      const argsOriginales = resto;
      conexion.run(
        "INSERT INTO productos (nombre, codigo) VALUES ('__PRODCODE_D2_DECOY__', ?)",
        [codigoIntento],
        function (errDecoy) {
          diag({ evento: "decoy_insertado", ok: !errDecoy, error: errDecoy ? String(errDecoy.message) : null });
          runOriginal.call(conexion, sql, ...argsOriginales);
        }
      );
      return conexion;
    }
  }
  return runOriginal.call(this, sql, ...resto);
};
`;

function mt1prodcodeEscribirMock() {
  const mockPath = path.join(os.tmpdir(), `prodcode-mock-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}.js`);
  fs.writeFileSync(mockPath, MT1PRODCODE_MOCK_SOURCE, "utf8");
  return mockPath;
}

async function mt1prodcodeConServidorInstrumentado(dbPath, fn, { marcador, diagPath }) {
  const port = await getFreePort();
  const baseUrl = `http://localhost:${port}`;
  const mockPath = mt1prodcodeEscribirMock();
  const baseEnv = { ...process.env };
  delete baseEnv.ATLAS_AUTH_MODE;
  delete baseEnv.ATLAS_EMPRESA_SLUG;
  delete baseEnv.ATLAS_CONTROL_DB_PATH;
  delete baseEnv.ATLAS_TENANCY_MODE;
  // MT-1F5C3: NODE_OPTIONS mangla backslashes en Windows -- normalizar a forward slashes.
  const requirePath = mockPath.replace(/\\/g, "/");
  const child = spawn(process.execPath, ["backend/server.js"], {
    cwd: ROOT,
    env: {
      ...baseEnv, PORT: String(port), GUERNICA_DB_PATH: dbPath,
      NODE_OPTIONS: `--require "${requirePath}"`,
      PRODCODE_MARCADOR: marcador,
      PRODCODE_DIAG_PATH: diagPath,
      PRODCODE_PACKAGE_JSON: path.join(ROOT, "package.json")
    },
    stdio: ["ignore", "pipe", "pipe"]
  });
  let logs = "";
  child.stdout.on("data", (chunk) => { logs += chunk.toString(); });
  child.stderr.on("data", (chunk) => { logs += chunk.toString(); });
  try {
    await waitForServer(baseUrl);
    await fn(baseUrl);
  } catch (error) {
    error.message = `${error.message}\nServidor test pid=${child.pid} port=${port}\n${logs}`;
    throw error;
  } finally {
    if (!child.killed) child.kill("SIGTERM");
    await new Promise((resolve) => {
      const timer = setTimeout(resolve, 1000);
      child.once("exit", () => { clearTimeout(timer); resolve(); });
    });
    if (child.exitCode === null && !child.killed) child.kill("SIGKILL");
    fs.rmSync(mockPath, { force: true });
  }
}

function mt1prodcodeLeerDiag(diagPath) {
  if (!fs.existsSync(diagPath)) return [];
  return fs.readFileSync(diagPath, "utf8").split("\n").filter(Boolean).map((linea) => JSON.parse(linea));
}

async function testProductoCodigoAutomaticoReintentoDeterminista() {
  const dbPath = bootstrapFreshTestDb();
  const marcador = `PRODCODE-DETERMINISTA-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  const diagPath = path.join(os.tmpdir(), `prodcode-diag-${process.pid}-${Date.now()}-${Math.random().toString(16).slice(2)}.jsonl`);
  fs.writeFileSync(diagPath, "");
  try {
    await mt1prodcodeConServidorInstrumentado(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", "admin123");
      await runSql(dbPath, "INSERT INTO categorias (nombre, margen_porcentaje, maneja_stock, usa_costos_varios, activo) VALUES ('PRODCODE-D2 Categoria', 0, 0, 0, 1)");
      const categoria = (await allSql(dbPath, "SELECT id FROM categorias WHERE nombre = 'PRODCODE-D2 Categoria'"))[0];

      const { response, data } = await requestJson(baseUrl, "POST", "/productos", {
        nombre: marcador,
        categoria_id: categoria.id,
        precio_compra: 5,
        precio_venta: 10,
        maneja_stock: 0,
        activo: 1,
        observaciones: "PRODCODE-D2 datos de negocio"
      }, token);

      assertEqual(response.status, 200, `la creacion final debe terminar correctamente tras el reintento (status=${response.status} ${JSON.stringify(data)})`);
      assertSame(typeof data?.id === "number", true, "la respuesta debe incluir el id del producto creado");
    }, { marcador, diagPath });

    const trazas = mt1prodcodeLeerDiag(diagPath);
    const intentos = trazas.filter((t) => t.evento === "insert_intento");
    const decoy = trazas.filter((t) => t.evento === "decoy_insertado");

    assertEqual(intentos.length, 2, `deben observarse exactamente 2 intentos de INSERT para el marcador -- la colision inducida y el reintento (traza=${JSON.stringify(trazas)})`);
    assertEqual(decoy.length, 1, "el decoy debe insertarse exactamente una vez");
    assertSame(decoy[0].ok, true, "el INSERT del decoy (la fila que provoca la colision) debe haberse completado con exito");
    assertSame(typeof intentos[0].codigo === "string" && intentos[0].codigo.length > 0, true, "el primer intento debe llevar un codigo automatico no vacio");
    assertSame(typeof intentos[1].codigo === "string" && intentos[1].codigo.length > 0, true, "el segundo intento (reintento) debe llevar un codigo automatico no vacio");
    assertSame(intentos[0].codigo !== intentos[1].codigo, true, "el reintento debe haber generado un codigo DISTINTO al que colisiono");

    const productos = await allSql(dbPath, "SELECT * FROM productos WHERE nombre = ?", [marcador]);
    assertEqual(productos.length, 1, "debe existir EXACTAMENTE un producto final persistido con el nombre solicitado, sin duplicados por el reintento");
    assertSame(productos[0].codigo, intentos[1].codigo, "el codigo final persistido debe ser el del segundo intento (el que tuvo exito)");
    assertSame(productos[0].codigo !== intentos[0].codigo, true, "el producto final NUNCA debe quedar con el codigo que colisiono");
    assertEqual(Number(productos[0].precio_compra), 5, "los datos de negocio (precio_compra) se conservan en el producto final");
    assertEqual(Number(productos[0].precio_venta), 10, "los datos de negocio (precio_venta) se conservan en el producto final");
    assertSame(productos[0].observaciones, "PRODCODE-D2 datos de negocio", "los datos de negocio (observaciones) se conservan en el producto final");

    // No se duplican operaciones posteriores al INSERT exitoso: registrarCambiosProducto siempre
    // registra el campo 'nombre' exactamente una vez por creacion (motivo='creacion'); si el bucle
    // de reintento repitiera pasos posteriores al INSERT exitoso, este conteo seria 2.
    const historialNombre = await allSql(
      dbPath,
      "SELECT * FROM historial_productos WHERE producto_id = ? AND campo_modificado = 'nombre' AND motivo = 'creacion'",
      [productos[0].id]
    );
    assertEqual(historialNombre.length, 1, "el registro de historial de creacion no debe duplicarse -- confirma que las operaciones posteriores al INSERT exitoso se ejecutaron una sola vez");
  } finally {
    fs.rmSync(dbPath, { force: true });
    fs.rmSync(diagPath, { force: true });
  }
}

// AUTH-SYNC-B2-P1A: password central-first. Cobertura de los 36 escenarios exigidos por el
// checkpoint de implementacion -- commit central antes que local, CAS/conflicto, fan-out a TODAS
// las memberships, backfill del consumer dedicado, semantica per-fila del consumer, proteccion del
// reconciliador via el marker global (nunca escribe sync_pendiente), preservacion legacy/pre-S0, y
// aislamiento cross-tenant. Ningun test preexistente se modifica.

async function testP1ACentralFirstHappyPathConvergeYLoginAceptaNueva() {
  const dbPath = bootstrapFreshRegisteredTenantDb();
  let controlDbPath;
  try {
    const fixture = await setupCentralFixture({ businessDbPath: dbPath });
    controlDbPath = fixture.controlDbPath;
    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", fixture.centralPassword);
      const { response, data } = await requestJson(baseUrl, "PATCH", `/usuarios/${fixture.localUserId}/password`, {
        password: "NuevaCentralFirst1", confirmar_password: "NuevaCentralFirst1"
      }, token, nuevaIdempotencyKeyHeader());
      assertEqual(response.status, 200, `PATCH password central-first happy path debe dar 200 (status=${response.status} ${JSON.stringify(data)})`);
      assertSame(data.message, "Contraseña actualizada correctamente", "mensaje de exito central-first debe ser el nuevo texto conceptual");
      assertSame(data.sincronizacion_shadow, "procesada", "la proyeccion inline del tenant actual debe completarse en el happy path");
      if (JSON.stringify(data).toLowerCase().includes("hash")) {
        throw new Error("la respuesta no debe exponer ningun hash");
      }

      const loginNuevo = await requestJson(baseUrl, "POST", "/login", { usuario: "admin", password: "NuevaCentralFirst1" }, null);
      assertEqual(loginNuevo.response.status, 200, "login central debe aceptar la nueva password inmediatamente");
      const loginViejo = await requestJson(baseUrl, "POST", "/login", { usuario: "admin", password: fixture.centralPassword }, null);
      assertEqual(loginViejo.response.status, 401, "login central debe rechazar la password vieja tras el cambio");
    }, extraEnvCentral(fixture));

    const localDespues = (await allSql(dbPath, "SELECT password FROM usuarios WHERE id = ?", [fixture.localUserId]))[0];
    assertSame(await bcrypt.compare("NuevaCentralFirst1", localDespues.password), true, "la Business DB local debe terminar reflejando la nueva password (proyectada inline)");

    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const central = await getControlQuery(controlDb, "SELECT password_hash, version FROM usuarios WHERE id = ?", [fixture.central.id]);
      assertSame(await bcrypt.compare("NuevaCentralFirst1", central.password_hash), true, "central.password_hash debe ser la nueva password");
      assertEqual(Number(central.version), 1, "version central debe haberse incrementado exactamente en 1");
      const fila = await getControlQuery(controlDb, "SELECT estado, version_objetivo FROM sync_pendiente WHERE membership_id = ? AND tipo_operacion = 'password'", [fixture.membership.id]);
      assertSame(fila.estado, "procesado", "la fila de outbox del tenant actual debe quedar procesada tras la proyeccion inline");
      assertEqual(Number(fila.version_objetivo), 1, "version_objetivo de la fila cerrada debe ser la nueva version central");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    limpiarTenantTestDb(dbPath);
    if (controlDbPath) fs.rmSync(controlDbPath, { force: true });
  }
}

async function testP1AConflictoCasDejaLocalIntactoYNoRevierteCentral() {
  const dbPath = bootstrapFreshRegisteredTenantDb();
  let controlDbPath;
  try {
    const fixture = await setupCentralFixture({ businessDbPath: dbPath });
    controlDbPath = fixture.controlDbPath;

    const primero = await userControlBridge.actualizarPasswordCentralFirst({
      usuarioCentralId: fixture.central.id, expectedVersion: 0,
      passwordHash: await bcrypt.hash("PrimeraGanadora1", 10), controlDbPath
    });
    assertSame(primero.ok, true, "el primer commit con expectedVersion correcto debe confirmar");

    const segundo = await userControlBridge.actualizarPasswordCentralFirst({
      usuarioCentralId: fixture.central.id, expectedVersion: 0,
      passwordHash: await bcrypt.hash("SegundaPerdedora1", 10), controlDbPath
    });
    assertSame(segundo.ok, false, "un segundo commit con el mismo expectedVersion ya obsoleto debe fallar CAS");
    assertSame(segundo.errorCode, "VERSION_CONFLICT", "el error de CAS debe ser VERSION_CONFLICT");
    assertEqual(segundo.versionActual, 1, "versionActual reportada debe ser la version real vigente");

    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const central = await getControlQuery(controlDb, "SELECT password_hash FROM usuarios WHERE id = ?", [fixture.central.id]);
      assertSame(await bcrypt.compare("PrimeraGanadora1", central.password_hash), true, "central debe conservar el password del commit ganador, nunca el perdedor");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    limpiarTenantTestDb(dbPath);
    if (controlDbPath) fs.rmSync(controlDbPath, { force: true });
  }
}

async function testP1AHttpPreS0FalloClosedBusinessDbIntacta() {
  const dbPath = bootstrapFreshRegisteredTenantDb();
  const controlDbPath = tempDbPath();
  try {
    const localAdmin = (await allSql(dbPath, "SELECT id, password FROM usuarios WHERE usuario = ?", ["admin"]))[0];
    const dbVieja = await authSyncB2S0CrearControlDbEsquemaViejo(controlDbPath);
    const empresaSlug = `p1a-http-preS0-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(dbVieja, { slug: empresaSlug, nombre: "P1A HTTP Pre-S0", dbPath: path.basename(dbPath) });
    const centralHashViejo = await bcrypt.hash("CentralPreS0Http1", 10);
    const central = await crearUsuarioCentral(dbVieja, { nombre: "P1A HTTP PreS0", usuarioReferencia: "admin", passwordHash: centralHashViejo, activo: 1 });
    await crearMembership(dbVieja, { usuarioId: central.id, empresaId: empresa.id, usuarioLocalId: localAdmin.id, rol: "admin", activo: 1 });
    await closeControlDb(dbVieja);
    await insertarTenantIdentityTest(dbPath, empresa.id, empresaSlug);

    // AUTH-SYNC-B2-P1A-SR-FIX: Session Revocation es OBLIGATORIA en runtime central -- un Control DB
    // pre-S0 (sin usuarios.password_version) ya no permite login central en absoluto (fail closed
    // ANTES de autenticar, ver autenticarCredencialCentral). Por lo tanto ya no es posible obtener
    // un token real para ejercer el endpoint PATCH password especificamente: el fail-closed ahora
    // cubre TODA la superficie de auth central, no solo esa ruta. Este test demuestra exactamente
    // eso -- ni el login ni ninguna escritura posterior son alcanzables.
    await withServer(dbPath, async (baseUrl) => {
      const { response, data } = await requestJson(baseUrl, "POST", "/login", { usuario: "admin", password: "CentralPreS0Http1" }, null);
      assertEqual(response.status, 503, "sin usuarios.password_version, el login central completo debe fallar cerrado, no solo el endpoint de password");
      assertSame(Object.prototype.hasOwnProperty.call(data || {}, "token"), false, "una respuesta 503 nunca debe incluir un token");
    }, {
      ATLAS_AUTH_MODE: "central", ATLAS_USER_BRIDGE_MODE: "shadow",
      ATLAS_EMPRESA_SLUG: empresaSlug, ATLAS_CONTROL_DB_PATH: controlDbPath
    });

    const localDespues = (await allSql(dbPath, "SELECT password FROM usuarios WHERE id = ?", [localAdmin.id]))[0];
    assertSame(localDespues.password, localAdmin.password, "Business DB debe quedar intacta cuando el esquema no soporta auth central");
    const controlDbFinal = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const centralDespues = await getControlQuery(controlDbFinal, "SELECT password_hash FROM usuarios WHERE id = ?", [central.id]);
      assertSame(centralDespues.password_hash, centralHashViejo, "central tampoco debe modificarse cuando falla cerrado por esquema incompatible");
    } finally {
      await closeControlDb(controlDbFinal);
    }
  } finally {
    limpiarTenantTestDb(dbPath);
    fs.rmSync(controlDbPath, { force: true });
  }
}

async function testP1AProyeccionInlineNoDisponibleRespondePendienteSinMensajeEnganosoYCentralYaCambio() {
  const dbPath = bootstrapFreshRegisteredTenantDb();
  let controlDbPath;
  try {
    const fixture = await setupCentralFixture({ businessDbPath: dbPath });
    controlDbPath = fixture.controlDbPath;

    await withServer(dbPath, async (baseUrl) => {
      const token = await login(baseUrl, "admin", fixture.centralPassword);

      // La corrupcion de empresa.db_path se hace DESPUES de que el servidor ya arranco (no antes):
      // validarTenantAntesDeAbrirDb() valida GUERNICA_DB_PATH contra el db_path registrado UNA SOLA
      // VEZ al bootear (backend/server.js:13086-13087), nunca por-request -- si se corrompe antes de
      // levantar el servidor, el boot mismo falla (fail-closed correcto, pero no es lo que este test
      // quiere ejercer). Corrompiendolo despues del boot solo afecta la lectura fresca que hace la
      // proyeccion inline del consumer al momento del PATCH, que es exactamente el escenario buscado.
      const controlDbPre = await bootstrapControlDb(controlDbPath, { seed: false });
      try {
        await runControlQuery(controlDbPre, "UPDATE empresas SET db_path = ? WHERE id = ?", ["p1a-inexistente-projection.db", fixture.empresa.id]);
      } finally {
        await closeControlDb(controlDbPre);
      }

      const { response, data } = await requestJson(baseUrl, "PATCH", `/usuarios/${fixture.localUserId}/password`, {
        password: "NuevaSinProyeccion1", confirmar_password: "NuevaSinProyeccion1"
      }, token, nuevaIdempotencyKeyHeader());
      assertEqual(response.status, 200, "aunque la proyeccion inline no pueda completarse, la respuesta debe seguir siendo 200 (central ya cambio)");
      assertSame(data.message, "Contraseña actualizada correctamente", "el mensaje de exito no debe cambiar aunque la proyeccion quede pendiente");
      assertSame(data.sincronizacion_shadow, "pendiente", "sin proyeccion inline exitosa, sincronizacion_shadow debe ser 'pendiente'");
      if (/intent[aá] de nuevo|volv[eé] a intentar/i.test(data.message)) {
        throw new Error("el mensaje de exito NO debe reutilizar wording que sugiera reintentar el cambio de password");
      }
    }, extraEnvCentral(fixture));

    const controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const central = await getControlQuery(controlDb, "SELECT password_hash FROM usuarios WHERE id = ?", [fixture.central.id]);
      assertSame(await bcrypt.compare("NuevaSinProyeccion1", central.password_hash), true, "central debe reflejar la nueva password aunque la proyeccion local inline haya quedado pendiente");
      const fila = await getControlQuery(controlDb, "SELECT estado FROM sync_pendiente WHERE membership_id = ? AND tipo_operacion = 'password'", [fixture.membership.id]);
      assertSame(fila.estado, "pendiente", "la fila de outbox debe quedar pendiente cuando la proyeccion inline no pudo completarse");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    limpiarTenantTestDb(dbPath);
    if (controlDbPath) fs.rmSync(controlDbPath, { force: true });
  }
}

async function testP1AControlDbAusenteNuncaSeCreaPorVerificacionNiPorDrenaje() {
  const controlDbPathInexistente = tempDbPath();
  try {
    assertSame(fs.existsSync(controlDbPathInexistente), false, "precondicion: el path de control db no debe existir todavia");
    const soporte = await p1aVerificarSoporteS0Standalone({ controlDbPath: controlDbPathInexistente });
    assertSame(soporte.soportaS0, false, "sin archivo, la verificacion de soporte S0 debe reportar false, nunca lanzar ni crear");
    assertSame(fs.existsSync(controlDbPathInexistente), false, "verificarSoporteS0Standalone NUNCA debe crear el archivo de control db");

    const drenaje = await p1aDrenarOutboxPassword({ controlDbPath: controlDbPathInexistente });
    assertSame(drenaje.ok, false, "drenarOutboxPassword sobre control db ausente debe fallar de forma controlada");
    assertSame(drenaje.errorCode, "CONTROL_DB_AUSENTE", "el codigo de error debe identificar la ausencia del control plane");
    assertSame(fs.existsSync(controlDbPathInexistente), false, "drenarOutboxPassword NUNCA debe crear el archivo de control db");
  } finally {
    fs.rmSync(controlDbPathInexistente, { force: true });
  }
}

async function testP1AReconcileMarkerGlobalProtegePasswordYNuncaEscribeSyncPendiente() {
  const businessDbPath = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    const admin = (await allSql(businessDbPath, "SELECT * FROM usuarios WHERE usuario = ?", ["admin"]))[0];
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const empresaSlug = `p1a-reconcile-marker-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresa = await registrarEmpresa(controlDb, { slug: empresaSlug, nombre: "P1A Reconcile Marker", dbPath: "guernica.db" });
    const centralHashVigente = await bcrypt.hash("CentralYaCambiadaXYZ1", 10);
    const central = await crearUsuarioCentral(controlDb, {
      nombre: admin.nombre, usuarioReferencia: admin.usuario, passwordHash: centralHashVigente, activo: 1
    });
    const membership = await crearMembership(controlDb, {
      usuarioId: central.id, empresaId: empresa.id, usuarioLocalId: admin.id, rol: admin.rol, activo: admin.activo
    });
    await runControlQuery(
      controlDb,
      `INSERT INTO sync_pendiente (usuario_id, empresa_id, membership_id, usuario_local_id, tipo_operacion, version_objetivo, estado, procesado_en)
       VALUES (?, ?, ?, ?, 'password', 1, 'procesado', datetime('now'))`,
      [central.id, empresa.id, membership.id, admin.id]
    );
    await closeControlDb(controlDb);

    const check = await reconcileShadowUsers({ empresaSlug, mode: "check", controlDbPath, businessDbPath });
    if (!check.ok) throw new Error(`CHECK marker password fallo: ${check.message}`);
    assertSame(check.usuarios[0].estados.includes("PASSWORD_PROTECTED_CENTRAL_FIRST"), true, "CHECK debe reportar PASSWORD_PROTECTED_CENTRAL_FIRST cuando existe el marker global");
    assertSame(check.usuarios[0].estados.includes("PASSWORD_MISMATCH"), false, "un mismatch protegido por el marker NUNCA debe clasificarse como PASSWORD_MISMATCH reparable");
    assertEqual(check.summary.protected_central, 1, "CHECK debe contar la proteccion de password");

    const controlDbCheckSnapshot = await bootstrapControlDb(controlDbPath, { seed: false });
    const syncPendienteAntes = await allControlQuery(controlDbCheckSnapshot, "SELECT * FROM sync_pendiente");
    await closeControlDb(controlDbCheckSnapshot);
    assertEqual(syncPendienteAntes.length, 1, "CHECK jamas debe escribir en sync_pendiente -- debe seguir habiendo exactamente la fila sembrada");

    const apply = await reconcileShadowUsers({ empresaSlug, mode: "apply", controlDbPath, businessDbPath });
    if (!apply.ok) throw new Error(`APPLY marker password fallo: ${apply.message}`);

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const centralDespues = await getControlQuery(controlDb, "SELECT password_hash FROM usuarios WHERE id = ?", [central.id]);
      assertSame(centralDespues.password_hash, centralHashVigente, "central.password_hash NUNCA debe revertirse al valor local stale mientras el marker exista");
      const syncPendienteDespues = await allControlQuery(controlDb, "SELECT * FROM sync_pendiente");
      assertEqual(syncPendienteDespues.length, 1, "APPLY tampoco debe escribir en sync_pendiente -- ni crear ni modificar filas, esa tabla es exclusiva del bridge/consumer");
      assertSame(syncPendienteDespues[0].estado, "procesado", "APPLY no debe alterar el estado de la fila existente");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbPath, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

async function testP1AMarkerGlobalProtegeMembershipSinFilaPropia() {
  const businessDbA = bootstrapFreshTestDb();
  const businessDbB = bootstrapFreshTestDb();
  const controlDbPath = tempDbPath();
  try {
    const adminA = (await allSql(businessDbA, "SELECT * FROM usuarios WHERE usuario = ?", ["admin"]))[0];
    const adminB = (await allSql(businessDbB, "SELECT * FROM usuarios WHERE usuario = ?", ["admin"]))[0];
    let controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    const slugA = `p1a-marker-sinfila-a-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const slugB = `p1a-marker-sinfila-b-${Date.now()}-${Math.random().toString(16).slice(2)}`;
    const empresaA = await registrarEmpresa(controlDb, { slug: slugA, nombre: "P1A Marker Sin Fila A", dbPath: "guernica.db" });
    const empresaB = await registrarEmpresa(controlDb, { slug: slugB, nombre: "P1A Marker Sin Fila B", dbPath: "guernica.db" });
    const centralHashVigente = await bcrypt.hash("CentralGlobalVigente1", 10);
    const central = await crearUsuarioCentral(controlDb, {
      nombre: "Usuario Multiempresa P1A", usuarioReferencia: "p1a-multiempresa", passwordHash: centralHashVigente, activo: 1
    });
    const membershipA = await crearMembership(controlDb, { usuarioId: central.id, empresaId: empresaA.id, usuarioLocalId: adminA.id, rol: "admin", activo: 1 });
    const membershipB = await crearMembership(controlDb, { usuarioId: central.id, empresaId: empresaB.id, usuarioLocalId: adminB.id, rol: "admin", activo: 1 });

    await runControlQuery(
      controlDb,
      `INSERT INTO sync_pendiente (usuario_id, empresa_id, membership_id, usuario_local_id, tipo_operacion, version_objetivo, estado)
       VALUES (?, ?, ?, ?, 'password', 1, 'pendiente')`,
      [central.id, empresaA.id, membershipA.id, adminA.id]
    );
    await closeControlDb(controlDb);

    const checkB = await reconcileShadowUsers({ empresaSlug: slugB, mode: "check", controlDbPath, businessDbPath: businessDbB });
    if (!checkB.ok) throw new Error(`CHECK empresa B fallo: ${checkB.message}`);
    assertSame(checkB.usuarios[0].estados.includes("PASSWORD_PROTECTED_CENTRAL_FIRST"), true, "el marker global (por usuario_id) debe proteger tambien a la membership B, aunque B no tenga fila propia en sync_pendiente");

    const applyB = await reconcileShadowUsers({ empresaSlug: slugB, mode: "apply", controlDbPath, businessDbPath: businessDbB });
    if (!applyB.ok) throw new Error(`APPLY empresa B fallo: ${applyB.message}`);

    controlDb = await bootstrapControlDb(controlDbPath, { seed: false });
    try {
      const centralDespues = await getControlQuery(controlDb, "SELECT password_hash FROM usuarios WHERE id = ?", [central.id]);
      assertSame(centralDespues.password_hash, centralHashVigente, "central no debe revertirse por B pese a que B no tiene fila propia en sync_pendiente");
      const filaB = await getControlQuery(controlDb, "SELECT id FROM sync_pendiente WHERE membership_id = ? AND tipo_operacion = 'password'", [membershipB.id]);
      assertSame(filaB, undefined, "APPLY no debe crear una fila de outbox para B -- el backfill es responsabilidad exclusiva del consumer, no del reconciliador");
    } finally {
      await closeControlDb(controlDb);
    }
  } finally {
    fs.rmSync(businessDbA, { force: true });
    fs.rmSync(businessDbB, { force: true });
    fs.rmSync(controlDbPath, { force: true });
  }
}

